## 2️⃣ Python

```python
import asyncio
import logging
from typing import Callable, Awaitable


async def retry(
    fn: Callable[[], Awaitable],
    max_attempts: int = 5,
    base_delay: float = 0.1,   # seconds
) -> None:
    """
    Retry an async function up to `max_attempts` times with exponential back‑off.

    :param fn: Async callable that returns a coroutine.
    :param max_attempts: Total attempts (first call + retries).
    :param base_delay: Initial delay in seconds before the first retry.
    """
    attempt = 0
    while True:
        try:
            return await fn()
        except Exception as exc:
            if attempt >= max_attempts - 1:   # last attempt already tried
                raise
            attempt += 1
            delay = base_delay * (2 ** (attempt - 1))
            logging.warning(
                f"Attempt {attempt}/{max_attempts} failed ({exc}); "
                f"retrying in {delay:.2f}s…"
            )
            await asyncio.sleep(delay)


# ----------------------------------------------------------------------
# Example usage ---------------------------------------------------------
if __name__ == "__main__":
    import random

    async def unreliable_fetch():
        # Simulate occasional failure
        if random.random() < 0.7:
            raise RuntimeError("random failure")
        return "OK"

    async def main():
        try:
            result = await retry(unreliable_fetch, max_attempts=4, base_delay=0.5)
            print(result)
        except Exception as e:
            print("All attempts failed:", e)

    asyncio.run(main())
```

