## 3️⃣ Go (Golang)

```go
package main

import (
	"context"
	"fmt"
	"math/rand"
	"time"
)

// Retry retries the given async function up to maxAttempts with exponential back‑off.
func retry(ctx context.Context, fn func() error, maxAttempts int, baseDelay time.Duration) error {
	attempt := 0
	for attempt < maxAttempts {
		if err := fn(); err == nil {
			return nil // success!
		}
		if attempt >= maxAttempts-1 { // last try → re‑throw
			return err
		}
		attempt++
		delay := baseDelay * time.Duration(1<<uint(attempt-1))
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
			time.Sleep(delay)
			fmt.Printf("Attempt %d/%d failed: %+v; retrying in %s…\n",
				attempt, maxAttempts, err, delay)
		}
	}
	return nil
}

// Example async function (simulating a network call):
func unreliableCall() error {
	if rand.Float64() < 0.7 { // 70% chance to fail
		return fmt.Errorf("random failure")
	}
	fmt.Println("Success!")
	return nil
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := retry(ctx, unreliableCall, 4, 200*time.Millisecond); err != nil {
		panic(err) // all attempts failed
	}
}
```

