## TypeScript (Node.js)

```ts
// lineReader.ts -------------------------------------------------------------
import { createReadStream } from 'fs';
import * as readline from 'readline';

/**
 * Stream a file line‑by‑line.
 *
 * @param path   Path to the text file.
 * @returns      An async iterator yielding each line (without newline chars).
 */
export function* readLines(path: string): AsyncIterable<string> {
  const rl = readline.createInterface({
    input: createReadStream(path, { encoding: 'utf8' }), // auto‑closes
    crlfDelay: Infinity,
  });

  for await (const line of rl) {
    yield line;               // yields one line at a time
  }
}

// Example usage -----------------------------------------------------------
(async () => {
  const filePath = './largeFile.txt';
  for await (const line of readLines(filePath)) {
    console.log(line);        // process each line here
  }
})();
```

*Why it works*: `readline.createInterface` reads from a readable stream (`createReadStream`) and yields one chunk at a time, keeping memory usage constant.

