Below are three self‑contained implementations – one for **TypeScript**, one for **Python**, and one for **Go** – that perform a *deep* merge of two plain JavaScript/JSON objects (`Object` / `dict`).  
When the same key exists in both source objects, the value from the **second** object overwrites (or recursively merges) the value from the first.

---

## 1️⃣ TypeScript

```ts
/**
 * Deep‑merges two values. If both are plain objects,
 * they are merged recursively; otherwise `right` wins.
 */
export function deepMerge<T, U>(left: T, right: U): T & U {
    // Helper that works for any pair of values (not only objects)
    const merge = (
        a: unknown,
        b: unknown
    ): unknown => {
        if (a == null || b == null) return b;          // `b` wins when either side is falsy
        if ((typeof a === 'object' && typeof b === 'object') ||
            Array.isArray(a) && Array.isArray(b)) {   // both objects or arrays
            // Arrays are concatenated (order matters)
            const merged = [...(a as any[]), ...(b as any[])];
            return merged;
        }
        // Fallback – primitive values: right overwrites left
        return b;
    };

    // Recursive walk for nested structures
    function walker(l: T, r: U): unknown {
        if (l === undefined || r === undefined) return merge(l, r);
        const result = Array.isArray(l) && Array.isArray(r)
            ? ([] as any[]).concat(l).map((item, i) => merge(item, r[i]))
            : Object.keys({ ...l }).reduce((acc, key) => {
                  acc[key] = typeof r[key] !== 'undefined' ? walker((l as {[k: string]: unknown})[key], (r as {[k: string]: unknown})[key]) :
                               walker((l as {[k: string]: unknown})[key], undefined);
                  return acc;
              }, {} as {[K in keyof T]: T[K]});
        // Fill missing keys from r
        Object.keys({ ...r }).forEach(k => {
            if (!(k in result)) result[k] = (r as {[k2: string]: unknown})[k];
        });
        return result;
    }

    return walker(left, right) as T & U;
}
```

