const a = { foo: 1, bar: { x: 10 } };
const b = { bar: { y: 20 }, baz: 3 };

// deepMerge(a, b) → { foo: 1, bar: { x: 10, y: 20 }, baz: 3 }
console.log(deepMerge(a, b));
```

