def deep_merge(left: dict | None = None,
               right: dict) -> dict:
    """
    Deep‑merge two dictionaries. Values in `right` override those in `left`.
    Nested dicts are merged recursively; other types are replaced.
    """
    if left is None:
        return right.copy()                     # start from a shallow copy of right

    result = left.copy()

    for key, value in right.items():
        if (key in result and isinstance(result[key], dict) 
                and isinstance(value, dict)):
            # Recurse into nested dicts
            result[key] = deep_merge(result[key], value)
        else:
            # Replace or add the key with `right`'s value
            result[key] = value

    return result


