package main

import (
	"fmt"
)

// DeepMerge returns a deep copy of m1 with values from m2 taking precedence.
func DeepMerge(m1, m2 map[string]interface{}) map[string]interface{} {
	if len(m1) == 0 {
		return mergeDeepCopy(m2)
	}
	if len(m2) == 0 {
		return mergeDeepCopy(m1)
	}

	result := make(map[string]interface{}, len(m1)+len(m2))
	for k, v := range m1 {
		result[k] = v
	}
	for k, v := range m2 {
		if _, exists := result[k]; exists && isMap(v) && isMap(result[k]) {
			// both values are maps → recurse
			result[k] = mergeDeepCopy(DeepMerge(result[k].(map[string]interface{}), v.(map[string]interface{})))
		} else {
			result[k] = v // right overwrites left
		}
	}

	return result
}

func isMap(v interface{}) bool { _, ok := v.(map[string]interface{}); return ok }

// Helper that returns a deep copy of an arbitrary value (maps only here)
func mergeDeepCopy(src interface{}) interface{} {
	switch srcM := src.(type) {
	case map[string]interface{}:
		dst := make(map[string]interface{}, len(srcM))
		for k, v := range srcM {
			dst[k] = mergeDeepCopy(v)
		}
		return dst
	default:
		return src // primitives are copied by value
	}
}

// ------------------------------------------------------------------
func main() {
	a := map[string]interface{}{"foo": 1, "bar": map[string]interface{}{"x": 10}}
	b := map[string]interface{}{"bar": map[string]interface{}{"y": 20}, "baz": 3}

