## 2️⃣ TypeScript Implementation  

```ts
// ------------------------------------------------------------
// TokenBucket – rate limiter (Node.js / browser compatible)
// ------------------------------------------------------------

/**
 * Creates a token bucket that allows N requests per second.
 *
 * @param capacity   Maximum burst size (tokens stored at max).
 * @param tokensPerSecond Tokens added to the bucket each second.
 */
export class TokenBucket {
  private readonly capacity: number;
  private readonly rate: number;               // tokens/second
  private now: number;                         // last timestamp we processed
  private tokens: number;

  constructor(capacity: number, tokensPerSecond: number) {
    this.capacity = Math.max(1, capacity);
    this.rate = Math.max(0.001, tokensPerSecond); // avoid division by zero

    // Start with an empty bucket; `now` is the timestamp of creation.
    this.now = Date.now() / 1000;
    this.tokens = 0;
  }

  /**
   * Try to acquire a token for one request.
   *
   * @returns true if the request can proceed immediately, false otherwise
   */
  public tryAcquire(): boolean {
    // Fast path – bucket already has tokens?
    const now = Date.now() / 1000;               // current time in seconds

    // Refill tokens that have become available since last call.
    this._refill(now);

    if (this.tokens > 0) {
      this.tokens -= 1;
      return true;   // request allowed
    }

    // No token immediately – reject or you could implement a back‑off delay here.
    return false;
  }

  /**
   * Internal helper: refill tokens based on elapsed time since `now`.
   */
  private _refill(nowSecs: number): void {
    const delta = nowSecs - this.now; // seconds passed
    if (delta > 0) {
      // Add up to capacity worth of tokens.
      const added = Math.min(delta * this.rate, this.capacity);
      this.tokens = Math.max(0, Math.min(this.tokens + added, this.capacity));
    }
    this.now = nowSecs; // update internal clock
  }

  /**
   * Convenience wrapper that automatically waits until a token is available.
   *
   * @param timeoutMs maximum time to wait (ms). Pass `null` for no waiting.
   */
  public acquire(timeoutMs?: number): Promise<void> {
    return new Promise((resolve, reject) => {
      const start = Date.now();
      let elapsed = 0;

      // Recursive helper that refills and checks availability.
      const tryAcquireRecursively = async () => {
        if (this.tryAcquire()) {
          resolve(); // success – token consumed
          return;
        }

        elapsed += 10; // wait in small chunks to avoid busy‑loop

        if (timeoutMs !== null && elapsed > timeoutMs) {
          reject(new Error('Rate limit exceeded'));
          return;
        }

        await new Promise((r) => setTimeout(r, 10)); // sleep a short chunk
        await tryAcquireRecursively();
      };

      tryAcquireRecursively().catch(reject);
    });
  }
}
```

