import time
from typing import Optional


class TokenBucket:
    """
    Simple token bucket for rate limiting.
    
    Parameters:
        capacity (int): Maximum tokens that can be stored (burst size).
        rate_per_second (float): Tokens added per second. Must be >= 0.
    """

    def __init__(self, capacity: int, rate_per_second: float):
        if capacity <= 0:
            raise ValueError("capacity must be > 0")
        if rate_per_second < 0:
            raise ValueError("rate_per_second must be non‑negative")

        self.capacity = capacity
        self.rate = rate_per_second
        # Store the timestamp of the last refill operation.
        self._last_refill_ts: float = time.time()
        self._tokens: int = 0

    def try_acquire(self) -> bool:
        """
        Try to acquire a token immediately.

        Returns True if successful, False otherwise.
        """
        now = time.time()

        # Refill tokens that have become available since the last call.
        self._refill(now)

        if self._tokens > 0:
            self._tokens -= 1
            return True

        return False

    def _refill(self, current_ts: float) -> None:
        """
        Internal helper – add tokens based on elapsed time.
        """
        elapsed = current_ts - self._last_refill_ts
        if elapsed > 0:
            # We can never exceed capacity.
            added = min(elapsed * self.rate, self.capacity)
            self._tokens = min(self._tokens + added, self.capacity)

        # Update internal clock to now for the next call.
        self._last_refill_ts = current_ts

    def acquire(self, timeout_seconds: Optional[float] = None) -> bool:
        """
        Block until a token is available or raise an exception if timed out.

        Parameters:
            timeout_seconds (float): Maximum seconds to wait. If `None`,
                the method never blocks and returns False immediately.
        """
        start = time.time()
        while True:
            if self.try_acquire():
                return True

            elapsed = time.time() - start
            if timeout_seconds is not None and elapsed >= timeout_seconds:
                # Timed out – no token available within the limit.
                return False

            # Sleep a tiny chunk to avoid busy‑waiting.
            time.sleep(0.01)


# ----------------------------------------------------------------------
# Example usage -------------------------------------------------------
