// Simple LRU Cache implementation in TypeScript

class LRUCache<K, V> {
    private capacity: number;
    // Map stores key → node (so we can O(1) lookup)
    private map = new Map<K, Node<K, V>>();
    // Doubly‑linked list head/tail represent most‑recent / least‑recent
    private head?: Node<K, V>;
    private tail?: Node<K, V>;

    constructor(capacity: number) {
        this.capacity = capacity;
    }

    /** Returns the value for `key` or undefined if not present */
    get(key: K): V | undefined {
        const node = this.map.get(key);
        if (!node) return undefined;

        // Move accessed node to front (most‑recent)
        this._moveToFront(node);

        return node.value;
    }

    /** Inserts/updates the value for `key`. If capacity is exceeded,
     * evicts the least‑recently used entry. */
    set(key: K, value: V): void {
        let node = this.map.get(key);
        if (!node) {
            // New key – create a fresh node
            const newNode = new Node(key, value);
            this.map.set(key, newNode);

            // Insert at front (most‑recent)
            if (!this.head) {
                this.head = newNode;
                this.tail = newNode;
            } else {
                newNode.next = this.head!;
                this.head!.prev = newNode;
                this.head = newNode;
            }

            // Evict oldest entry if we exceed capacity
            if (this.map.size > this.capacity) {
                const lruNode = this.tail!;
                this.map.delete(lruNode.key);
                this._removeNode(lruNode);
                this.tail = lruNode.prev;
                if (this.tail) this.tail.next = null;
            }
        } else {
            // Existing key – update value & move to front
            node.value = value;
            this._moveToFront(node);
        }
    }

    /** Private helper: detach a node from its current position */
    private _removeNode(node: Node<K, V>): void {
        if (node.prev) node.prev.next = node.next;
        else this.head = node.next; // detached head

        if (node.next) node.next.prev = node.prev;
        else this.tail = node.prev; // detached tail
    }

    /** Private helper: attach a node right after the current head */
    private _moveToFront(node: Node<K, V>): void {
        if (this.head === node) return; // already front

        this._removeNode(node);
        // Insert at front
        node.next = this.head!;
        this.head!.prev = node;
        this.head = node;
        node.prev = null;
    }

    /** Helper inner class representing a doubly‑linked list node */
    private static class Node<K, V> {
        key: K;
        value: V;
        prev?: Node<K, V>;
        next?: Node<K, V>;

        constructor(key: K, value: V) {
            this.key = key;
            this.value = value;
        }
    }
}

// Example usage
const cache = new LRUCache<string, number>(3);
cache.set('one', 1);
cache.set('two', 2);
console.log(cache.get('one')); // → 1

cache.set('three', 3);          // now capacity = 3
cache.set('four', 4);           // evicts 'two'
console.log(cache.get('two')); // → undefined
```

**Key points**

* Uses a **Map** for O(1) key look‑ups and a doubly‑linked list to keep MRU/LRU order.
* `set` inserts/updates; if the size exceeds capacity it evicts the tail (LRU).
* `get` moves accessed nodes to the front.

