// LRUCache implements a simple LRU cache with O(1) ops.
type LRUCache struct {
	capacity int
	cache    map[interface{}]*list.Element // key -> element in list
	order    *list.List                    // doubly‑linked list of keys (MRU → LRU)
}

// Node holds the value; we store interface{} to keep generics simple.
type node struct {
	key   interface{}
	value interface{}
}

func NewLRUCache(capacity int) *LRUCache {
	return &LRUCache{
		capacity: capacity,
		cache:    make(map[interface{}]*list.Element),
		order:    list.New(),
	}
}

// Get returns the value for key or nil if not present.
func (c *LRUCache) Get(key interface{}) interface{} {
	if elem, ok := c.cache[key]; !ok {
		return nil
	} else {
		c.order.MoveToFront(elem)
		return elem.Value.(*node).value
	}
}

// Set inserts/updates the value for key. Evicts LRU if capacity exceeded.
func (c *LRUCache) Set(key, value interface{}) {
	if elem, ok := c.cache[key]; !ok {
		// New entry – create node and add to front of list
		newNode := &node{key: key, value: value}
		elem = c.order.PushFront(newNode)
		c.cache[key] = elem

		if c.order.Len() > c.capacity {
			// Evict least‑recently used (tail)
			evicted := c.order.Remove(c.order.Back())
			delete(c.cache, evicted.(*node).key)
		}
	} else {
		// Existing entry – update value and move to front
		ele := elem.Value.(*node)
		ele.value = value
		c.order.MoveToFront(elem)
	}
}

func main() {
	cache := NewLRUCache(3)

	cache.Set("one", 1)
	cache.Set("two", 2)
	fmt.Println(cache.Get("one")) // → 1

	cache.Set("three", 3)        // capacity not exceeded yet
	cache.Set("four", 4)         // evicts "two"
	fmt.Println(cache.Get("two")) // → nil (evicted)
}
```

