/**
 * Debounce wrapper.
 *
 * @param fn          Function to be debounced.
 * @param wait        Milliseconds to delay before invoking `fn`.
 * @param options     Optional configuration:
 *                    - leading: invoke immediately on first call (default false).
 *                    - maxWait: maximum time between calls (overrides `wait` if exceeded) (default same as `wait`).
 */
function debounce<T extends (...args: any[]) => any>(
  fn: T,
  wait: number,
  options?: {
    leading?: boolean;
    maxWait?: number; // optional, defaults to `wait`
  }
): ReturnType<T> {
  let timeoutId: NodeJS.Timeout | null = null;
  const argsRef = {args: [] as any[]}; // mutable reference for trailing calls

  const invoke = (...callArgs: Parameters<T>) => {
    if (timeoutId) return; // already pending
    if (!options?.leading && argsRef.args.length > 0) {
      // If leading is false and we have a previous call, treat this as a new sequence.
      argsRef.args = [...callArgs];
    } else {
      argsRef.args.push(...callArgs);
    }

    const later = () => {
      timeoutId = null;
      if (!options?.maxWait) {
        fn(...argsRef.args);
      } else {
        // If maxWait is set, ensure we don't exceed it
        const timeSinceFirstCall = Date.now() - argsRef.firstTime ?? 0;
        if (timeSinceFirstCall + wait > options.maxWait) {
          fn(...argsRef.args);
          argsRef.firstTime = Date.now();
        }
      }
    };

    timeoutId = setTimeout(later, Math.min(wait, options?.maxWait ? options.maxWait - timeSinceFirstCall : 0));
    argsRef.firstTime ??= Date.now(); // capture first call timestamp
  };

  return invoke as ReturnType<T>;
}

