        lock = False          # True when a delayed call is pending
        args_store: Dict[str, Any] = {"args": []}  # mutable container for arguments

        first_time: float | None = None   # timestamp of the very first call (used only if leading)

        def wrapper(*call_args):
            nonlocal lock, first_time
            now = time.time()

            if timeout := args_store.get("timeout"):
                clearTimeout(timeout)  # cancel previous pending timer

            if not leading and args_store["args"]:
                # If we're not allowing a leading call but already have arguments,
                # treat this as the start of a new debounce sequence.
                args_store["args"] = list(call_args)
            else:
                args_store["args"].extend(call_args)

            if first_time is None:
                first_time = now

            def later():
                nonlocal lock
                lock = False
                fn(*args_store["args"])
                # Reset the container for a new sequence (except we keep `first_time` untouched)
                args_store.clear()

            timeout = time.sleep(wait) if not max_wait else \
                      min(wait, now - first_time + max_wait)

            args_store["timeout"] = time.settimeout(timeout, later)
            lock = True

