// ------------------------------------------------------------
// Simple Pub/Sub EventEmitter – pure TS implementation
// ------------------------------------------------------------

type Listener<T extends any[]> = (...args: T) => void;

/**
 * Tiny pub/sub emitter.
 *
 * • `on` registers a listener for an event name.
 * • `off` removes one or all listeners (optional parameters).
 * • `emit` calls every active listener with the supplied arguments.
 */
export class EventEmitter {
  /** internal registry – map: eventName → array of listeners */
  private listeners = new Map<string, Listener<any[]>>();

  /**
   * Register a callback for an event name.
   *
   * @param name      Event identifier (string)
   * @param listener  Callback that receives the supplied arguments
   */
  on(name: string, listener: Listener<any[]>): void {
    if (!this.listeners.has(name)) this.listeners.set(name, []);
    const arr = this.listeners.get(name)!;
    arr.push(listener);
  }

  /**
   * Remove a specific listener or all listeners for an event.
   *
   * @param name      (optional) Event identifier. If omitted → remove ALL listeners
   * @param listener  (optional) Specific callback to drop. Ignored when `name` is omitted.
   */
  off(name?: string, listener?: Listener<any[]>): void {
    if (!name) {
      // Remove everything
      this.listeners.clear();
      return;
    }

    const arr = this.listeners.get(name);
    if (!arr) return; // nothing to remove

    if (listener) {
      // Find and splice the exact listener
      const idx = arr.indexOf(listener);
      if (idx !== -1) arr.splice(idx, 1);
    } else {
      // Remove all listeners for this name
      this.listeners.delete(name);
    }
  }

  /**
   * Invoke every listener attached to `name` with the supplied arguments.
   *
   * @param name     Event identifier
   * @param args     Arguments passed through from emitter side
   */
  emit(name: string, ...args: any[]): void {
    const arr = this.listeners.get(name);
    if (!arr) return; // no listeners → nothing happens

    for (const listener of arr) {
      listener(...args); // spread arguments to each callback
    }
  }

  /** Helper – convenience method that returns the current array reference */
  private _listeners(name: string): Listener<any[]>[] | undefined {
    return this.listeners.get(name);
  }
}
```

