# ------------------------------------------------------------
# Simple Pub/Sub EventEmitter – pure Python implementation
# ------------------------------------------------------------

from typing import Callable, Any, List


class EventEmitter:
    """
    Tiny pub/sub emitter.
    
    * `on(name: str, listener: Callable[..., None])` → register a callback.
    * `off(name: Optional[str] = None, listener: Optional[Callable[..., None]] = None)`
      → remove one or all listeners for an event name.
    * `emit(name: str, *args:Any)` → call every active listener with the supplied args.
    """

    def __init__(self):
        # map: eventName -> list of listeners
        self._listeners: dict[str, List[Callable[..., None]]] = {}

    def on(self, name: str, listener: Callable[..., None]) -> None:
        """Register a callback for an event."""
        if name not in self._listeners:
            self._listeners[name] = []
        self._listeners[name].append(listener)

    def off(
        self,
        name: Optional[str] = None,
        listener: Optional[Callable[..., None]] = None,
    ) -> None:
        """
        Remove a specific listener or all listeners for an event.
        
        * If `name` is omitted → remove **all** listeners globally.
        * If both `name` and `listener` are given → remove only that exact listener.
        """
        if name is None:               # no name provided → clear everything
            self._listeners.clear()
            return

        lst = self._listeners.get(name)
        if not lst:
            return                     # nothing to do for this event

        if listener is not None:       # remove a specific callback
            try:
                lst.remove(listener)
            except ValueError:
                pass   # listener not found – silently ignore
        else:                         # remove all listeners with this name
            self._listeners.pop(name, None)

    def emit(self, name: str, *args: Any) -> None:
        """Invoke every listener attached to `name` with the supplied arguments."""
        lst = self._listeners.get(name)
        if not lst:
            return                     # no listeners → nothing happens
        for cb in lst:
            cb(*args)                  # unpack args and pass them through


