    # subscribe
    ee.on('greeting', hello)
    ee.on('exit',   goodbye)

    # fire events
    ee.emit('greeting', 'Hello world!')
    ee.emit('exit', 0)          # no reason supplied
    ee.emit('exit', 1, 'out of memory')

    # unsubscribe (optional)
    ee.off('exit', goodbye)
