/**
 * Throttles a function so it can be invoked at most once per `delayMs` ms.
 *
 * @template T - The return type of the wrapped function (or void if async).
 * @param fn      – The callback you want to throttle. It may be sync or async.
 * @param delayMs – Minimum time between two invocations, in milliseconds.
 */
export function throttle<T>(
  fn: (...args: any[]) => T | Promise<T>,
  delayMs: number
): (...args: Parameters<typeof fn>) => T | Promise<T> {
  let pendingPromise: Promise<any> | null = null;
  let lastCallTimestamp = -delayMs; // so the first call is always allowed

  return async function throttled(...args) {
    const now = Date.now();

    if (pendingPromise === null || now >= lastCallTimestamp + delayMs) {
      pendingPromise = Promise.resolve(fn(...args))
        .then(result => {
          pendingPromise = null;
          return result;
        })
        .catch(err => {
          // propagate any error and reset the timer
          pendingPromise = null;
          throw err;
        });
      lastCallTimestamp = now;

      if (pendingPromise === null) {
        // If we just finished a call, clear the placeholder immediately.
        pendingPromise = null;
      }
    }

    return await pendingPromise!;
  };
}
