import os
from jose import jwt, jwk, exceptions

# --------------------------------------------------------------------
def sign_jwt(payload: dict, ttl_sec: int | None = None) -> str:
    """
    Signs a JWT using RSA keys stored locally.
    The private key file (`private.pem`) must contain the PEM‑encoded RSA private key.
    """
    # Load public key from disk (or keep it in memory if you prefer)
    with open('public.pem', 'r') as f:
        pub_key = jwk.construct(f.read())

    token = jwt.encode(
        payload,
        pub_key,
        algorithm='RS256',
        headers={'kid': os.getenv('JWT_KID', '')},  # optional key identifier
    )
    if ttl_sec is not None:
        exp = int(jwt.get_unverified_header(token)['exp']) + ttl_sec
        token = jwt.encode(
            payload,
            pub_key,
            algorithm='RS256',
            headers={'kid': os.getenv('JWT_KID', '')},
            options=dict(expiration_time=exp)
        )
    return token

# --------------------------------------------------------------------
def verify_jwt(token: str) -> dict | None:
    """
    Verifies the JWT signature and returns decoded claims.
    Raises exceptions if verification fails (e.g., expired, invalid sig).
    """
    with open('private.pem', 'r') as f:
        priv_key = jwk.construct(f.read())

    try:
        payload = jwt.decode(
            token,
            priv_key,
            algorithms=['RS256'],
            audience=None,
            issuer=None,
        )
        return payload
    except exceptions.ExpiredSignatureError:
        raise ValueError('Token has expired')
    except exceptions.InvalidTokenError as e:
        # You can inspect `e` for more details (invalid signature, wrong key ID, etc.)
        raise ValueError(f'JWT verification failed: {str(e)}')

# --------------------------------------------------------------------
if __name__ == '__main__':
    # Example payload
    payload = {'user_id': 1234, 'role': 'editor'}

    token = sign_jwt(payload, ttl_sec=300)   # expires in 5 minutes

    print('Signed JWT:', token)

    try:
        decoded = verify_jwt(token)
        print('Decoded claims:', decoded)
    except ValueError as exc:
        print('Verification error:', exc)
```

**Key points**

* Uses **`python-jose`**, which supports both RSA (`jwk.construct`) and HS256.
* Keys are loaded from PEM files – you can also keep them in environment variables or a secrets manager.
* The `ttl_sec` argument lets you set an explicit expiration time.

