		UserID:    int(payload["user_id"].(float64)),
		Role:      payload["role"].(string),
		IssuedAt:  time.Now().Unix(),
		ExpiresAt: time.Unix(time.Now().Add(time.Second*time.Duration(ttlSec)).Unix(), 0),
	})

	signed, err := token.SignedString(keyFunc)
	if err != nil {
		return "", fmt.Errorf("signing JWT: %w", err)
	}
	return signed, nil
}

func verifyJwt(tokenStr string) (map[string]interface{}, error) {
	keyFunc := func(t *jwt.Token) (interface{}, error) {
		if _, ok := t.Method.(*jwt.SigningMethodRSA); !ok {
			return nil, fmt.Errorf("unexpected signing method: %v", t.Header["alg"])
		}

		pubKeyBytes, err := os.ReadFile("./public.pem")
		if err != nil {
			return nil, err
		}
		key, err := jwt.ParseRSAPublicKeyFromPEM(pubKeyBytes)
		if err != nil {
			return nil, err
		}
		return key, nil
	}

	token, err := jwt.ParseWithClaims(tokenStr, &Claims{}, keyFunc)
	if err != nil {
		return nil, fmt.Errorf("parsing token: %w", err)
	}

	if !token.Valid {
		return nil, fmt.Errorf("invalid token")
	}
	return token.Claims.(jwt.MapClaims), nil
}

