  // jwt.ts --------------------------------------------------------------
  import * as fs from 'fs';
  import * as path from 'path';
  import { sign, verify } from 'jsonwebtoken';
  
  /**
   * Configuration – you can also load this from a .env file.
   */
  const JWT_PRIVATE_KEY_PATH = path.resolve(__dirname, './private.key');
  const JWT_PUBLIC_KEY_PATH  = path.resolve(__dirname, './public.key');
  
  // --------------------------------------------------------------------
  // Sign a token
  export function signJwt(payload: Record<string, any>, ttlSec?: number): string {
      const privateKey = fs.readFileSync(JWT_PRIVATE_KEY_PATH);
      return sign(
          payload,
          privateKey.toString(),
          { algorithm: 'RS256', expiresIn: ttlSec ? `${ttlSec}s` : undefined }
      );
  }
  
  // --------------------------------------------------------------------
  // Verify a token
  export function verifyJwt(token: string): Record<string, any> | null {
      const publicKey = fs.readFileSync(JWT_PUBLIC_KEY_PATH);
      return verify(
          token,
          publicKey.toString(),
          { algorithms: ['RS256'] }
      ) as Record<string, any>;
  }
  
  // --------------------------------------------------------------------
  // Example usage (run with `ts-node jwt.ts`)
  if (require.main === module) {
      // 1️⃣ Create a token
      const payload = { userId: 42, role: 'admin' };
      const token = signJwt(payload, 3600);   // expires in 1 hour
  
      console.log('Signed JWT:', token);
  
      // 2️⃣ Verify it later
      try {
          const decoded = verifyJwt(token);
          if (decoded) {
              console.log('Decoded payload:', decoded);
          } else {
              console.error('Verification failed – invalid or expired token');
          }
      } catch (err: any) {
          console.error('Error verifying JWT:', err.message);
      }
