## 1. TypeScript (`src/utils/xss.ts`)

```ts
// src/utils/xss.ts
/**
 * Escape HTML special characters.
 *
 * @param input - Raw user‑supplied string.
 * @returns String with <, >, &, ', and " replaced by their entities.
 */
export function escapeHtml(input: string): string {
  if (!input) return '';

  // Use a compact RegExp that matches the four most common unsafe chars
  const re = /([<>&"'])/g;
  return input.replace(re,
    (c) => ({
      '<': '&lt;',
      '>': '&gt;',
      '&': '&amp;',
      "'": '&#39;',   // single quote – prevents attribute injection
      '"': '&quot;'
    }[c])
  );
}

/**
 * Strip tags while preserving text content.
 *
 * @param html - HTML string that may contain malicious markup.
 * @returns Only the inner text, safe to display anywhere.
 */
export function stripTags(html: string): string {
  if (!html) return '';
  // Simple regex removes opening and closing tags; preserves whitespace
  return html.replace(/<\/?[^>]+(>|$)/g, '');
}

/**
 * Encode a URL‑safe fragment (e.g., for href or src attributes).
 *
 * @param url - User‑supplied URL.
 * @returns Percent‑encoded version safe to embed in HTML attributes.
 */
export function encodeUrl(url: string): string {
  if (!url) return '';
  // encodeURIComponent encodes everything except alphanumerics and `-_.~`
  return encodeURIComponent(url).replace(/'/g, '%27').replace(/"/g, '%22');
}
```

**Usage**

```ts
import { escapeHtml } from './xss';

const userInput = '<script>alert("XSS");</script>';
console.log(escapeHtml(userInput)); // → &lt;script&gt;alert(&quot;XSS&quot;);&lt;/script&gt;
```

*Why this works*:  
- **`escapeHtml`** replaces the four most dangerous characters (`<`, `>`, `&`, `'`).  
- **`stripTags`** removes any remaining HTML tags, leaving only plain text.  
- **`encodeUrl`** guarantees URLs are safe for `<a href="…">` or `<img src="…">`.

