from typing import Callable, List

# -------------------------------------------------------------------
# WorkerPool – concurrent executor with a fixed number of workers.
# -------------------------------------------------------------------
class WorkerPool:
    def __init__(self, num_workers: int):
        self._workers = []
        for _ in range(num_workers):
            w = asyncio.create_task(self.worker())
            self._workers.append(w)

    async def worker(self) -> None:
        while True:
            # Grab a job from the shared queue (FIFO)
            job = jobs_queue.pop(0) if jobs_queue else None
            if not job:               # no more work → exit this task
                break

            try:
                await job()
            except Exception as exc:
                print(f"Worker raised an error: {exc}")

    async def run(self, jobs: List[Callable[[], asyncio.Future]]):
        """Submit N jobs and wait for completion."""
        # Start all workers concurrently
        await asyncio.gather(*self._workers)

