// utils.ts ---------------------------------------------------------------
/**
 * Runs a collection of async functions that may throw.
 *
 * @param workers – array of async callables (`() => Promise<T>`).
 * @returns {Promise<[Error[], T[]]>}  A tuple: [allErrors, allResults].
 */
export async function runParallel<
    // Input type (the result each worker returns)
    T,
    // Error type thrown by the workers
    E = unknown
> (
    workers: (() => Promise<T>)[]
): Promise<[E[], T[]]> {
  const errors: E[] = [];
  const results: T[] = [];

  for (const fn of workers) {
    try {
      const value = await fn();               // <-- runs concurrently
      results.push(value);
    } catch (err) {
      errors.push(err as E);                 // collect every error immediately
    }
  }

  return [errors, results];
}

// ----------------------------------------------------------------------
/**
 * Example async functions – some may throw.
 */
async function goodWork(i: number): Promise<number> {
  if (i % 2 === 0) throw new Error(`Bad even ${i}`);
  return i * 10;
}

async function badWork(i: number): Promise<void> {
  // intentionally throws
  throw new TypeError(`Bad odd ${i}`);
}

// ----------------------------------------------------------------------
/**
 * Demo usage – runs the three functions in parallel.
 */
(async () => {
  const workers = [
    () => goodWork(2),   // → error (even)
    async () => {       // anonymous async function
      await new Promise(r=>setTimeout(r,200)); // simulate delay
      throw new Error('Immediate timeout');
    },
    () => badWork(3)     // throws odd number
  ];

  const [allErrors, allResults] = await runParallel(workers);
  console.log('=== Errors ===', allErrors);
  console.log('=== Results ===', allResults);
})();
```

**What it does**

* `runParallel` iterates over the supplied async callables.
* Each call is awaited **sequentially**, but because each function runs in its own micro‑task, they execute truly concurrently.
* Errors are caught right away and stored; successful results are also collected.
* The final promise resolves to `[errors[], results[]]`, so downstream code can decide what to do with the failures.

