    """May raise."""
    if i % 2 == 0:
        raise ValueError(f"Bad even {i}")
    return i * 10


def bad_work(i: int):
    """Raises immediately."""
    raise TypeError(f"Bad odd {i}")


async def run_parallel(tasks):
    """
    Runs a list of async functions concurrently and gathers all errors.

    Parameters
    ----------
    tasks : List[Callable[..., Awaitable[Any]] | Callable[..., Any]]
        Functions that return an awaitable (or plain value).

    Returns
    -------
    Tuple[List[Exception], List[Any]]
        First element – all exceptions raised during execution.
        Second element – list of successful results in the same order as `tasks`.
    """
    errors: list[Exception] = []
    results: list[Any] = []

    # We use asyncio.gather with return_exceptions=True so that
    # *all* awaitables are scheduled concurrently, but we still collect
    # per‑task outcomes manually.
    async def gather_one(idx):
        try:
            val = await tasks[idx]()
            results.append(val)
        except Exception as exc:
            errors.append(exc)

    # Create a list of coroutines – each runs the corresponding task once.
    coros = [gather_one(i) for i in range(len(tasks))]
    await asyncio.gather(*coros)

    return errors, results


# ----------------------------------------------------------------------
