    tasks = [
        lambda: good_work(2),          # → error
        lambda: asyncio.sleep(0.1),
        lambda: bad_work(3)            # → error (odd)
    ]

    errs, outs = asyncio.run(run_parallel(tasks))
    print("=== Errors ===", errs)
    print("=== Results ===", outs)
