## 3️⃣ Go (using goroutines + waitgroup)

```go
package main

import (
	"fmt"
	"sync"
)

// ----------------------------------------------------------------------
func goodWork(i int) (int, error) {
	if i%2 == 0 {
		return 0, fmt.Errorf("bad even %d", i)
	}
	return i * 10, nil
}

func badWork(i int) error {
	return fmt.Errorf("bad odd %d", i)
}

// ----------------------------------------------------------------------
// runParallel executes a slice of functions concurrently.
//
// Each function must return (result, error). The caller supplies the
// concrete callables; errors are collected and returned together with any results.
//
// Parameters:
//   workers []func() (interface{}, error)  // each element is an async operation.
//
// Returns:
//   [2][]error / []interface{} – first slice = all errors, second slice =
//                                 successful results in the same order as `workers`.
func runParallel(workers []func() (any, error)) ([]error, []any) {
	var wg sync.WaitGroup
	wg.Add(len(workers))

	errors := make([]error, len(workers))
	results := make([]any, len(workers))

	for i, fn := range workers {
		go func(idx int) {
			defer wg.Done()
			out, err := fn()
			if err != nil {
				errors[idx] = err
			} else {
				results[idx] = out
			}
		}(i)
	}

	wg.Wait() // wait for all goroutines to finish

	return errors, results
}

// ----------------------------------------------------------------------
func main() {
	tasks := []func() (any, error){
		func() (any, error) { return goodWork(2), nil },   // → error
		func() (any, error) { return nil, fmt.Errorf("immediate timeout") },
		func() (any, error) { return badWork(3), nil },    // → error (odd)
	}

	errs, outs := runParallel(tasks)

	fmt.Println("=== Errors ===")
	for _, e := range errs {
		fmt.Println(e)
	}
	fmt.Println("\n=== Results ===")
	for _, v := range outs {
		fmt.Printf("%+v\n", v)
	}
}
```

**Why it works**

* Each worker is launched in its own goroutine.
* A `sync.WaitGroup` ensures the main thread blocks until **all** workers have reported a result or an error.
* Errors are stored directly into pre‑allocated slices (`errors`) indexed by position; successful values go to `results`.
* The function returns exactly `[errors, results]`, matching the TypeScript and Python signatures.

