use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

// Counter is an integer protected by a mutex.
struct Counter {
    value: i32,
    // Arc + Mutex gives us shared ownership and thread‑safe access.
    lock: Arc<Mutex<i32>>,
}

impl Counter {
    fn new() -> Self {
        Counter {
            value: 0,
            lock: Arc::new(Mutex::new(0)),
        }
    }

    // Returns the current value (read‑only).
    fn get(&self) -> i32 {
        *self.lock.lock().unwrap()
    }

    // Increments by `n` atomically.
    fn inc(&self, n: i32) -> i32 {
        let mut guard = self.lock.lock().unwrap();
        let new_val = *guard + n;
        *guard = new_val;
        new_val
    }
}

/* -------------------------------------------------
   Example usage – concurrent reads & writes
--------------------------------------------------- */
fn main() {
    let counter = Arc::new(Counter::new());

    // Spawn several threads that increment the counter many times.
    let mut handles = vec![];
    for _ in 0..5 {
        let c = Arc::clone(&counter);
        handles.push(thread::spawn(move || {
            for _ in 0..10_000 {
                c.inc(1);
            }
        }))
    }

    // Wait for all threads to finish.
    for h in handles.into_iter() {
        h.join().unwrap();
    }

    println!("Final value: {}", counter.get());
}
```

**Key points**

* `Arc<Mutex<T>>` gives **multiple owners** (`Arc`) plus thread‑safe mutual exclusion (`Mutex`).  
* The lock is acquired with `.lock()` (which blocks until the mutex becomes available) and automatically released when the guard goes out of scope.  

