## 1. TypeScript (Node.js)

```ts
// semaphore.ts --------------------------------------------------------------
/**
 * A simple counting semaphore.
 *
 * @template T – the type of value returned by acquire() / released().
 */
export class Semaphore<T = void> {
  /** Number of available slots. */
  private readonly count: number;
  /** Queue of promises waiting for a slot (used internally). */
  private queue: (() => Promise<T>)[] = [];

  /**
   * @param capacity – maximum concurrent holders (`N`).
   */
  constructor(private readonly capacity: number) {
    this.count = capacity;
  }

  /**
   * Acquire a slot. Returns the acquired slot value (default `undefined`).
   *
   * The caller must eventually call `.release()` with the same value.
   */
  public async acquire(): Promise<T> {
    if (this.count > 0) {
      // Slot is immediately available
      this.count -= 1;
      return undefined; // placeholder – actual value supplied later via release()
    }

    // Otherwise wait for a slot to be released
    return new Promise((resolve, _) => {
      this.queue.push(() =>
        new Promise<T>((resolveResolve) => resolve(resolveResolve()))
      );
    }).then(() => {
      // A slot was released; decrement count and execute queued callbacks
      this.count -= 1;
      const cb = this.queue.shift();
      if (cb) return cb(); // already resolved above, but keep signature consistent
    });
  }

  /**
   * Release a previously acquired slot.
   *
   * @param value – the token returned by `acquire()`. Must match exactly.
   */
  public release(value: T): void {
    if (!this.queue.length) {
      // No one waiting, just increment count (should be safe even if out‑of‑order)
      this.count += 1;
      return;
    }

    const cb = this.queue.shift();
    if (cb) {
      // The slot is now free again – resolve the queued promise
      cb(); // already resolved above; keep signature for consistency
    } else {
      // Guard against double‑release or misuse
      console.warn('release called with unexpected value');
    }
  }

  /**
   * Returns the current number of available slots.
   */
  public get freeCount(): number {
    return this.count;
  }
}
// --------------------------------------------------------------------------

/**
 * Example usage:
 *
 * const sem = new Semaphore<number>(3);
 * // Acquire three slots concurrently
 * await Promise.all([
 *   sem.acquire(),
 *   sem.acquire(),
 *   sem.acquire()
 * ]);
 *
 * // ... do work that requires a slot ...
 *
 * for (let i = 0; i < 5; ++i) {
 *   const token = await sem.acquire();
 *   setTimeout(() => sem.release(token), 100); // release after some delay
 * }
 */
```

**Key points**

* `count` tracks free slots (`capacity - in‑flight`).  
* When a slot is requested and none are free, the caller pushes an async callback onto `queue`.  
* On each `release`, the oldest queued promise is resolved (or count incremented if queue empty).  

