import asyncio
from typing import Any


class Semaphore:
    """
    A simple counting semaphore.
    """

    def __init__(self, capacity: int):
        self._capacity = capacity
        self._count = capacity          # free slots
        self._queue: asyncio.Queue[asyncio.Future] = asyncio.Queue()

    async def acquire(self) -> Any:
        """Acquire a slot; blocks until one is available."""
        if self._count > 0:
            self._count -= 1
            return None               # placeholder – actual value supplied later via release()
        else:
            # Wait for a released token
            future = asyncio.Future()
            self._queue.put_nowait(future)
            await future
            return None

    def release(self, _value: Any) -> None:
        """Release a previously acquired slot."""
        if not self._queue:
            # No one waiting – just increment count (safe even out‑of‑order)
            self._count += 1
            return

        future = self._queue.get_nowait()
        # The token is already resolved; we could store it but keep signature simple.
        future.set_result(None)   # resolve the Future
