import asyncio

async def worker(sem: Semaphore, id_: int):
    async with sem.acquire() as _:
        print(f"Worker {id_} acquired slot")
        await asyncio.sleep(0.2)
        print(f"Worker {id_} releasing slot")

async def main():
    sem = Semaphore(capacity=3)

    # Launch several workers that may run concurrently up to the limit
    tasks = [worker(sem, i) for i in range(5)]
    await asyncio.gather(*tasks)

if __name__ == "__main__":
    asyncio.run(main())
