## 3. Go

```go
package semaphore

import (
	"context"
)

// Semaphore implements a counting semaphore.
type Semaphore struct {
	capacity int           // max concurrent holders
	count    int           // free slots (capacity - busy)
	queue    chan struct{} // buffered channel for waiting goroutines
}

// NewSemaphore creates a new semaphore with given capacity.
func NewSemaphore(capacity int) *Semaphore {
	if capacity < 0 {
		panic("negative capacity")
	}
	return &Semaphore{
		capacity: capacity,
		count:    capacity,
		queue:    make(chan struct{}, capacity),
	}
}

// Acquire waits until a slot is available and returns it.
func (s *Semaphore) Acquire(ctx context.Context) error {
	if s.count > 0 {
		s.count--
		return nil
	}

	select {
	case <-ctx.Done():
		return ctx.Err()
	default:
		s.queue <- struct{}{}
	}
	return nil
}

// Release releases a previously acquired slot.
func (s *Semaphore) Release() {
	s.queue <- struct{}{}
}
```

**Typical usage**

```go
package main

import (
	"context"
	"fmt"
	"time"
)

func main() {
	sem := semaphore.NewSemaphore(3)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	var wg sync.WaitGroup
	wg.Add(5) // 5 workers that may run concurrently up to limit

	for i := 0; i < 5; i++ {
		go func(id int) {
			defer wg.Done()
			if err := sem.Acquire(ctx); err != nil {
				fmt.Printf("worker %d: could not acquire slot\n", id)
				return
			}
			fmt.Printf("Worker %d acquired slot\n", id)

			time.Sleep(200 * time.Millisecond)
			sem.Release()
			fmt.Printf("Worker %d releasing slot\n", id)
		}(i)
	}

	wg.Wait()
}
```

**Key points**

* `count` tracks currently free slots.  
* When capacity is reached, callers are placed on a buffered channel (`queue`) that holds up to `capacity` values.  
* Each call to `Release` sends one value onto the channel, waking waiting goroutines.

