// producer.ts -------------------------------------------------------------
import { Worker, MessagePort } from 'worker_threads';

type Port = MessagePort;

export function createProducer(): Promise<Port> {
  const port = new Promise<Port>((resolve) => {
    const worker = new Worker(new URL('./worker-producer.js', import.meta.url));
    worker.on('message', (msg: Port) => resolve(msg));
    // send a signal that the producer is ready – we’ll pass it later
  });

  // start work in background thread
  return port;
}
```

