import { createConsumer as consumerWorker } from './consumer';

async function runPipeline() {
  // ---- Stage A: producer → channel (worker thread) --------------------
  const [aPort] = await Promise.all([createProducer(), createTransformer()]);
  console.log('🔹 Producer started, awaiting Transformer…');

  // ---- Stage B: transformer → channel ---------------------------------
  const bPort = aPort; // reuse the same port for downstream
  const consumerPromise = consumerWorker(); // starts worker‑consumer

