def binary_search(arr: list[int], target: int) -> int:
    """
    Binary search on a sorted list.
    Returns the index of `target` if present; otherwise -1.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
