/**
 * Compute the longest common subsequence of two strings.
 *
 * @param a First input string
 * @param b Second input string
 * @returns The longest common subsequence (LCS)
 */
function lcs(a: string, b: string): string {
  const m = a.length;
  const n = b.length;

  // dp[i][j] will hold the LCS of a[0..i-1] and b[0..j-1]
  const dp: number[][] = Array(m + 1)
    .fill(null)
    .map(() => Array(n + 1).fill(0));

  // Fill DP table
  for (let i = 1; i <= m; ++i) {
    for (let j = 1; j <= n; ++j) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // Reconstruct the LCS from the DP table
  let i = m, j = n;
  const result: string[] = [];

  while (i > 0 && j > 0) {
    if (a[i - 1] === b[j - 1]) {
      result.unshift(a[i - 1]); // prepend to keep correct order
      --i; --j;
    } else if (dp[i - 1][j] >= dp[i][j - 1]) {
      --i;
    } else {
      --j;
    }
  }

  return result.join('');
}

