```ts
/**
 * Recursive merge sort.
 *
 * @param arr – the input array to be sorted.
 * @returns a new sorted copy of `arr`.
 */
function mergeSort<T>(arr: T[]): T[] {
    // Base case: arrays with ≤1 element are already sorted
    if (arr.length <= 1) return arr;

    const mid = Math.floor(arr.length / 2);
    const left  = mergeSort(arr.slice(0, mid));
    const right = mergeSort(arr.slice(mid));

    return merge(left, right);
}

/**
 * Merge two already‑sorted arrays into one sorted array.
 *
 * @param a – first sorted sub‑array
 * @param b – second sorted sub-array
 * @returns merged sorted array containing all elements of `a` and `b`
 */
function merge<T>(a: T[], b: T[]): T[] {
    const result: T[] = [];
    let i = 0, j = 0;

    // Pull the smallest head element from either side
    while (i < a.length && j < b.length) {
        if (a[i] <= b[j]) {
            result.push(a[i]);
            ++i;
        } else {
            result.push(b[j]);
            ++j;
        }
    }

    // Append any leftovers
    return result.concat(a.slice(i)).concat(b.slice(j));
}

/* Example usage */
const numbers = [5, 2, 9, 1, 3];
console.log(mergeSort(numbers));   // → [1,2,3,5,9]
```

