fn merge_sort<T: Ord>(arr: &[T]) -> Vec<T> {
    if arr.len() <= 1 {
        arr.to_vec()
    } else {
        let mid = arr.len() / 2;
        let (left, right) = arr.split_at(mid);
        _merge(merge_sort(&left[..]), merge_sort(&right[..]))
    }
