fn _merge<T: Ord>(mut a: Vec<T>, mut b: Vec<T>) -> Vec<T> {
    let mut result = vec![];
    while !a.is_empty() && !b.is_empty() {
        if a[0] <= b[0] {
            result.push(a.remove(0));
        } else {
            result.push(b.remove(0));
        }
    }
    // Remaining elements (one of these will be empty)
    result.extend_from_slice(&a);
    result.extend_from_slice(&b);
    result
}

