// trie.ts ---------------------------------------------------------

class TrieNode {
  children: Record<string, TrieNode>;
  isEndOfWord: boolean;

  constructor() {
    this.children = {};
    this.isEndOfWord = false;
  }
}

export class Trie {
  root: TrieNode;

  constructor() {
    this.root = new TrieNode();
  }

  /** Insert a word into the trie */
  insert(word: string): void {
    let node = this.root;
    for (const ch of word) {
      if (!node.children[ch]) {
        node.children[ch] = new TrieNode();
      }
      node = node.children[ch];
    }
    node.isEndOfWord = true;
  }

  /** Search for a word in the trie */
  search(word: string): boolean {
    let node = this.root;
    for (const ch of word) {
      if (!node.children[ch]) return false; // character not found
      node = node.children[ch];
    }
    return node.isEndOfWord; // only true if it's a complete word
  }

  /** Optional: check if any word in the trie has the given prefix */
  startsWith(prefix: string): boolean {
    let node = this.root;
    for (const ch of prefix) {
      if (!node.children[ch]) return false;
      node = node.children[ch];
    }
    return true; // returns whether a branch exists with that prefix
  }
}
