# get_with_timeout.py -------------------------------------------------------
import requests
from typing import Optional

def get_with_timeout(
    url: str,
    timeout_ms: Optional[int] = 10_000   # None → no explicit timeout (default)
) -> str:
    """
    GET request with configurable timeout.

    Args:
        url: Destination URL.
        timeout_ms: Milliseconds before aborting. Pass `None` for unlimited wait.

    Returns:
        Response body as a string.

    Raises:
        requests.exceptions.HTTPError – non‑2xx status codes (unless ignored).
        requests.exceptions.Timeout   – if the request exceeds *timeout_ms*.
    """
    # Convert ms to seconds
    timeout = timeout_ms / 1000.0 if timeout_ms is not None else None

    try:
        response = requests.get(url, timeout=timeout)
        response.raise_for_status()          # raise on non‑2xx
        return response.text                 # raw body string
    except requests.exceptions.Timeout as exc:
        raise RuntimeError(f"Request timed out after {timeout_ms} ms") from exc
    except requests.exceptions.RequestException as exc:
        raise  # re‑raise other network / HTTP errors
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    import sys, pathlib

    url = "https://httpbin.org/delay/5"
    ms   = int(sys.argv[1]) if len(sys.argv) > 1 else None
    try:
        body = get_with_timeout(url, timeout_ms=ms)
        print("First 40 characters of response:", body[:40], "... (truncated)")
    except Exception as e:
        sys.exit(str(e))
```

**Key points**

* `requests.get(..., timeout=timeout)` uses seconds; we convert milliseconds → seconds.
* `raise_for_status()` guarantees a clear exception on HTTP errors.
* The function returns **only the text body**, perfect for downstream processing.

