// get_with_timeout.go ------------------------------------------------------
package main

import (
	"bytes"
	"context"
	"io/ioutil"
	"net/http"
	"time"

	"github.com/pkg/errors" // optional, provides richer errors
)

// GetWithTimeout returns the HTTP GET response body as a string.
//
// timeoutMs: 0 (default) → no explicit timeout; positive value sets a deadline.
func GetWithTimeout(url string, timeoutMs int64) (string, error) {
	ctx := context.Background()
	if timeoutMs > 0 {
		var cancel func()
		ctx, cancel = context.WithTimeout(ctx, time.Duration(timeoutMs)*time.Millisecond)
		defer cancel() // ensure cancellation even if fetch never returns
	}

	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return "", errors.Wrap(err, "failed to build request")
	}
	resp, err := http.DefaultClient.Do(req.WithContext(ctx))
	if err != nil {
		return "", errors.Wrapf(err, "HTTP GET %s", url)
	}
	defer resp.Body.Close()

	if !((200 <= resp.StatusCode) && (resp.StatusCode < 300)) {
