  // getWithTimeout.ts ---------------------------------------------------------
  import { setTimeout } from 'timers/promises'; // Node ≥ v18 provides this helper
  
  /**
   * Performs an HTTP GET request with a timeout.
   *
   * @param url            The URL to fetch.
   * @param timeoutMs      Timeout in milliseconds (0 = no timeout).
   * @returns              Promise<string> – the response body as string.
   */
  export async function getWithTimeout(
    url: string,
    timeoutMs: number = 10_000 // default 10 s
  ): Promise<string> {
    const controller = new AbortController();
    const id          = setTimeout(() => controller.abort(), timeoutMs);
  
    try {
      const response = await fetch(url, { signal: controller.signal });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      // Read the whole body as text (throws on network errors)
      return await response.text();
    } finally {
      clearTimeout(id);               // cancel any pending timer
      controller.abort();             // ensure abort() is called even if fetch rejects
    }
  }
  // ---------------------------------------------------------------------------
  
  /* Example usage ---------------------------------------------------------- */
  import { getWithTimeout } from './getWithTimeout';
  
  (async () => {
    try {
      const body = await getWithTimeout('https://httpbin.org/delay/5', 3000);
      console.log('Body (first few chars):', body.slice(0, 30) + '…');
    } catch (e: any) {
      // e may be an AbortError or generic Error
      console.error('Request failed:', e.message);
    }
  })();
  ```
  
