// websocket-client.ts
import { WebSocket } from "ws";

const ws = new WebSocket("wss://echo.websocket.org"); // replace with your endpoint

/**
 * Helper – pretty‑print a received message.
 */
function printMessage(msg: string | ArrayBufferView) {
  if (typeof msg === "string") {
    console.log(`🟢 Received text: ${msg}`);
  } else {
    const data = Array.from(new Uint8Array(msg as ArrayBuffer));
    // Show first few bytes for readability
    const hex = data.slice(0, Math.min(16, data.length)).map(b => b.toString(16).padStart(2, "0")).join(" ");
    console.log(`🟢 Received binary (first 16 bytes): ${hex}`);
  }
}

// ---- Event handlers -------------------------------------------------
ws.onopen = () => {
  console.log("✅ WebSocket opened");
};

ws.onmessage = (event) => {
  printMessage(event.data);
};

ws.onerror = (error) => {
  console.error("❌ WebSocket error:", error);
};

ws.onclose = (_code, _reason) => {
  // The connection may be reopened automatically if you call ws.close() later.
  console.log("🔚 WebSocket closed");
};
// ---------------------------------------------------------------------

// Send a test message right after opening
if (ws.readyState === WebSocket.OPEN) {
  const payload = JSON.stringify({ type: "ping", timestamp: Date.now() });
  ws.send(payload);
} else {
  // If the socket isn’t open yet, you can wait for `open` event or use `.on("open", ...)`
}
```

