#!/usr/bin/env python3
import asyncio
import json
from websockets import connect, WebSocketException


async def main():
    uri = "wss://echo.websocket.org"   # replace with your endpoint

    async with connect(uri) as ws:
        print("✅ Connected to:", uri)

        # Send a JSON payload (you can change the data)
        message = {"type": "ping", "timestamp": int(asyncio.get_event_loop().time())}
        await ws.send(json.dumps(message))
        print(f"📡 Sent: {message}")

        try:
            async for msg in ws:
                # `msg` is a string when using text protocol; binary otherwise
                if isinstance(msg, str):
                    print("🟢 Received text:", msg)
                else:
                    # Convert bytes to hex for readability
                    hex_repr = ":".join(f"{b:02x}" for b in msg)
                    print("🟢 Received binary (first few bytes):", hex_repr[:20])
        except WebSocketException as e:
            print("❌ Websocket error:", e)


if __name__ == "__main__":
    asyncio.run(main())
```

