## TypeScript

```ts
/**
 * Reads a CSV string and returns an array of objects keyed by the header row.
 *
 * @param csv - The CSV data as a single string. First line must be the header.
 * @returns An array of objects, one per row (excluding header).
 */
export function readCSV(csv: string): Record<string, unknown>[] {
  // Split into lines and strip whitespace
  const rows = csv.split(/\r?\n/).map(line => line.trim());

  if (!rows.length) {
    throw new Error('Empty CSV provided');
  }

  const headers = rows[0].split(',').map(h => h.trim());
  const result: Record<string, unknown>[] = [];

  // Helper to safely parse numbers when possible
  function coerce(value: string): number | boolean | string {
    if (value === '') return '';
    const num = Number(value);
    if (!isNaN(num)) {
      // Preserve integers as numbers, not strings
      return Number.isInteger(num) ? num : num;
    }
    const lower = value.toLowerCase();
    if (lower === 'true') return true;
    if (lower === 'false') return false;
    return value; // leave as string otherwise
  }

  for (let i = 1; i < rows.length; i++) {
    const values = rows[i].split(',');
    // Pad shorter rows with empty strings so we still get a key‑value pair per header
    while (values.length < headers.length) values.push('');
    const obj: Record<string, unknown> = {};
    for (let j = 0; j < headers.length; j++) {
      obj[headers[j]] = coerce(values[j]);
    }
    result.push(obj);
  }

  return result;
}
```

