import csv
from typing import List, Dict, Any

def read_csv(file_path: str) -> List[Dict[str, Any]]:
    """
    Reads a CSV file and returns a list of dictionaries keyed by the header row.

    :param file_path: Path to the CSV file (UTF‑8 encoded).
    :return: List of objects; each dict corresponds to one data row.
    """
    with open(file_path, newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        rows = list(reader)

    if not rows:
        return []

    headers = [h.strip() for h in rows[0]]
    result: List[Dict[str, Any]] = []

    def coerce(val: str) -> Any:
        """Attempt to convert a string value to int/float/bool when possible."""
        val = val.strip()
        if not val:
            return ''
        try:
            num = float(val)
            # Preserve ints as Python int
            return int(num) if num.is_integer() else num
        except ValueError:
            pass

        lower = val.lower()
        if lower == 'true':
            return True
        if lower == 'false':
            return False
        return val  # fallback to string

    for row in rows[1:]:          # skip header row
        values = [coerce(v) for v in row]
        result.append(dict(zip(headers, values)))

    return result


