// CSVRow is a helper type for the result.
type CSVRow map[string]interface{}

func readCSV(filePath string) ([]CSVRow, error) {
	f, err := os.Open(filePath)
	if err != nil {
		return nil, fmt.Errorf("open file: %w", err)
	}
	defer f.Close()

	r := csv.NewReader(f)
	rows, err := r.ReadAll()
	if err != nil {
		return nil, fmt.Errorf("read CSV rows: %w", err)
	}

	if len(rows) == 0 {
		return []CSVRow{}, nil
	}

	headers := make([]string, len(rows[0]))
	for i, v := range rows[0] {
		headers[i] = v // trim whitespace if needed
	}
	result := []CSVRow{}

	// Helper to coerce string values when possible
	coerce := func(s string) interface{} {
		if s == "" {
			return ""
		}
		v, err := strconv.ParseFloat(s, 64)
		if err == nil && v == float64(int(v)) {
			return int(v) // preserve ints as Go int
		}
		switch s {
		case "true":
			return true
		case "false":
			return false
		default:
			return s
		}
	}

	for _, row := range rows[1:] { // skip header row
		obj := make(CSVRow)
		for i, v := range row {
			obj[headers[i]] = coerce(v)
		}
		result = append(result, obj)
	}

	return result, nil
}

