// cli.ts --------------------------------------------------------------
#!/usr/bin/env node

/**
 * Simple CLI argument parser that supports:
 *   • Flags      – -f|--flag          (no value)
 *   • Options    – --output=file.txt  (requires a value)
 *   • Positionals– positional args after flags/options
 *
 * Usage: ts-node cli.ts [--debug] [-o output.txt] file1 [file2 …]
 */

import { exit } from "process";

// Helper to parse the arguments array manually.
function parseArgs(argv: string[]): {
  flags: Record<string, unknown>;
  options: Record<string, unknown>;
  positionals: string[];
} {
  const flags = {};
  const options = {};
  const positionals = [];

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];

    // Flag – short (-f) or long (--flag)
    if (/^--?[\w-]+$/.test(arg)) {
      // If the next token is a value, treat it as an option; otherwise flag.
      let value: unknown;
      if (i + 1 < argv.length && !/^--?[\w-]+$/.test(argv[i + 1])) {
        value = argv[++i]; // consume next token
      } else {
        value = true; // default boolean flag
      }
      flags[arg] = value;
      i++;
      continue;
    }

    // Option – long (--output=…) or short (-o)
    if (/^--?[\w-]+=(.*)$/.test(arg)) {
      const match = arg.match(/^--?([\w-]+)=(.*)$/) || [];
      options[match![1]] = true; // default boolean option
      i++;
      continue;
    }

    // Anything else is a positional argument.
    positionals.push(arg);
    i++;
  }
  return { flags, options, positionals };
}

// -------------------------------------------------------------------
const argv = process.argv.slice(2);          // drop the script name
const parsed = parseArgs(argv);

// Example usage – print everything nicely:
console.log("Flags:", JSON.stringify(parsed.flags, null, 2));
console.log("Options:", JSON.stringify(parsed.options, null, 2));
console.log("Positionals:", parsed.positionals.join(" "));

// -------------------------------------------------------------------
if (parsed.positionals.length === 0) {
  console.error(
    `❌ No positional arguments provided. Usage:\n` +
      `$ ${process.argv[0]} ${process.argv[1]} [--debug] [-o output.txt] file1 [file2 …]\n`
  );
  exit(1);
}

// -------------------------------------------------------------------
// In a real app you would now process the parsed values.
// For demo purposes we just echo them:
