#!/usr/bin/env python3
"""
CLI argument parser supporting:
 * Flags      – -f|--flag          (no value)
 * Options    – --output=file.txt  (requires a value)
 * Positionals– positional args after flags/options

Usage: python cli.py [--debug] [-o output.txt] file1 [file2 …]
"""

import argparse
import sys
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(
        description="Simple CLI demo – flags, options & positionals."
    )

    # Flags (boolean)
    parser.add_argument(
        "--debug",
        action="store_true",
        help="Enable debug output.",
    )

    # Options with required value
    parser.add_argument(
        "-o", "--output", type=Path, default=None,
        help="Output file path. If omitted the script writes to stdout."
    )

    # Positional arguments (one or more)
    parser.add_argument(
        "files",
        nargs="+",
        help="One or more input files.",
    )

    args = parser.parse_args()

    # ---- Demo logic -------------------------------------------------
    print("\n=== DEMO ===")
    if getattr(args, "debug", False):
        print("Debug mode enabled.")
    else:
        print("Debug mode disabled.")

    output_path = args.output
    sep = ", "
    if output_path and output_path.is_file():
        # If the file exists we treat it as a list of paths (optional)
        files = [str(p) for p in Path(args.output).read_text().splitlines()]
    else:
        files = args.files

    print("Input files:", sep.join(files))


if __name__ == "__main__":
    main()
