// Helper to parse flags manually – similar to Python/TS examples.
func parseArgs() (flags map[string]bool, options map[string]string, pos []string) {
	flags = make(map[string]bool)
	options = make(map[string]string)
	pos = []string{}

	i := 1
	for i < len(os.Args) {
		arg := os.Args[i]
		switch arg {
		case "--debug":
			flags["debug"] = true
		case "-o", "--output":
			if i+1 < len(os.Args) && !strings.HasPrefix(os.Args[i+1], "-") {
				options["output"] = os.Args[i+1]
				i++
			} else {
				options["output"] = "true" // default boolean option
			}
		default:
			pos = append(pos, arg)
		}
		i++
	}

	return flags, options, pos
}

func main() {
	flags, opts, pos := parseArgs()

	fmt.Println("\n=== DEMO ===")
	if flags["debug"] {
		fmt.Println("Debug mode enabled.")
	} else {
		fmt.Println("Debug mode disabled.")
	}

	outputPath := opts["output"]
	seps := ", "
	var files []string
	if outputPath != "" && outputPath != "true" {
		files = strings.Split(outputPath, seps)
	} else {
		files = pos
	}
	fmt.Print("Input files:", strings.Join(files, seps))
}
