## 1️⃣ TypeScript (Node.js)

```ts
// kvstore.ts --------------------------------------------------------------
import { readFileSync, writeFileSync } from "fs";
import { join } from "path";

/**
 * Path to the JSON file that holds the key‑value pairs.
 */
const STORE_PATH = "./kv_store.json";

/**
 * Initialise the store – creates an empty object if the file does not exist
 * or parses it; otherwise throws on malformed content.
 */
function initStore(): Record<string, unknown> {
  try {
    const raw = readFileSync(STORE_PATH, "utf8");
    return JSON.parse(raw) as Record<string, unknown>;
  } catch (err: any) {
    if (err.code !== "ENOENT") throw err; // file missing → treat as empty
    return {};
  }
}

/**
 * Get the value for a given key. Returns `undefined` if the key does not exist.
 */
export function get(key: string): unknown | undefined {
  const store = initStore();
  return store[key];
}

/**
 * Set (or replace) the value for a given key.
 *
 * @param overwrite – If true, existing values are overwritten; otherwise an
 *                   error is thrown when trying to set an already‑existing key.
 */
export function set(key: string, value: unknown, overwrite = false): void {
  const store = initStore();
  if (!overwrite && store[key] !== undefined) {
    throw new Error(`Key "${key}" already exists`);
  }
  store[key] = value;
  writeFileSync(STORE_PATH, JSON.stringify(store, null, 2));
}

/**
 * Delete a key from the store.
 *
 * @param silent – If true, no error is thrown when the key does not exist.
 */
export function deleteKey(key: string, silent = false): void {
  const store = initStore();
  if (store[key] === undefined && !silent) {
    throw new Error(`Key "${key}" does not exist`);
  }
  delete store[key];
  writeFileSync(STORE_PATH, JSON.stringify(store, null, 2));
}

// -----------------------------------------------------------------------
```

**Usage example**

```ts
import { get, set, deleteKey } from "./kvstore";

set("username", "alice");
console.log(get("username")); // → alice

set("enabled", true);          // overwrite existing value
deleteKey("enabled");         // removes the key
// deleteKey("nonexistent");   // uncomment to see an error (or use silent:true)
```

*Notes*

- The file `kv_store.json` lives in the same directory as the script.
- Values are stored exactly as written (`string`, `number`, `boolean`, `null`, objects, arrays …). If you need a stricter schema, add validation logic inside `set`.
- Errors thrown by `get/set/deleteKey` can be caught and handled gracefully (e.g., fallback defaults).

