  # kvstore.py ---------------------------------------------------------------
  import json
  from pathlib import Path
  
  
  STORE_PATH = Path("./kv_store.json")
  
  
  def _load() -> dict:
      """Load the JSON file, creating an empty dict if missing."""
      try:
          return json.loads(STORE_PATH.read_text(encoding="utf-8"))
      except (json.JSONDecodeError, FileNotFoundError):
          return {}
  
  
  def get(key: str) -> any | None:
      """
      Return the value for *key* or `None` if it does not exist.
      Use `get(key, default)` pattern to avoid explicit checks.
      """
      store = _load()
      return store.get(key)
  
  
  def set(key: str, value: any, overwrite=False):
      """
      Set (or replace) the value for *key*.
  
      - If `overwrite` is False and the key already exists, a ValueError is raised.
      - The file is written with pretty‑printing (indent=2).
      """
      store = _load()
      if not overwrite and store.get(key) is not None:
          raise ValueError(f"Key '{key}' already exists")
      store[key] = value
      STORE_PATH.write_text(json.dumps(store, ensure_ascii=False, indent=2), encoding="utf-8")
  
  
  def delete_key(key: str, *, silent=False):
      """
      Delete a key.
  
      - If the key does not exist and `silent` is False, raises KeyError.
      - Returns nothing (the file reflects the change).
      """
      store = _load()
      if store.get(key) is None and not silent:
          raise KeyError(f"Key '{key}' does not exist")
      del store[key]
      STORE_PATH.write_text(json.dumps(store, ensure_ascii=False, indent=2))
  ```
  
