  package main
  
  import (
  	"encoding/json"
  	"fmt"
  	"os"
  )
  
  const storePath = "./kv_store.json"
  
  type KVStore map[string]any
  
  func initKV() KVStore {
  	if _, err := os.Stat(storePath); os.IsNotExist(err) {
  		return make(KVStore)
  	}
  	data, err := os.ReadFile(storePath)
  	if err != nil {
  		panic(fmt.Sprintf("cannot read kv store: %v", err))
  	}
  	var store KVStore
  	err = json.Unmarshal(data, &store)
  	if err != nil {
  		panic(fmt.Sprintf("invalid JSON in kv store: %v", err))
  	}
  	return store
  }
  
  // get returns the value for a key or nil if not present.
  func Get(key string) any {
  	store := initKV()
  	v, _ := store[key]
  	return v
  }
  
  // set inserts/overwrites a key/value pair. Panics on duplicate unless silent=true.
  func Set(key string, value any, overwrite bool) {
  	store := initKV()
  	if !overwrite && _, exists := store[key]; exists {
  		panic(fmt.Sprintf("key '%s' already exists", key))
  	}
  	store[key] = value
  	data, err := json.MarshalIndent(store, "", "  ")
  	if err != nil {
  		panic(err)
  	}
  	if err := os.WriteFile(storePath, data, 0o644); err != nil {
  		panic(err)
  	}
  }
  
  // delete removes a key. Panics if the key does not exist unless silent=true.
  func Delete(key string, silent bool) {
  	store := initKV()
  	if _, exists := store[key]; !exists && !silent {
  		panic(fmt.Sprintf("key '%s' does not exist", key))
  	}
  	delete(store, key)
  	data, err := json.MarshalIndent(store, "", "  ")
  	if err != nil {
  		panic(err)
  	}
  	if err := os.WriteFile(storePath, data, 0o644); err != nil {
  		panic(err)
  	}
  }
  
  // -----------------------------------------------------------------------
