	 Password: os.Getenv("REDIS_PASSWORD"),   // optional
	 DB:       0,                             // default DB (usually 0)
	}

	ctx := context.Background()

	// -------------------------------------------------
	// 1. Connect & ping
	if err := client.Ping(ctx).Err(); err != nil {
		log.Fatalf("cannot connect to Redis: %v", err)
	}
	fmt.Println("[GO] Connected")

	// -------------------------------------------------
	// 2. Set key with TTL (seconds)
	key := "demo:key"
	value := "Hello from Go!"
	ttl, _ := strconv.Atoi(os.Getenv("REDIS_TTL", "10")) // default 10s
	if err := client.Set(ctx, key, value, time.Duration(ttl)*time.Second).Err(); err != nil {
		log.Fatalf("cannot set key: %v", err)
	}
	fmt.Printf("[GO] SET → %q : %q\n", key, value)

	// -------------------------------------------------
	// 3. Get the value back
	fetchedVal, err := client.Get(ctx, key).Result()
	if err != nil {
		log.Fatalf("cannot get key: %v", err)
	}
	fmt.Printf("[GO] GET → %q : %q\n", key, fetchedVal)

	client.Close()
}

func main() {
	run()
}
