## 1️⃣ TypeScript (Node.js)

```ts
// streamJsonArray.ts
import { createReadStream, ReadStream } from 'fs';
import { pipeline } from 'stream';
import { Transform } from 'stream';

/**
 * Stream a JSON array from disk without loading the whole file.
 *
 * @param filePath – path to the JSON file (relative to process.cwd())
 * @param onItem   – called for each parsed object
 * @param onError  – error handler
 */
export function streamJsonArray(
  filePath: string,
  onItem: (item: any) => void,
  onError?: (err: Error) => void
): ReadStream {
  const rs = createReadStream(filePath);

  // Transform JSON lines → objects, emitting each item.
  const parser = new Transform({
    readableObjectMode: true,
    writableObjectMode: false,

    transform(chunk: Buffer, _: BufferEncoding, callback: () => void) {
      try {
        // Split on newline (or any line‑terminator sequence)
        const lines = chunk.toString().split(/\r?\n/);
        let remaining = '';
        for (let i = 0; i < lines.length; ++i) {
          if (!remaining && i === lines.length - 1) {
            // last piece may be incomplete – keep it
            remaining = lines[i];
            continue;
          }
          const line = remaining + lines[i];
          try {
            const item: any = JSON.parse(line);
            onItem(item);
          } catch (e) {
            onError?.(new Error(`JSON parse error at line "${line}"`));
          }
        }
        // push the leftover piece for next chunk
        if (remaining && remaining !== lines[lines.length - 1]) {
          rs.push(remaining + '\n');
        }
      } catch (e) {
        onError?.(e);
      }
      callback();
    },
  });

  pipeline(rs, parser, (err?: Error) => {
    if (err) onError?.(err);
    // ensure clean close
    rs.destroy();
  });

  return rs;
}
```

**Usage**

```ts
import { streamJsonArray } from './streamJsonArray';

// Example: process each user object as it arrives
streamJsonArray('data/users.json', (user) => {
  console.log(`Processing ${user.name}`);
}, (err) => {
  console.error('Error streaming JSON:', err);
});
```

*Why this works*: `createReadStream` returns a Node.js readable stream. The custom Transform stream parses each line as JSON, emitting items one‑by‑one and feeding only the next chunk into the OS buffer.

