# stream_json_array.py
import json
from pathlib import Path
from typing import Callable


def stream_json_array(
    file_path: str,
    on_item: Callable[[dict], None],
    *,
    on_error: Callable[[Exception], None] | None = None,
) -> Path:
    """
    Stream a JSON array from disk without loading the whole file.

    Reads line‑by‑line (each line expected to be valid JSON), parses it, and
    calls `on_item` for every parsed object. If parsing fails an error is
    passed to `on_error`.

    :param file_path: Path to the JSON array file.
    :param on_item: Called with each parsed dict.
    :param on_error: Optional callback for parse errors.
    """
    path = Path(file_path)

    # Open in text mode, iterate line by line (no buffering beyond OS buffer)
    with open(path, 'r', encoding='utf-8') as f:
        # Read a small buffer manually to handle incomplete lines across chunks
        while True:
            chunk = f.read(8192)          # read 8 KB at a time
            if not chunk:                 # EOF reached
                break

            # Split on newline; keep any leftover fragment for next iteration
            parts = chunk.splitlines()
            leftover = '' if parts[-1] == '' else parts.pop()

            for line in parts:
                try:
                    obj = json.loads(line)
                    on_item(obj)
                except json.JSONDecodeError as exc:
                    on_error?(exc)

        # If there is any remaining text after the last newline, treat it as a partial line
        if leftover and leftover.strip():
            try:
                obj = json.loads(leftover)
                on_item(obj)
            except json.JSONDecodeError as exc:
                on_error?(exc)


# ----------------------------------------------------------------------
# Example usage (can be placed in another module or run directly)

if __name__ == '__main__':
    def print_user(u):
        print(f'Processing {u.get("name")}')

    stream_json_array('data/users.json', print_user, on_error=lambda e: print('Parse error:', e))
```

**Key points**

* Reads the file line‑by‑line (`f.read(8192)`), keeping only a small buffer in memory.
* Handles incomplete JSON lines across chunk boundaries by buffering the tail of each read.
* Calls `on_item` for every successfully parsed object; any parse error is forwarded to `on_error`.

