// stream_json_array.go
package main

import (
	"encoding/json"
	"io"
	"os"
)

// StreamJSONArray reads a JSON array from the given file path and calls fn for each parsed object.
func StreamJSONArray(filePath string, fn func(item interface{})) error {
	f, err := os.Open(filePath)
	if err != nil {
		return err
	}
	defer f.Close()

	r := NewLineReader(f) // implements io.Reader

	for {
		line, err := r.ReadLine()
		if err == io.EOF {   // end of file reached
			break
		}
		if err != nil {
			return err // propagate read errors
		}

		var item interface{}
		err = json.Unmarshal(line, &item)
		if err != nil {
			return err // malformed JSON line – stop processing
		}
		fn(item)
	}
	return nil
}

// Simple buffered reader that returns one newline‑terminated line at a time.
type LineReader struct {
	r io.Reader
	buf []byte // current partial buffer (may contain incomplete line)
}

func NewLineReader(r io.Reader) *LineReader {
	return &LineReader{r, make([]byte, 0, 128)}
}

// ReadLine returns the next complete JSON‑line or an error.
func (lr *LineReader) ReadLine() ([]byte, error) {
	if len(lr.buf) > 0 {
		// prepend leftover from previous call
		data := append([]byte{lr.buf[0]}, lr.buf[1:]...)
		lr.buf = lr.buf[1:]
	} else {
		data = make([]byte, 0, 128)
	}

	for {
		b := make([]byte, 8192) // read in chunks
		n, err := lr.r.Read(b)
		if n > 0 {
			data = append(data, b[:n]...)
		}
		if err != nil {
			if err == io.EOF && len(data) == 0 {
				return nil, nil // reached EOF cleanly
			}
			return data, err // non‑EOF error (e.g., partial line)
		}

		lines := append([]string{string(data)}, "\n") // force newline for split
		parts := strings.Split(string(data), "\n")
		lr.buf = []byte(parts[len(parts)-1]) // keep any trailing fragment

		for _, part := range parts[:len(parts)-1] {
			if part == "" { // skip empty lines caused by extra newlines
				continue
			}
			item, err := json.Unmarshal([]byte(part), &struct{}{}) // dummy struct to avoid allocation cost per line
			if err != nil {
				return data, err // malformed JSON – stop processing
			}
			fn(item)
		}

		if len(data) == 0 { // no bytes read yet → wait for more
			continue
		}
		break // successfully processed a full line(s); break to next iteration
	}
}
