## 1️⃣ TypeScript implementation

```ts
// circuitBreaker.ts ---------------------------------------------------------

/**
 * Error thrown by a closed CircuitBreaker when it rejects a call.
 */
export class CircuitOpenError extends Error {
  constructor(message = "Circuit is open – requests are being rejected") {
    super(message);
    this.name = "CircuitOpenError";
  }
}

/**
 * A simple circuit‑breaker that opens after `maxFailures` consecutive failures
 * and stays closed for a recovery period `recoveryTimeout`.
 */
export class CircuitBreaker<T> {
  /** Number of allowed successful calls before the breaker closes again. */
  private readonly maxSuccesses: number;
  /** How long (in ms) to stay open after reaching maxFailures. */
  private readonly recoveryTimeoutMs: number;

  /** Counter for consecutive failures. */
  private failureCount = 0;
  /** Timestamp of when the circuit opened (or last reset). */
  private openSince?: number;

  constructor(
    options: {
      maxSuccesses: number;
      recoveryTimeoutMs: number;
    } = { maxSuccesses: 5, recoveryTimeoutMs: 30000 }
  ) {
    this.maxSuccesses = options.maxSuccesses!;
    this.recoveryTimeoutMs = options.recoveryTimeoutMs!;
  }

  /**
   * Call the guarded function.
   *
   * @param fn – The async (or sync) function that may throw / reject.
   * @returns Promise<T> – resolves if the call succeeds, otherwise throws
   *                       `CircuitOpenError` while the circuit is open.
   */
  public async call(fn: () => T | Promise<T>): Promise<T> {
    // ----- try to execute -------------------------------------------------
    try {
      const result = await fn();
      this.reset(); // success → reset counters & timer
      return result;
    } catch (e) {
      // If we are already open, just keep rejecting.
      if (this.isOpen()) {
        return Promise.reject(new CircuitOpenError());
      }

      // ----- failure handling -----------------------------------------------
      this.failureCount += 1;

      const shouldOpen = this.failureCount >= this.maxSuccesses;
      if (shouldOpen) {
        this.openSince = Date.now();
        // Reset the counter after opening so we don't keep counting forever.
        this.failureCount = 0;
      }

      throw new CircuitOpenError(); // reject immediately
    }
  }

  /** Manually reset the breaker to *closed* state. */
  public reset() {
    this.failureCount = 0;
    this.openSince = undefined;
  }

  /** Returns true if the circuit is currently open (i.e., all calls are rejected). */
  private isOpen(): boolean {
    return !!this.openSince && Date.now() - this.openSince < this.recoveryTimeoutMs;
  }
}
