// Example: a function that sometimes fails (e.g., network hiccup)
const riskyOperation = async () => {
  // Simulate success/failure with a random number generator.
  const ok = Math.random() > 0.7; // ~30% failure rate
  if (!ok) throw new Error("Simulated transient error");
  return "✅ Success";
};

// Create a breaker that allows up to 3 successes, then stays open for 5 seconds.
const cb = new CircuitBreaker({ maxSuccesses: 3, recoveryTimeoutMs: 5000 });

async function run() {
  try {
    const result = await cb.call(riskyOperation);
    console.log("Result:", result);
  } catch (err) {
    // When the circuit is open every call throws CircuitOpenError.
    if (err instanceof CircuitOpenError) {
      console.error("Circuit is OPEN – calls are being rejected.");
    }
  }
}

run();
```

