```python
# circuit_breaker.py ---------------------------------------------------------

import time
from typing import Callable, Any


class CircuitOpenError(Exception):
    """Raised when the circuit is open and all calls are rejected."""


class CircuitBreaker:
    """
    Simple circuit‑breaker that opens after `max_successes` consecutive failures,
    staying closed for a recovery period of `recovery_timeout_seconds`.
    """

    def __init__(
        self,
        max_successes: int = 5,
        recovery_timeout_seconds: float = 30.0,
    ):
        """
        :param max_successes: Number of allowed successful calls before closing.
        :param recovery_timeout_seconds: How long (seconds) to stay open after hitting the limit.
        """
        self.max_successes = max_successes
        self.recovery_timeout_seconds = recovery_timeout_seconds

        # Counters & timestamps
        self.failure_count = 0
        self.open_since: float | None = None   # epoch seconds

    def _is_open(self) -> bool:
        """True if the circuit is currently open (all calls rejected)."""
        return self.open_since is not None and (
            time.time() - self.open_since < self.recovery_timeout_seconds
        )

    def call(
        self,
        fn: Callable[[], Any],
    ) -> Any:
        """
        Execute `fn`. Returns its result on success, otherwise raises CircuitOpenError.

        :param fn: A callable that may raise any exception.
        :raises CircuitOpenError: when the circuit is open (all calls rejected).
        """
        try:
