// ------------------------------------------------------------
// memoize.ts – TTL cache implementation in plain JavaScript/TS
// ------------------------------------------------------------

/**
 * A simple TTL‑based memoizer.
 *
 * @template K - key type (e.g. string, number)
 * @template V - value type (the result of the function call)
 */
export class TTLCache<K, V> {
  /** Underlying storage: map from key → {value, expiresAt} */
  private readonly store = new Map<K, { value: V; expiresAt?: number }>();

  /** Default TTL in milliseconds. Use `undefined` for no expiration (default). */
  private ttlMs: number;

  constructor(ttlMs = undefined) {
    this.ttlMs = ttlMs;
  }

  /**
   * Retrieve a cached result.
   *
   * If the entry is missing, expired or never set, the callback is invoked
   * and its return value is stored with TTL before returning it.
   */
  get<KY extends K>(key: KY): V {
    const now = Date.now();
    const entry = this.store.get(key);

    if (entry) {
      // Entry exists – check expiration
      if (this.ttlMs !== undefined && now >= entry.expiresAt!) {
        // expired → delete and re‑invoke later
        this.store.delete(key);
      } else {
        return entry.value as V;
      }
    }

    // No valid entry or TTL never set – compute fresh value.
    const newValue = this.compute(key);

    if (this.ttlMs !== undefined) {
      // Store with explicit expiration timestamp
      this.store.set(key, { value: newValue, expiresAt: now + this.ttlMs });
    } else {
      // No TTL → keep forever (or until manually cleared)
      this.store.set(key, { value: newValue });
    }

    return newValue;
  }

  /** Manually invalidate a specific key */
  delete(key: K): void {
    this.store.delete(key);
  }

  /** Clear the whole cache */
  clear(): void {
    this.store.clear();
  }
}

/**
 * Helper – memoize any function that takes **exactly one** argument.
 *
 * @template T - input type (used as key)
 * @template R - output type
 * @param fn - original function: (arg:T) => R
 * @param ttlMs - TTL in ms; `undefined` means no expiration
 */
export function memoizeTTL<T, R>(
  fn: (arg: T) => R,
  ttlMs?: number // undefined = never expire
): (arg: T) => R {
  const cache = new TTLCache<T, R>(ttlMs);
  return (arg: T) => cache.get(arg);
}
```

