        """
        Decorator‑style usage.
        Example:

            @TTLCache(ttl_seconds=10)
            def expensive(arg):
                ...
        """
        cache = self
        def wrapper(k: Any) -> Any:
            return cache.get(k)
        # expose the original function name for introspection
        wrapper.__name__ = fn.__name__
        return wrapper

