package main

import (
	"sync"
	"time"
)

// TTLCache implements a thread‑safe memoizer with explicit TTL.
type TTLCache struct {
	mu      sync.RWMutex          // protects underlying map
	data    map[string]cacheItem   // key → {value, expireAt}
	ttlSec  float64               // seconds; 0 or <0 => no expiration
}

// cacheItem holds the computed value and its expiry timestamp.
type cacheItem struct {
	Value interface{}
	Expiry time.Time
}

func NewTTLCache(ttlSeconds float64) *TTLCache {
	return &TTLCache{
		data:    make(map[string]cacheItem),
		ttlSec:  ttlSeconds,
	}
}

// Get returns the cached value or computes it via `fn` if missing/invalid.
func (c *TTLCache) Get(key string, fn func() interface{}) interface{} {
	c.mu.RLock()
	item, ok := c.data[key]
	c.mu.RUnlock()

	if !ok {
		// No entry – compute fresh value
		value := fn()
		expireAt := time.Time{}
		if c.ttlSec > 0 && c.ttlSec >= 0 {
			expireAt = time.Now().Add(time.Duration(c.ttlSec) * time.Second)
		}
		c.Set(key, value, expireAt)
		return value
	}

	now := time.Now()
	if item.Expiry.IsZero() || now.Before(item.Expiry) {
		return item.Value
	}
	// expired – delete and recompute later
	delete(c.data, key)

	value := fn()
	expireAt := time.Time{}
	if c.ttlSec > 0 && c.ttlSec >= 0 {
		expireAt = now.Add(time.Duration(c.ttlSec) * time.Second)
	}
	c.Set(key, value, expireAt)
	return value
}

// Set inserts a key/value pair with an optional explicit expiry.
func (c *TTLCache) Set(key string, value interface{}, expiry time.Time) {
	c.mu.Lock()
	defer c.mu.Unlock()

	c.data[key] = cacheItem{Value: value, Expiry: expiry}
}

// Delete removes a specific entry.
func (c *TTLCache) Delete(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	delete(c.data, key)
}

// Clear wipes the whole cache.
func (c *TTLCache) Clear() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.data = make(map[string]cacheItem)
}
