/**
 * A simple Bloom filter for membership testing.
 *
 * @template T   The type of elements stored in the filter.
 */
export class BloomFilter<T> {
  /** Number of bits (size of the underlying bit array). */
  private readonly size: number;
  /** Number of hash functions used. */
  private readonly k: number;

  /** Bit array – each entry is a single byte so we can set/clear individual bits cheaply. */
  private readonly bits: Uint8Array;

  /**
   * @param expectedItems   Expected maximum number of items that will be added.
   *                        This lets us compute the optimal size and k for a given FP rate.
   * @param fpRate         Desired false‑positive probability (e.g., 0.01 → 1%).
   */
  constructor(expectedItems: number, private readonly fpRate: number) {
    // Optimal number of hash functions for a given expected load:
    const m = Math.ceil((expectedItems / fpRate) * Math.log(2)); // bits
    this.size = m;
    this.k = Math.floor(Math.log(2) * m); // ≈ (m/expectedItems)*ln2

    // Initialise bit array – each element is a byte; we treat every bit as 0 initially.
    this.bits = new Uint8Array(m);
  }

  /**
   * Add an item to the filter.
   */
  add(item: T): void {
    const hashes = hash(item, this.k);
    for (const h of hashes) {
      // Convert hash → index in [0, size‑1]
      const idx = h % this.size;
      // Set that bit – using bitwise OR to avoid race conditions.
      this.bits[idx >>> 3] |= 1 << (idx & 7); // shift by bits per byte
    }
  }

  /**
   * Test whether an item **might** be present.
   *
   * Returns `true` if all corresponding bits are set, otherwise `false`.
   */
  has(item: T): boolean {
    const hashes = hash(item, this.k);
    for (const h of hashes) {
      const idx = h % this.size;
      // If the bit is not set → definitely not present.
      if ((this.bits[idx >>> 3] & (1 << (idx & 7))) === 0) {
        return false;
      }
    }
    return true; // All bits set → probable presence.
  }

  /** Return a human‑readable string showing the current FP rate. */
  getFalsePositiveRate(): number {
    const m = this.size;
    const n = this.bits.reduce((sum, b) => sum + (b ? 8 : 0), 0);
    // Approximate expected false positives: m * exp(-k·ln2)^{n/m}
    return Math.exp(-Math.pow(this.k / m, n / m)) * m;
  }
}

/**
 * Simple hash function family.
 *
 * Uses MurmurHash3 (32‑bit) for speed and deterministic results across runs.
 */
function hash(value: unknown, k: number): Int32Array {
  const out = new Int32Array(k);
  // Convert the value to a string – this works for most primitives & objects.
  const str = JSON.stringify(value); // stable serialization
  let h1 = 0xdeadbeef | 0;
  let h2 = 0x41c6ce57 | 0;

  for (let i = 0; i < k; ++i) {
    // Simple djb2‑like mixing using the string’s bytes.
    const c = str.charCodeAt(i % str.length);
    h1 = Math.imul(h1 ^ c, 2654435761); // prime
    h2 = Math.imul(h2 ^ (c << 8), 2654435761);
    out[i] = ((h1 >>> 0) + (h2 >>> 0)) | 0;
  }
  return out;
}
