class BloomFilter:
    """
    A simple Bloom filter for membership testing.
    
    Parameters
    ----------
    expected_items : int
        Expected maximum number of items that will be added.
    fp_rate      : float (0.0 - 1.0)
        Desired false‑positive probability (e.g., 0.01 → 1%).
        
    Attributes
    ----------
    size           : int   # total bits in the bit array.
    k              : int   # number of hash functions used.
    bits           : bytearray
        Each byte stores up to 8 bits; we treat each bit independently.
    """

    def __init__(self, expected_items: int, fp_rate: float) -> None:
        self.size = int((expected_items / fp_rate) * (1.0 + 1e-9))   # safe upper bound
        self.k = int(1.4426950408889634 * self.size // expected_items)
        # Initialise all bits to zero.
        self.bits = bytearray(self.size)

    def add(self, item: Any) -> None:
        """Insert an element into the filter."""
        hashes = hash_item(item, self.k)
        for h in hashes:
            idx = h % self.size
            # Set bit at position `idx` (0‑indexed). 1 << (idx & 7) selects the correct byte offset.
            self.bits[idx >> 3] |= 1 << (idx & 7)

    def has(self, item: Any) -> bool:
        """Return True if *maybe* present; False if definitely absent."""
        hashes = hash_item(item, self.k)
        for h in hashes:
            idx = h % self.size
            # If any bit is zero → not present.
            if (self.bits[idx >> 3] & (1 << (idx & 7))) == 0:
                return False
        return True

    def false_positive_rate(self) -> float:
        """
        Approximate current FP rate based on bits set.

        Uses the formula: m * exp(-k^2 / n)
          where m = size, k = number of hash functions, n = total bits set.
        This is an approximation; exact value requires counting all bits.
        """
        # Count non‑zero bytes (each byte contributes 8 bits).
        num_set_bits = sum(b.bit_count() for b in self.bits)
        return self.size * (1.0 - (1.0 - 1/self.size)**(num_set_bits))

    def __repr__(self) -> str:
        fp = round(self.false_positive_rate(), 4)
        return f"BloomFilter(size={self.size}, k={self.k}, fp≈{fp})"


def hash_item(value: Any, num_hashes: int):
    """
    Produce `num_hashes` pseudo‑random integer hashes for a given item.
    
    Uses JSON serialization + djb2‑like mixing to guarantee deterministic output
    across runs and reasonable distribution.
    """
    # Stable string representation (handles most primitives & dicts/lists).
    s = json.dumps(value, sort_keys=True)
    h1, h2 = 0xdeadbeef | 0, 0x41c6ce57 | 0

    out = [0] * num_hashes
    for i in range(num_hashes):
        c = ord(s[i % len(s)])
        h1 = (h1 ^ c) * 2654435761   # prime multiplier
        h2 = (h2 ^ (c << 8)) * 2654435761
        out[i] = ((h1 >> 0) + (h2 >> 0)) & 0xffffffff

    return out


