## TypeScript

```ts
/**
 * Returns the maximum sum of any contiguous subarray of size k.
 *
 * @param nums - Array of numbers.
 * @param k    - Size of the sliding window.
 * @returns The maximum sum, or undefined if invalid input.
 */
function maxSlidingWindowSum(nums: number[], k: number): number | undefined {
  // Guard against invalid inputs
  if (!nums || k <= 0 || nums.length < k) return undefined;

  let currentSum = 0;
  for (let i = 0; i < k; ++i) {
    currentSum += nums[i];
  }
  let maxSum = currentSum;

  // Slide the window
  for (let i = k; i < nums.length; ++i) {
    currentSum += nums[i] - nums[i - k];   // add new, remove old
    if (currentSum > maxSum) maxSum = currentSum;
  }

  return maxSum;
}

// Example usage:
console.log(maxSlidingWindowSum([1,2,3,4,5], 3)); // → 12
