## 1. TypeScript

```ts
// bfs.ts --------------------------------------------------------------
type Graph = Record<string, string[]>;   // node → list of neighbours

/**
 * Returns the shortest path from start to target using BFS.
 *
 * @param graph – adjacency‑list representation of the graph
 * @param start – starting node identifier (string)
 * @param target – goal node identifier (string)
 * @returns an array of nodes representing the path, or `null` if unreachable
 */
function bfsShortestPath(
  graph: Graph,
  start: string,
  target: string
): string[] | null {
  // Early‑exit for trivial case
  if (!graph[start] || !graph[target]) return null;

  const queue = [{ node: start, path: [start] }];   // (currentNode, currentPath)
  const visited = new Set<string>([start]);

  while (queue.length > 0) {
    const { node, path } = queue.shift()!;          // FIFO order

    if (node === target) return path;               // found shortest route

    for (const neighbour of graph[node] || []) {
      if (!visited.has(neighbour)) {
        visited.add(neighbour);
        queue.push({ node: neighbour, path: [...path, neighbour] });
      }
    }
  }

  // No path exists
  return null;
}

// ---------------------------------------------------------------------
// Example usage -------------------------------------------------------
if (import.meta.main) {
  const g = {
    A: ["B", "C"],
    B: ["A", "D", "E"],
    C: ["A", "F"],
    D: ["B"],
    E: ["B", "F"],
    F: ["C", "E"]
  };

  console.log(bfsShortestPath(g, "A", "F")); // → ['A', 'C', 'F']
}
```

**How it works**

1. **Queue** stores `(node, path‑so‑far)`. Because we enqueue neighbours only when they haven’t been visited before, the first time we encounter `target` the path is guaranteed to be minimal.
2. The algorithm stops as soon as `target` appears in the queue’s front node – no further expansion needed.

