## 2. Python

```python
from collections import deque
from typing import List, Dict, Optional

Graph = Dict[str, List[str]]   # node → list of neighbours


def bfs_shortest_path(graph: Graph,
                      start: str,
                      target: str) -> Optional[List[str]]:
    """
    Returns the shortest path from `start` to `target` using BFS.
    If no path exists, returns None.

    Parameters
    ----------
    graph : Dict[str, List[str]]
        Adjacency‑list representation of the graph.
    start : str
        Starting node identifier.
    target : str
        Goal node identifier.

    Returns
    -------
    Optional[List[str]]
        Ordered list of nodes from `start` to `target`, or None if unreachable.
    """
    # Early exit for impossible cases
    if start not in graph or target not in graph:
        return None

    queue = deque([(start, [start])])
    visited = {start}

    while queue:
        node, path = queue.popleft()

        if node == target:
            return path

        for neighbour in graph[node]:
            if neighbour not in visited:
                visited.add(neighbour)
                queue.append((neighbour, path + [neighbour]))

    # No reachable path
    return None


