## 3. Go

```go
package main

import (
	"fmt"
)

// Graph represents an adjacency list: node → slice of neighbours (strings)
type Graph map[string][]string


func bfsShortestPath(graph Graph, start, target string) []string {
	if _, ok := graph[start]; !ok || _, ok = graph[target]; !ok {
		return nil // one side missing
	}

	type pair struct{ node string; path []string }
	queue := []pair{{start, []string{start}}}
	visited := make(map[string]bool)
	visited[start] = true

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]

		if cur.node == target {
			return cur.path
		}

		for _, nb := range graph[cur.node] {
			if !visited[nb] {
				visited[nb] = true
				newPath := make([]string, len(cur.path)+1)
				copy(newPath, cur.path)
				newPath[len(cur.path)] = nb
				queue = append(queue, pair{nb, newPath})
			}
		}
	}

	return nil // no path found
}


// ---------------------------------------------------------------------
func main() {
	g := Graph{
		"A": {"B", "C"},
		"B": {"A", "D", "E"},
		"C": {"A", "F"},
		"D": {"B"},
		"E": {"B", "F"},
		"F": {"C", "E"},
	}

	path := bfsShortestPath(g, "A", "F")
	fmt.Println(path) // → [A C F]
}
```

**Explanation**

* The `pair` struct bundles a node with the path taken to reach it.
* We use a plain slice for the queue because Go slices are efficient for FIFO operations in this context.
* Early exit when target is found; otherwise return `nil`.

