// topological-sort.ts
/**
 * Topological sort of a directed acyclic graph (DAG).
 *
 * Input:
 *   - `graph`: Map<Node, Set<Node>> where each key is a node and the set contains its outgoing neighbours.
 * Output: Array<Node> ordered such that for every edge u → v, u appears before v.
 *
 * Complexity:
 *   Time  – O(V + E)
 *   Space – O(V + E) (adjacency map + visited/set)
 */

import { Map } from "typescript-collections";

function topologicalSort<T>(graph: Map<T, Set<T>>): T[] {
    const indegree = new Map<T, number>(); // node → in‑degree
    const queue: T[] = [];                 // nodes with 0 incoming edges
    const result: T[] = [];

    // ---- Build indegree map -------------------------------------------------
    graph.forEach((_, neighbours) => {
        neighbours.forEach(nbr => indegree.set(nbr, (indegree.get(nbr) || 0) + 1));
    });
    graph.keys().forEach(node => {
        if (!indegree.has(node)) queue.push(node); // no incoming edges
    });

    // ---- BFS / Kahn's algorithm ---------------------------------------------
    while (queue.length > 0) {
        const node = queue.shift()!;
        result.push(node);

        const neighbours = graph.get(node);
        if (neighbours) {
            neighbours.forEach(nbr => {
                indegree.set(nbr, indegree.get(nbr)! - 1);
                if (indegree.get(nbr) === 0) queue.push(nbr);
            });
        }
    }

    // If we didn't process every node there is a cycle → should never happen for DAG
    if (result.length !== graph.size()) {
        throw new Error("Graph contains a cycle! Topological sort not possible.");
    }

    return result;
}

// --------------------------------------------------------------
// Example usage:
if (require.main === module) {
    // Build a tiny DAG: A -> B, A -> C, B -> D, C -> D
    const g = new Map<string, Set<string>>();
    g.set("A", new Set(["B", "C"]));
    g.set("B", new Set(["D"]));
    g.set("C", new Set(["D"]));
    g.set("D", new Set());

    console.log(topologicalSort(g)); // → ["A","B","C","D"] (order may vary for B/C)
}
```

