#!/usr/bin/env python3
"""
Topological sort of a directed acyclic graph (DAG).

Input:
    - `graph`: dict where keys are nodes and values are iterables/set of outgoing neighbours.
Output: list ordered such that for every edge u → v, u appears before v.

Complexity:
    Time  – O(V + E)
    Space – O(V + E) (adjacency map + visited set)
"""

from collections import defaultdict, deque
from typing import Any, Dict, Iterable, List

def topological_sort(graph: Dict[Any, Iterable[Any]]) -> List[Any]:
    # Build in‑degree dictionary
    indegree = {u: 0 for u in graph}
    for u in graph:
        for v in graph[u]:
            indegree[v] = indegree.get(v, 0) + 1

    # Queue nodes with zero incoming edges
    q = deque([u for u in indegree if indegree[u] == 0])
    result: List[Any] = []

    while q:
        u = q.popleft()
        result.append(u)

        # Decrease neighbours' indegree and enqueue when they hit 0
        for v in graph.get(u, ()):
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)

    if len(result) != len(graph):
        raise ValueError("Graph contains a cycle! Topological sort not possible.")
    return result


# --------------------------------------------------------------
if __name__ == "__main__":
    # Example DAG: A -> B, A -> C, B -> D, C -> D
    g = {
        "A": {"B", "C"},
        "B": {"D"},
        "C": {"D"},
        "D": set(),
    }
    print(topological_sort(g))   # → ['A', 'B', 'C', 'D'] (order of B/C may vary)
