package main

import (
	"container/list"
	"fmt"
)

// TopologicalSort returns a slice of nodes ordered so that for every edge u -> v,
// node u appears before node v.
func TopologicalSort(graph map[string][]string) []string {
	inDegree := make(map[string]int)
	for u := range graph {
		inDegree[u] = 0
	}
	// Compute in‑degrees from adjacency list
	for u, neighbors := range graph {
		for _, v := range neighbors {
			inDegree[v]++
		}
	}

	q := list.New()
	for node, deg := range inDegree {
		if deg == 0 {
			q.PushBack(node)
		}
	}

	var result []string
	for q.Len() > 0 {
		nodeStr := q.Front().Value.(string)
		result = append(result, nodeStr)

		nextList := graph[nodeStr]
		for _, v := range nextList {
			inDegree[v]--
			if inDegree[v] == 0 {
				q.PushBack(v)
			}
		}
	}

	if q.Len() != len(graph) {
		panic("Graph contains a cycle! Topological sort not possible.")
	}
	return result
}

// --------------------------------------------------------------
func main() {
	// Example DAG: A -> B, A -> C, B -> D, C -> D
	graph := map[string][]string{
		"A": {"B", "C"},
		"B": {"D"},
		"C": {"D"},
		"D": {},
	}

	order := TopologicalSort(graph)
	fmt.Println(order) // e.g. ["A","B","C","D"] (order of B/C may vary)
}
