/**
 * 0/1 Knapsack – recursive DP solution.
 *
 * @param values   Array of item values.
 * @param weights  Array of item weights.
 * @param capacity Maximum weight allowed in the knapsack.
 * @returns The maximum total value that can be carried.
 */
function knapsack(values: number[], weights: number[], capacity: number): number {
    const n = values.length;

    // memo[i][w] will hold the best value for first i items with capacity w
    const memo: Record<string, number> = {};

    function dp(i: number, w: number): number {
        if (i === 0 || w === 0) return 0;
        const key = `${i}-${w}`;
        if (key in memo) return memo[key];

        let result;
        // If the current item cannot be taken
        if (weights[i - 1] > w) {
            result = dp(i - 1, w);
        } else {
            // Take or not take the i‑th item and pick the better option
            const withItem = values[i - 1] + dp(i - 1, w - weights[i - 1]);
            const withoutItem = dp(i - 1, w);
            result = Math.max(withItem, withoutItem);
        }
        memo[key] = result;
        return result;
    }

    return dp(n, capacity);
}

