def knapsack(values, weights, capacity):
    """
    Classic DP solution for the 0/1 Knapsack problem.
    
    Parameters:
      values     – list of item values (int or float)
      weights    – list of corresponding item weights
      capacity   – maximum total weight allowed
      
    Returns:
      Maximum achievable value under the given capacity.
    """
    n = len(values)
    # memo[i][w] stores best value using first i items and capacity w
    memo = {}

    def dp(i: int, w: int) -> float:
        if i == 0 or w == 0:
            return 0.0
        key = (i, w)
        if key in memo:
            return memo[key]

        # Item i-1 cannot be taken because it exceeds the current capacity
        if weights[i - 1] > w:
            result = dp(i - 1, w)
        else:
            # Either take item i‑1 or skip it; pick the better option
            with_item = values[i - 1] + dp(i - 1, w - weights[i - 1])
            without_item = dp(i - 1, w)
            result = max(with_item, without_item)

        memo[key] = result
        return result

    return dp(n, capacity)


