## 1. TypeScript (Node.js)

```ts
// messageQueue.ts ---------------------------------------------------------
import { Readable } from "stream";

/**
 * A thread‑safe in‑memory FIFO queue.
 *
 * Public API:
 *   enqueue(value) – push an item onto the back
 *   dequeue()       – pop an item from the front, throws if empty
 *   peek()          – return (but do not remove) the front item,
 *                     throws if empty.  Returns undefined only via error.
 */
export class MessageQueue<T> {
    private readonly queue: T[] = [];
    // `Array` methods are already atomic in V8/Node, but we guard with a lock
    // to make the intent explicit and to work on platforms where that isn’t true.
    private readonly mutex = new (require("events").EventEmitter)();

    /**
     * Push an item onto the back of the queue.
     */
    public enqueue(value: T): void {
        this.mutex.emit("lock");               // acquire lock
        try {
            this.queue.push(value);
        } finally {
            this.mutex.emit("unlock");
        }
    }

    /**
     * Remove and return the front item, or throw if empty.
     *
     * @throws {Error} when queue is empty.
     */
    public dequeue(): T {
        this.mutex.emit("lock");
        try {
            const [first] = this.queue; // destructure to get first element
            const removed = this.queue.splice(0, 1)[0];
            return removed;
        } finally {
            this.mutex.emit("unlock");
        }
    }

    /**
     * Return the front item without removing it.
     *
     * @throws {Error} when queue is empty.
     */
    public peek(): T | undefined {
        this.mutex.emit("lock");
        try {
            return this.queue[0];
        } finally {
            this.mutex.emit("unlock");
        }
    }

    /** Helper to expose the internal stream for testing (optional). */
    // Uncomment if you need a readable stream:
    // public readonly items = new Readable({
    //   objectMode: true,
    //   read() {}
    // });
}
```

### How it works
* **`mutex`** – an `EventEmitter` that we treat as a lock.  
  * `lock()` → emit “lock”, wait for the event to fire, then release with `unlock`.  
  * All three public methods acquire the same emitter; because only one listener can be active at a time (the default), this gives mutual exclusion.
* The implementation uses plain JavaScript arrays (`push`, `splice(0,1)`). In V8/Node these operations are already atomic for single‑threaded accesses, but we still lock to guarantee correctness on platforms where that isn’t guaranteed.

### Usage example

```ts
import { MessageQueue } from "./messageQueue";

const mq = new MessageQueue<number>();

mq.enqueue(10);
mq.enqueue(20);

console.log(mq.peek()); // 10 – does not remove it
console.log(mq.dequeue()); // 10
console.log(mq.peek()); // 20

// Dequeue until empty (will throw when queue is exhausted)
while (true) {
    try {
        console.log("popped:", mq.dequeue());
    } catch (e: any) {
        if ((e as Error).message === "Queue is empty") break;
    }
}
