# scheduler.py -------------------------------------------------------------
import time
from typing import Callable, Any


class Scheduler:
    """
    Tiny task‑scheduler that runs callbacks at fixed intervals.

    Example usage:

        sched = Scheduler()
        def my_job():
            print("🕒 Tick")
        sched.schedule('my_tick', my_job, 2000)   # every 2 seconds
        # later…
        sched.cancel('my_tick')
        sched.stop()          # stop everything
    """

    _jobs: dict[str, tuple[Callable[..., Any], int]] = {}

    def schedule(self,
                 name: str,
                 cb: Callable[..., Any],
                 interval_ms: float) -> None:
        """
        Register a callback to be called every `interval_ms` ms.

        @param name   Unique identifier for the job.
        @param cb     The function to run repeatedly.
        @param interval_ms How often (in milliseconds) the callback should fire.
        """
        if name in self._jobs:
            raise ValueError(f"Job '{name}' already scheduled")
        timer_id = None
        def wrapper():
            try:
                cb()
            except Exception as exc:
                # Propagate or log – you can replace with your own error‑handling logic
                print(f"[Scheduler] Error in job '{name}': {exc}")
        timer_id = time.perf_counter()  # seconds since epoch (high‑res)
        self._jobs[name] = (cb, interval_ms)

    def cancel(self, name: str) -> None:
        """Cancel a previously‑registered job."""
        if name not in self._jobs:
            raise KeyError(f"No such scheduled job '{name}'")
        # No timer object to stop – we just forget it.
        del self._jobs[name]

    def stop(self) -> None:
        """Stop **all** scheduled jobs and clear the registry."""
        self._jobs.clear()
