## 3️⃣ Go

```go
// scheduler.go -----------------------------------------------------------
package main

import (
	"context"
	"fmt"
	"sync/atomic"
	"time"
)

type Scheduler struct {
	jobs map[string]*jobInfo   // name → {cb, ticker}
	mu   sync.Mutex
}

type jobInfo struct {
	cb    func()
	ticker *time.Ticker
}

func NewScheduler() *Scheduler {
	return &Scheduler{
		jobs: make(map[string]*jobInfo),
	}
}

// schedule registers a callback to be called every `interval` seconds.
func (s *Scheduler) Schedule(name string, cb func(), interval time.Duration) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, exists := s.jobs[name]; exists {
		return fmt.Errorf("job %q already scheduled", name)
	}
	ticker := time.NewTicker(interval)
	s.jobs[name] = &jobInfo{
		cb:    cb,
		ticker: ticker,
	}
	go func() {
		for range ticker.C {
			cb()
		}
	}()
	return nil
}

// Cancel stops a previously‑registered job.
func (s *Scheduler) Cancel(name string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	j, exists := s.jobs[name]
	if !exists {
		return fmt.Errorf("no such scheduled job %q", name)
	}
	delete(s.jobs, name)
	ticker := j.ticker
	ticker.Stop() // stop the goroutine that drives the loop
	return nil
}

// StopAll stops **every** registered job.
func (s *Scheduler) StopAll() {
	s.mu.Lock()
	defer s.mu.Unlock()

	for _, ji := range s.jobs {
		ji.ticker.Stop()
	}
	s.jobs = make(map[string]*jobInfo)
}
```

