  /**
   * A tiny task‑scheduler that runs registered callbacks at fixed intervals.
   *
   * Usage:
   *   const scheduler = new Scheduler();
   *   scheduler.schedule('myJob', () => console.log('Hello'), 2000);
   *   // … later …
   *   scheduler.stop();          // stop everything
   *   scheduler.cancel('myJob'); // cancel a specific job
   */
  export class Scheduler {
      /** Mapping from name → (callback, timerId) */
      private jobs: Record<string, [() => void, NodeJS.Timer | undefined]> = {};
  
      /**
       * Register a callback to be called every `intervalMs` milliseconds.
       *
       * @param name  Unique identifier for the job – used later to cancel it.
       * @param cb    The function to run repeatedly.
       * @param intervalMs How often (in ms) the callback should fire.
       */
      schedule(name: string, cb: () => void, intervalMs: number): void {
          if (this.jobs[name]) throw new Error(`Job "${name}" already scheduled`);
          const timer = setInterval(cb, intervalMs);
          this.jobs[name] = [cb, timer];
      }
  
      /**
       * Cancel a previously‑registered job by its name.
       *
       * @param name The identifier you gave when scheduling.
       */
      cancel(name: string): void {
          const [_, timer] = this.jobs[name];
          if (timer) clearInterval(timer);
          delete this.jobs[name];
      }
  
      /**
       * Stop **all** scheduled jobs and clean up references.
       */
      stop(): void {
          Object.values(this.jobs).forEach(([cb, timer]) => {
              if (timer) clearInterval(timer);
          });
          this.jobs = {};
      }
  }
