// ------------------------------------------------------------
// nextCronRun.ts
// ------------------------------------------------------------

/**
 * Parses a standard Unix‑cron expression (minute hour day month day-of-week)
 * and returns the POSIX timestamp of the **next** occurrence after `now`.
 *
 * @param cron - A string like "*/15 8-17 * * 1-5"
 * @returns The next run time as a Date object.
 */
export function getNextCronRun(cron: string): Date {
    const now = new Date();

    // Helper to parse each field and return an array of valid values
    const parseField = (field: string, min?: number, max?: number) => {
        if (!field) return [];
        try {
            // Support */N syntax as well as explicit ranges/commas
            const parts = field.split(/[\s*,\/-]/);
            const nums = new Set<number>();
            for (const p of parts) {
                if (p.startsWith('*')) continue;          // handled by the whole expression
                if (p.includes('/')) {
                    const [stepStr, rest] = p.split('/');
                    let step: number;
                    if (!rest) step = 1;
                    else step = Number(rest);
                    nums.add(step);                       // not a value list – ignore for next run calculation
                } else {
                    nums.add(Number(p));
                }
            }
            return Array.from(nums).filter(v => v >= (min ?? -Infinity)) &&
                   Array.from(nums).filter(v => v <= (max ?? Infinity));
        } catch (_) {
            throw new Error(`Invalid cron field "${field}"`);
        }
    };

    // Split the expression into its five fields
    const [m, h, d, M, dow] = cron.split(' ');

    if (m.length === 0 || h.length === 0 || d.length === 0 ||
        M.length === 0 || dow.length === 0) {
        throw new Error('Cron expression missing one or more fields');
    }

    // Build sets of allowed values for each field
    const minutes   = parseField(m, 0, 59);
    const hours      = parseField(h, 0, 23);
    const daysOfMonth= parseField(d, 1, 31);
    const months     = parseField(M);               // JAN‑DEC (no numeric range needed)
    const dowValues  = parseField(dow, 0, 7);       // SUN=0 … SAT=6

    // Helper to find the next value >= target in a sorted array
    const nextValueAfter = (arr: number[], target: number) => {
        for (const v of arr) {
            if (v > target) return v;
        }
        return null;   // no later occurrence within current month/day/etc.
    };

    // Determine the next minute, hour, day‑of‑month and month
    let nextMin = nextValueAfter(minutes, now.getMinutes());
    let nextHour = nextValueAfter(hours,  now.getHours());

    if (nextHour === null) {
        const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        // advance to the first day of the next month that contains a valid hour
        while (true) {
            const d2 = new Date(today);
            d2.setDate(d2.getDate() + 1);               // move to next day
            if (!nextValueAfter(daysOfMonth, d2.getDate())) continue;
            const h2 = new Date(d2.getFullYear(), d2.getMonth(), d2.getDate());
            nextHour = nextValueAfter(hours, h2.getHours());
            if (nextHour !== null) break;
        }
    }

    // If hour also failed to advance within the current month,
    // we need to jump to the first day of the next month
    let nextDayOfMonth: number | undefined;
    if (nextHour === null) {
        const d3 = new Date(now.getFullYear(), now.getMonth() + 1, 1);
        nextDayOfMonth = nextValueAfter(daysOfMonth, d3.getDate());
    } else {
        // otherwise we can reuse the current day
        nextDayOfMonth = now.getDate();
    }

    let nextMonth: number | undefined;
    if (nextDayOfMonth === null) {
        const m2 = new Date(now.getFullYear(), now.getMonth() + 1, 1);
        while (!nextValueAfter(months, m2.getMonth())) {
            m2.setMonth(m2.getMonth() + 1);
        }
        nextMonth = m2.getMonth();
    } else {
        // current month is fine; just use its value
        nextMonth = now.getMonth();
    }

    let nextDow: number | undefined;
    if (nextDayOfMonth === null) {
        const d4 = new Date(now.getFullYear(), now.getMonth(), 1);
        while (!dowValues.includes(d4.getDay())) d4.setDate(d4.getDate() + 1);
        nextDow = dowValues.indexOf(d4.getDay());
    } else {
        // current day is valid; keep it
        nextDow = now.getDay();
    }

    // Build the final Date object for the *next* occurrence.
    let nextDate: Date;
    if (nextMonth !== undefined) {
        // We have jumped to a new month or year – reset time parts appropriately
        const d5 = new Date(now.getFullYear(), nextMonth, 1);
        while (!dowValues.includes(d5.getDay())) d5.setDate(d5.getDate() + 1);
        nextDate = new Date(d5.getFullYear(), nextMonth, d5.getDate(),
                            nextHour ?? now.getHours(), nextMin ?? now.getMinutes(),
                            0); // seconds/MS are irrelevant for cron
    } else {
        const d6 = new Date(now.getFullYear(), now.getMonth(), nextDayOfMonth!);
        while (!dowValues.includes(d6.getDay())) d6.setDate(d6.getDate() + 1);
        nextDate = new Date(d6.getFullYear(),
                            now.getMonth(),
                            d6.getDate(),
                            nextHour ?? now.getHours(),
                            nextMin ?? now.getMinutes());
    }

    // If the computed date is *already* in the past, step forward one interval.
    if (nextDate <= now) {
        const incSecs = 0; // cron intervals are usually minute‑hour-day-month,
                          // but we can add a tiny delta to guarantee “after now”
        nextDate.setSeconds(nextDate.getSeconds() + 1);
    }

    return nextDate;
}

