#!/usr/bin/env python3
"""
next_cron_run.py

Parse a Unix cron expression (minute hour day-of-month month day-of-week)
and return the POSIX timestamp of the next occurrence after "now".
"""

import datetime
from typing import List, Tuple


def parse_field(field: str) -> List[int]:
    """
    Convert a single cron field into a sorted list of allowed integers.
    Supports */N syntax and explicit ranges/comma‑separated values.
    """
    if not field:
        return []
    parts = set()
    for part in field.split():
        # Split on /, -, or comma
        tokens = part.replace('/', ' ').replace('-', ' ').split(',')
        for tok in tokens:
            try:
                num = int(tok)
                parts.add(num)
            except ValueError:
                raise ValueError(f"Invalid cron token: {tok}")
    return sorted(parts)


def next_value_after(sorted_vals: List[int], target: int) -> int | None:
    """
    Return the smallest value >= target, or None if all values are < target.
    """
    for v in sorted_vals:
        if v > target:
            return v
    return None


def parse_cron(cron_expr: str) -> Tuple[List[int], List[int],
                                       List[int], List[int], List[int]]:
    fields = cron_expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must contain exactly five fields")
    minute, hour, dom, month, dow = fields
    minutes   = parse_field(minute)
    hours     = parse_field(hour)
    dom_vals  = parse_field(dom)
    months    = parse_field(month)          # JAN‑DEC (no numeric range needed)
    dow_vals  = parse_field(dow)

    return minutes, hours, dom_vals, months, dow_vals


def next_cron_run(cron_expr: str) -> datetime.datetime:
    """
    Compute the POSIX timestamp of the next cron execution after now.
    Returns a `datetime` object (UTC if no tzinfo is supplied).
    """
    # Current time
    now = datetime.datetime.now(datetime.timezone.utc)

    minutes, hours, dom_vals, months, dow_vals = parse_cron(cron_expr)

    def advance_field(field: List[int], target: int) -> int:
        nxt = next_value_after(field, target)
        if nxt is None:
            raise ValueError(f"No later value for {field} in current period")
        return nxt

    # ----- minute -----
    next_min = advance_field(minutes, now.minute)

    # ----- hour -----
    try:
        next_hour = advance_field(hours, now.hour)
    except ValueError:
        # Jump to first day of next month that contains a valid hour
        today = datetime.datetime.now(datetime.timezone.utc).date()
        while True:
            tomorrow = today + datetime.timedelta(days=1)
            d2 = datetime.datetime.combine(tomorrow,
                                           datetime.time(0, 0))
            if advance_field(hours, d2.hour) is not None:
                break
            today = tomorrow

        next_hour = advance_field(hours, now.replace(day=today.day).hour)

    # ----- day-of-month -----
    try:
        next_dom = advance_field(dom_vals, now.day)
    except ValueError:
        # No later day in current month → go to first valid day of next month
        d3 = datetime.datetime.now(datetime.timezone.utc).date()
        while True:
            d4 = d3 + datetime.timedelta(days=1)
            if advance_field(dom_vals, d4.day) is not None:
                break
            d3 = d3.replace(month=d3.month + 1) if d3.month < 12 else \
                 datetime.datetime.combine(datetime.date(now.year+1, 1, 1),
                                           datetime.time(0))
        next_dom = advance_field(dom_vals, d4.day)

    # ----- month -----
    try:
        next_month = advance_field(months, now.month)
    except ValueError:
        # No later month in current year → wrap to January of next year
        while True:
            m2 = datetime.datetime(now.year, now.month + 1 if now.month < 12 else 1,
                                   1).replace(day=1)   # force first day
            if advance_field(months, m2.month) is not None:
                break
            now = now.replace(year=now.year + 1)
        next_month = advance_field(months, now.month)

    # ----- dow (weekday) -----
    try:
        next_dow = next_value_after(dow_vals, now.weekday())
    except ValueError:
        # Walk forward to first day that matches any allowed dow
        d5 = datetime.datetime.now(datetime.timezone.utc).date()
        while not any((d5 + datetime.timedelta(days=i)).weekday() in dow_vals for i in range(7)):
            d5 += datetime.timedelta(days=1)
        next_dow = advance_field(dow_vals, (d5.weekday()))

    # Build the resulting datetime. If we had to jump months/years,
    # reset time parts appropriately.
    if next_month is not None:
        # New month/year – start at first day of that month then adjust hour/min
        d6 = datetime.datetime(now.year if next_month == now.month else now.year,
                               next_month, 1)
        while (d6.weekday() != next_dow):
            d6 += datetime.timedelta(days=1)

