## 1️⃣ TypeScript (Node ≥ 12)

```ts
// diff.ts ---------------------------------------------------------------
type JSONValue = object | string | number | boolean | null;

interface DiffResult {
    added: Record<string, JSONValue>;
    removed: Record<string, JSONValue>;
    modified: Record<string, [JSONValue, JSONValue]>;
}

/**
 * Recursively compare two JSON values and return the diff.
 *
 * @param oldVal  The “old” value (can be object or primitive)
 * @param newVal  The “new” value – must have the same type as oldVal
 * @returns DiffResult with added, removed, modified entries
 */
export function diffJSON(oldVal: JSONValue, newVal: JSONValue): DiffResult {
    const added: Record<string, JSONValue> = {};
    const removed: Record<string, JSONValue> = {};
    const modified: Record<string, [JSONValue, JSONValue]> = {};

    // Helper that works for both objects and arrays
    function walk(path: string[], o: JSONValue, n: JSONValue) {
        if (o === undefined || n === undefined) return; // nothing to diff

        // Primitive values – compare directly
        if (
            typeof o !== 'object' ||
            o === null ||
            Array.isArray(o)
        ) {
            if (JSON.stringify(o) !== JSON.stringify(n)) {
                modified[path.join('.')] = [o, n];
            }
            return;
        }

        // If one side is an array and the other isn’t – treat as removal of whole array
        const bothArrays = Array.isArray(o) && Array.isArray(n);
        if (bothArrays) {
            // Compare lengths first; then each element position‑wise
            if (o.length !== n.length) modified[path.join('.')] = [o, n];
            else for (let i = 0; i < o.length; ++i) walk([...path, String(i)], o[i], n[i]);
            return;
        }

        // Normal objects – recurse into each key
        const keysO = Object.keys(o);
        const keysN = Object.keys(n);

        // Keys removed from new object
        for (const k of keysO.filter(k => !keysN.includes(k))) {
            removed[`${path.join('.')}.${k}`] = o[k];
        }

        // Recurse into common keys and detect modifications
        for (const k of [...new Set(keysO).values()]) {
            if (!keysN.includes(k)) continue; // already handled above

            const newPath = [...path, k];
            walk(newPath, o[k], n[k]);
        }
    }

    walk([], oldVal, newVal);
    return { added, removed, modified };
}
// -----------------------------------------------------------------------
