import json
from typing import Any, Dict

DiffResult = Dict[str, Any]

def _walk(path: list, old_val: Any, new_val: Any) -> None:
    # Primitive values – compare directly
    if not isinstance(old_val, (dict, list)) or old_val is None \
       and not isinstance(new_val, (dict, list)) or new_val is None:
        if str(old_val) != str(new_val):
            diff["modified"] = [old_val, new_val]
        return

    # Both are dicts
    if isinstance(old_val, dict) and isinstance(new_val, dict):
        old_keys = set(old_val.keys())
        new_keys = set(new_val.keys())

        # Keys removed from the “new” side
        for k in old_keys - new_keys:
            diff["removed"][k] = old_val[k]

        # Recurse into common keys and detect modifications
        for k in old_keys.intersection(new_keys):
            _walk(path + [str(k)], old_val[k], new_val[k])
    # Both are lists – compare element‑by‑element by index
    elif isinstance(old_val, list) and isinstance(new_val, list):
        if len(old_val) != len(new_val):
            diff["modified"] = [old_val, new_val]
        else:
            for i, (o_item, n_item) in enumerate(zip(old_val, new_val)):
                _walk(path + [str(i)], o_item, n_item)
    # One side is a dict/list and the other isn’t → treat as removal of whole container
    else:
        diff["modified"] = [old_val, new_val]


def diff_json(old: Any, new: Any) -> DiffResult:
    """
    Return a dictionary with three keys:
      - added   : keys present in `new` but not in `old`
      - removed : keys present in `old` but missing from `new`
      - modified: entries that exist in both but have different values
    """
    diff = {"added": {}, "removed": {}, "modified": {}}
    _walk([], old, new)
    return diff


