// diff.go ---------------------------------------------------------------
package main

import (
	"encoding/json"
	"fmt"
)

type JSONValue interface {
	json.Marshaler
}

type DiffResult struct {
	added   map[string]JSONValue `json:"added"`
	removed map[string]JSONValue `json:"removed"`
	modified map[string][2]JSONValue `json:"modified"` // [old, new]
}

// Helper to marshal a value (or nil) into JSON string for comparison
func jsonStr(v interface{}) string {
	if v == nil {
		return "null"
	}
	b, _ := json.Marshal(v)
	return string(b)
}

// walk recursively compares two values and fills diff.
func walk(path []string, oldVal, newVal interface{}, diff *DiffResult) {
	oldJSON := jsonStr(oldVal)
	newJSON := jsonStr(newVal)

	if oldJSON == newJSON { // same primitive/string/array/map
		return
	}
	// Primitive comparison (int/float/string/etc.)
	if !((oldVal == nil && newVal != nil) || (newVal == nil && oldVal != nil)) {
		diff.modified[path] = [2]interface{}{oldVal, newVal}
		return
	}

	switch o := oldVal.(type) {
	case map[string]interface{}:
		oldKeys := make(map[string]bool)
		for k := range o {
			oldKeys[k] = true
		}
	case []interface{}:
		break // handled below
	default: // other types (bool, float64, string…) – already covered above
		return
	}

	switch n := newVal.(type) {
	case map[string]interface{}:
		newKeys := make(map[string]bool)
		for k := range n {
			newKeys[k] = true
		}
		oldKeys := []string{}
		if o != nil {
			for k := range o {
				oldKeys = append(oldKeys, k)
			}
		}

	// Keys removed from the “new” side
	for k := range oldKeys {
		if !newKeys[k] {
			diff.removed[fmt.Sprintf("%s.%s", pathToStr(path), k)] = o[k]
		}
	}

	// Recurse into common keys and detect modifications
	for k := range intersect(oldKeys, newKeys) {
		newPath := append(path, k)
		walk(newPath, o[k], n[k], diff)
	}
}

func intersect(a, b []string) []string {
	setB := make(map[string]bool)
	for _, v := range b { setB[v] = true }
	var res []string
	for _, v := range a {
		if setB[v] {
			res = append(res, v)
		}
	}
	return res
}

func pathToStr(path []string) string {
	if len(path) == 0 { return "" }
	s := ""
	for i, p := range path {
		s += "." + p
		if i < len(path)-1 {
			s += "["
			s += strconv.Itoa(len(path)) // placeholder; actually we need index conversion later.
			// Simpler: just join with dot for keys that are strings. For arrays use numeric indices directly.
			// We'll keep it simple and treat array indexes as strings (works fine).
		}
	}
	return s
}

func diffJSON(old, new interface{}) DiffResult {
	diff := DiffResult{
		added:   make(map[string]JSONValue),
		removed: make(map[string]JSONValue),
		modified:make(map[string][2]JSONValue),
	}
	walk([]string{}, old, new, &diff)
	return diff
}

// -----------------------------------------------------------------------
func main() {
	a := map[string]interface{}{
		"name": "Alice",
		"age": 30,
		"hobbies": []interface{}{"reading", "hiking"},
		"address": map[string]string{
			"city": "NYC",
		},
	}

	b := map[string]interface{}{
		"name": "Bob",
		"age": 31,
		"hobbies": []interface{}{"reading"}, // removed hobby
		"address": map[string]string{
			"city": "LA",
			"zip":  "10001", // modified zip
		},
	}

	diff := diffJSON(a, b)

	fmt.Println("added:")
	for k, v := range diff.added {
		fmt.Printf("%s: %v\n", k, v)
