	fmt.Println("\nremoved:")
	for k, v := range diff.removed {
		fmt.Printf("%s: %v\n", k, v)
	}
	fmt.Println("\nmodified (old,new):")
	for k, pair := range diff.modified {
		fmt.Printf("%s: [%v,%v]\n", k, pair[0], pair[1])
	}
}

