/* Example usage */
(() => {
  const src = 'AAAABBBCCD';
  console.log(`Original : "${src}"`);
  const comp = compress(src);
  console.log(`Compressed: "${comp}"`);
  const decomp = decompress(comp);
  console.log(`Decoded  : "${decomp}" (should match original)`);
})();
