# run_length.py -----------------------------------------------------------
def compress(text: str) -> str:
    """Run-length encode a string."""
    if not text:
        return ""
    result = []
    count = 1
    prev = text[0]

    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(f"{count}{prev}")
            prev = ch
            count = 1
    # last run
    result.append(f"{count}{prev}")

    return "".join(result)


def decompress(encoded: str) -> str:
    """Run-length decode a string."""
    if not encoded:
        return ""
    output = []
    i = 0

    while i < len(encoded):
        # consume the numeric part
        num_str = ""
        while i < len(encoded) and encoded[i].isdigit():
            num_str += encoded[i]
            i += 1
        count = int(num_str)

        # consume the character(s)
        char = ""
        while i < len(encoded) and encoded[i].isalpha():
            char += encoded[i]
            i += 1

        output.append(char * count)

    return "".join(output)


