// rle.go ---------------------------------------------------------------
package main

import (
	"bytes"
	"fmt"
)

// compress returns the RLE encoding of a string.
func compress(input string) string {
	if input == "" {
		return ""
	}
	var buf bytes.Buffer
	count := 1
	prev := input[0]

	for _, ch := range input[1:] {
		if ch == prev {
			count++
		} else {
			buf.WriteString(fmt.Sprintf("%d%c", count, prev))
			prev = ch
			count = 1
		}
	}
	buf.WriteString(fmt.Sprintf("%d%c", count, prev))

	return buf.String()
}

// decompress decodes a string produced by compress().
func decompress(encoded string) string {
	if encoded == "" {
		return ""
	}
	var output bytes.Buffer

	i := 0
	for i < len(encoded) {
		// read the number prefix
		num := 0
		for ; i < len(encoded) && '0' <= encoded[i] && encoded[i] <= '9'; i++ {
			num = num*10 + int(encoded[i]) - '0'
		}
		if num == 0 {
			panic("invalid encoding: missing digit after number")
		}

		// read the character(s)
		ch := ""
		for ; i < len(encoded) && ('a' <= encoded[i] || 'A' <= encoded[i]); i++ {
			ch += string(encoded[i])
		}
		output.WriteString(strings.Repeat(ch, num))
	}

	return output.String()
}

