  // runLength.ts -------------------------------------------------------------
  /**
   * Compress a string using run-length encoding.
   *
   * @param input The string to compress.
   * @returns Encoded string (e.g., "AAAABBBCCD" → "4A3B2C1D").
   */
  export function compress(input: string): string {
    if (!input) return '';
  
    let result = '';
    let count = 1;
    const lastChar = input[0];
  
    for (let i = 1; i < input.length; ++i) {
      if (input[i] === lastChar) {
        ++count;
      } else {
        // Append the run length and character
        result += `${count}${lastChar}`;
        // Reset for new char
        count = 1;
        lastChar = input[i];
      }
    }
    // Last run
    result += `${count}${lastChar}`;
  
    return result;
  }
  
  /**
   * Decompress a string that was encoded with compress().
   *
   * @param encoded The compressed string (e.g., "4A3B2C1D").
   * @returns Original uncompressed string.
   */
  export function decompress(encoded: string): string {
    if (!encoded) return '';
  
    let output = '';
    let i = 0;
    while (i < encoded.length) {
      // Read the numeric run length
      let numStr = '';
      while (i < encoded.length && /\d/.test(encoded[i])) {
        numStr += encoded[i];
        ++i;
      }
      const count = parseInt(numStr, 10);
      if (!count) throw new Error('Invalid encoding: missing digit after number');
  
      // Read the character
      let char = '';
      while (i < encoded.length && /[A-Za-z]/.test(encoded[i])) {
        char += encoded[i];
        ++i;
      }
      if (!char) throw new Error('Invalid encoding: missing character after digits');
  
      output += `${' '.repeat(count)}${char}`; // repeat the char count times
    }
  
    return output;
  }
  
