## 1️⃣ TypeScript (Node.js / Browser)

```ts
// pkce.ts --------------------------------------------------------------
import { randomBytes } from "crypto";
import * as url from "url";

/**
 * Generate a strong PKCE verifier.
 *
 * Recommended size: ≥128 bytes. Here we use 96 bytes → ~768 bits of entropy.
 */
function generateVerifier(): string {
  // crypto.randomBytes returns Buffer; toString('base64') would give +/=. We need URL‑safe Base64.
  const buf = randomBytes(96);               // 96 bytes ≈ 768 bits
  return buf.toString("base64url");         // RFC 4648 §5 (URL‑safe, no padding)
}

/**
 * Derive the PKCE `code_challenge` from a verifier using SHA‑256 + Base64‑URL.
 *
 * The challenge MUST be computed as:
 *   base64url( sha256(verifier ) )
 * and **without** any trailing '=' padding.
 */
function deriveChallenge(verifier: string): string {
  const hash = require("crypto").createHash("sha256");
  hash.update(verifier);
  const digest = hash.digest();               // Buffer
  return digest.toString("base64url");       // RFC 4648 §5 (URL‑safe, no padding)
}

/**
 * Example: request an authorization code from a PKCE‑enabled provider.
 */
async function requestToken(codeVerifier: string, challenge: string) {
  const authUrl = new URL("https://provider.com/auth");
  authUrl.searchParams.append("response_type", "code");          // or "token"
  authUrl.searchParams.append("client_id", "<YOUR_CLIENT_ID>");
  authUrl.searchParams.append("redirect_uri", encodeURIComponent("<REDIRECT_URI>"));
  authUrl.searchParams.append("code_challenge_method", "S256");
  authUrl.searchParams.append("code_challenge", challenge);

  console.log("\n🔐 Authorization URL:\n", authUrl.toString());
}

// ---------------------------------------------------------------------
(async () => {
  const verifier = generateVerifier();
  const challenge = deriveChallenge(verifier);
  console.log("\n✅ Generated PKCE pair:");
  console.log(`verifier   : ${verifier}`);
  console.log(`challenge  : ${challenge}`);

  // In a real flow you would now redirect the user to `authUrl.toString()`.
  await requestToken(verifier, challenge);
})();
```

