#!/usr/bin/env python3
import os, hashlib, base64, urllib.parse

def generate_verifier(length: int = 96) -> str:
    """Generate a URL‑safe Base64 string (no padding)."""
    # random.getrandbits gives an integer; convert to bytes.
    return base64.urlsafe_b64encode(os.urandom(length)).decode('ascii').rstrip('=')

def derive_challenge(verifier: str) -> str:
    """
    Compute PKCE `code_challenge` = SHA‑256 verifier → Base64‑URL (no padding).
    """
    digest = hashlib.sha256(verifier.encode()).digest()
    return base64.urlsafe_b64encode(digest).decode('ascii').rstrip('=')

def request_token(code_verifier: str, code_challenge: str):
    auth_url = "https://provider.com/auth"
    params = urllib.parse.urlencode({
        "response_type": "code",
        "client_id": "<YOUR_CLIENT_ID>",
        "redirect_uri": urllib.parse.quote("<REDIRECT_URI>"),
        "code_challenge_method": "S256",
        "code_challenge": code_challenge,
    })
    url = auth_url + "?" + params
    print("\n🔐 Authorization URL:\n", url)

if __name__ == "__main__":
    verifier = generate_verifier()
    challenge = derive_challenge(verifier)
    print("\n✅ Generated PKCE pair:")
    print(f"verifier   : {verifier}")
    print(f"challenge  : {challenge}")

    # Uncomment to actually redirect the user:
    # request_token(verifier, challenge)
