package main

import (
	"crypto/rand"
	"encoding/base64"
	"fmt"
	"hash/sha256"
	"net/url"
)

// ---------------------------------------------------------------------
// PKCE helpers -------------------------------------------------------
func generateVerifier(length int) (string, error) {
	b := make([]byte, length)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil // RawURLEncoding == urlbase64 without padding
}

// Derive challenge = SHA256(verifier) → Base64‑URL (no padding).
func deriveChallenge(verifier string) string {
	h := sha256.Sum256([]byte(verifier))
	enc := base64.RawURLEncoding.EncodeToString(h[:])
	return enc // already trimmed of '=' because RawEncoding strips it
}

// ---------------------------------------------------------------------
// Example: request token -------------------------------------------------
func requestToken(codeVerifier, codeChallenge string) {
	authURL, _ := url.Parse("https://provider.com/auth")
	q := authURL.Query()
	q.Set("response_type", "code")
	q.Set("client_id", "<YOUR_CLIENT_ID>")
	q.Set("redirect_uri", "<REDIRECT_URI>") // URL‑encode if needed
	q.Set("code_challenge_method", "S256")
	q.Set("code_challenge", codeChallenge)
	authURL.RawQuery = q.Encode()
	fmt.Println("\n🔐 Authorization URL:")
	fmt.Println(authURL.String())
}

func main() {
	verifier, err := generateVerifier(96) // 96 bytes ≈ 768 bits
	if err != nil {
		panic(err)
	}
	challenge := deriveChallenge(verifier)

	fmt.Println("\n✅ Generated PKCE pair:")
	fmt.Printf("verifier   : %s\n", verifier)
	fmt.Printf("challenge  : %s\n", challenge)

	requestToken(verifier, challenge)
}
