// rateLimit.ts -------------------------------------------------------------
import { Request, Response, NextFunction } from "express";

/**
 * Options for the middleware.
 */
export interface RateLimitOptions {
  /** Number of requests allowed per window. Default: 100 */
  limit?: number;
  /** Window length in seconds (e.g., 60). Default: 60 */
  windowMs?: number;
}

/**
 * Simple in‑memory rate limiter that can be used as middleware.
 *
 * @param ip - The client IP address (as a string)
 * @returns true if the request is allowed, false otherwise
 */
export function createRateLimitMiddleware(opts: RateLimitOptions = {}): (
  req: Request,
  res: Response,
  next: NextFunction,
) => void {
  const limit = opts.limit ?? 100;
  const windowMs = opts.windowMs ?? 60_000; // 1 minute

  /** In‑memory store */
  const storage = new Map<string, number>(); // ip → timestamp of last request

  return (req: Request, res: Response, next: NextFunction) => {
    const ip = req.ip || req.headers["x-forwarded-for"] ?? "unknown";

    // Clean up expired timestamps
    storage.forEach((ts, key) => {
      if (Date.now() - ts > windowMs) {
        storage.delete(key);
      }
    });

    // If we have fewer than `limit` requests in the last window → allow
    const now = Date.now();
    let count = storage.get(ip) ?? 0;
    if (count < limit) {
      storage.set(ip, now);               // record this request timestamp
      next();                              // continue to downstream handlers
      return true;                         // success flag for convenience
    }

    // Too many requests – reject with a friendly response
    res.status(429).json({
      error: "Too Many Requests",
      message: `You have exceeded the rate limit of ${limit} request(s) per ${windowMs / 1000}s window.`,
    });
    return false;                         // failure flag
  };
}

// --------------------------------------------------------------------------

// Example Express usage ----------------------------------------------------
import express from "express";
const app = express();

app.use(
  createRateLimitMiddleware({
    limit: 50,          // requests per minute
    windowMs: 60_000,   // 1 minute
  })
);

app.get("/", (req, res) => {
  res.send("Hello World – you are allowed!");
});

// --------------------------------------------------------------------------

if (require.main === module) {
  app.listen(3000, () => console.log("🚀 Server listening on :3000"));
}
```

**How it works**

1. **Middleware creation** (`createRateLimitMiddleware`) returns a function that runs for every request.
2. The middleware extracts the client IP from `req.ip` (or X‑Forwarded‑For).
3. It cleans out timestamps older than the configured window, then checks how many requests occurred in the last minute.
4. If ≤ limit → calls `next()`; otherwise returns a **429 Too Many Requests** JSON response.

