## 2️⃣ Python (Flask)

```python
# rate_limit.py -------------------------------------------------------------
from datetime import datetime, timedelta
from typing import Callable

from flask import Flask, request, jsonify, abort

def create_rate_limit_middleware(
    limit: int = 100,
    window_seconds: float = 60.0,
) -> Callable[[Flask], None]:
    """
    Returns a Flask middleware function that can be registered with `app.before_request`.

    Parameters
    ----------
    limit : number of requests allowed per window.
    window_seconds : length of the sliding time‑window (seconds).

    The internal storage is an in‑memory dict:
        ip_address → list[datetime]   # timestamps of recent calls
    """
    from collections import deque

    store: dict[str, list[datetime]] = {}

    def middleware(app):
        @app.before_request
        def _rate_limit():
            client_ip = request.remote_addr or request.headers.get("X-Forwarded-For", "unknown")
            now = datetime.utcnow()

            # Remove timestamps older than the window
            store.setdefault(client_ip, []).extend(
                [t for t in store[client_ip] if (now - t) <= timedelta(seconds=window_seconds)]
            )

            # If we already have `limit` requests in the last window → block
            if len(store[client_ip]) >= limit:
                abort(429, description=f"Too Many Requests. Limit of {limit} per {window_seconds}s.")
            
            # Otherwise record this request timestamp (deque would auto‑pop old entries)
            store[client_ip].append(now)

        return None  # no explicit return needed; middleware is attached via `before_request`

    return middleware

# --------------------------------------------------------------------------

if __name__ == "__main__":
    app = Flask(__name__)

    # Example usage:
    app.before_request(create_rate_limit_middleware(limit=30, window_seconds=60))

    @app.route("/")
    def hello():
        return "Hello World – you are allowed!"

    app.run(host="0.0.0.0", port=5000)
```

**Key points**

* Uses a **deque‑like list** (`store[client_ip]`) to keep timestamps.
* `before_request` hook runs *before* any view function, allowing us to abort early with HTTP 429.
* The same logic works for both synchronous and async Flask routes (the decorator is pure Python).

