  // rate_limit.go ------------------------------------------------------------
  package main
  
  import (
  	"net/http"
  	"sync/atomic"
  	"time"
  
  	"github.com/gorilla/mux" // optional, but shows a minimal pattern; you can also use std mux.
  )
  
  type RateLimitConfig struct {
  	Limit      int    // max requests per window
  	WindowSecs time.Duration
  }
  
  // Simple in‑memory store (IP → slice of timestamps)
  var ipTimestamps = make(map[string][]time.Time) // shared across goroutines
  
  func initRateLimit(cfg RateLimitConfig) http.Handler {
  	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
  		ip := r.Header.Get("X-Real-Ip")          // fallback to X‑Forwarded‑For if needed
  		if ip == "" {
  			ip = mux.CurrentRoute(r).GetVar(r.Context(), "ip")
  			if ip == "" { ip = r.RemoteAddr }
  		}
  
  		now := time.Now()
  		timestamps := ipTimestamps[ip]
  
  		// prune old entries
  		for i, t := range timestamps {
  			if now.Sub(t) > cfg.WindowSecs*time.Second {
  				timestamps = append(timestamps[:i], timestamps[i+1:]...)
  			}
  		}
  
  		if len(timestamps) >= cfg.Limit {
  			http.Error(w, "Too Many Requests", http.StatusTooManyRequests)
  			return
  		}
  
  		timestamps = append(timestamps, now)
  		ipTimestamps[ip] = timestamps
  
  		next.ServeHTTP(w, r) // continue to the next handler (mux or std mux)
  	})
  }
  
  // --------------------------------------------------------------------------
  
  func main() {
  	cfg := RateLimitConfig{
  		Limit:      50,
  		WindowSecs: time.Minute,
  	}
  	mux := mux.NewRouter()
  	mux.Use(initRateLimit(cfg))
  
  	// Example handlers
  	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
  		w.Write([]byte("Hello World – you are allowed!\n"))
  	})
  
  	http.ListenAndServe(":8080", mux)
  }
  ```
  
  **Explanation**
  
  * The middleware extracts the IP (`X‑Real‑Ip` → `X‑Forwarded‑For` fallback).
  * It keeps a slice of timestamps in a **global map**. A small cleanup loop removes entries older than the window.
  * If the count reaches the limit, it returns HTTP 429; otherwise it calls `next.ServeHTTP`.
  
