```ts
// aes256gcm.ts --------------------------------------------------------------
import { randomBytes } from "crypto";

/**
 * Encrypt data with AES‑256‑GCM.
 *
 * @param plainText - Buffer to encrypt
 * @param key        - 32‑byte Buffer (AES‑256)
 * @returns IV + ciphertext + auth tag (concatenated as Uint8Array)
 */
export function aesEncrypt(plainText: Buffer, key: Buffer): Uint8Array {
  const iv = randomBytes(12); // GCM nonce/IV
  const cipher = crypto.createCipheriv("aes-256-gcm", key, iv);
  let encrypted = cipher.update(plainText, "utf8", "binary");
  encrypted += cipher.final("binary");

  // Convert everything to a single Uint8Array for transport/storage
  return new Uint8Array(
    [...iv as unknown as number[], ...encryptedAsBytes(encrypted) as unknown as number[], ...cipher.getAuthTag()]
  );

  function encryptedAsBytes(str: string): number[] {
    const arr = [];
    let i = 0;
    while (i < str.length) {
      // UTF‑8 → binary string
      const chunk = str.slice(i, i + 1024);
      arr.push(...Array.from(chunk).map(c => c.charCodeAt(0)));
      i += chunk.length;
    }
    return arr;
  }
}

/**
 * Decrypt data that was previously encrypted with aesEncrypt.
 *
 * @param payload - Uint8Array containing IV || ciphertext || auth tag
 * @param key     - 32‑byte Buffer (AES‑256)
 * @returns Decrypted plain text as Buffer
 */
export function aesDecrypt(payload: Uint8Array, key: Buffer): string {
  if (payload.length < 12 + 16) throw new Error("Payload too short");
  const iv = payload.slice(0, 12);
  const ciphertextTag = payload.slice(12, -16); // last 16 bytes are auth tag
  const ciphertext = payload.slice(12 + ciphertextTag.length);

  const decipher = crypto.createDecipheriv(
    "aes-256-gcm",
    key,
    iv
  );
  decipher.setAuthTag(ciphertextTag);
  let decrypted = decipher.update(ciphertext, "binary", "utf8");
  decrypted += decipher.final("utf8");

  // Convert back from binary string → UTF‑8 buffer (if needed)
  return Buffer.from(decrypted, "binary").toString("utf8");
}
// --------------------------------------------------------------------------

/* Example usage ---------------------------------------------------------- */
import { aesEncrypt, aesDecrypt } from "./aes256gcm";

const key = randomBytes(32);               // store securely!
const plain = "Hello world! This is a secret message.";

const encrypted = aesEncrypt(Buffer.from(plain), key);
console.log("Encrypted (hex):", Buffer.concat([encrypted.slice(0, 12), encrypted.slice(-16)]).toString("hex"));

const decrypted = aesDecrypt(Buffer.from(encrypted));
console.log("Decrypted:", decrypted);
```

**Key points**

* `crypto.createCipheriv` / `createDecipheriv` are used – they automatically handle PKCS#7 padding and GCM authentication.
* The IV (`nonce`) is **12 bytes** (96‑bit) because that’s the size OpenSSL expects for GCM.
* The returned payload concatenates **IV || ciphertext || auth tag**, which is what most libraries expect when you store a single blob.

