```python
# aes256gcm.py --------------------------------------------------------------
import os
from typing import Tuple, Union

from cryptography.hazmat.primitives.ciphers.aead import AESGCM


def encrypt(plain_text: bytes, key: bytes) -> Tuple[bytes, bytes]:
    """
    Encrypt data with AES‑256‑GCM.

    Returns (nonce, ciphertext_tag)
        * nonce : 12 bytes IV
        * tag   : 16 bytes authentication tag
    The caller should concatenate them before storage.
    """
    if len(key) != 32:
        raise ValueError("Key must be 256‑bit (32 bytes)")

    # AESGCM generates a random nonce internally; we still create one for clarity
    nonce = os.urandom(12)
    aesgcm = AESGCM(key)

    ciphertext_tag = aesgcm.encrypt(nonce, plain_text, associated_data=None)
    return nonce, ciphertext_tag


def decrypt(
    payload: Union[bytes, Tuple[bytes, bytes]],
    key: bytes,
) -> str:
    """
    Decrypt data that was previously encrypted with encrypt().
    Accepts either (nonce, ciphertext_tag) tuple or concatenated blob.
    Returns plain text as string.
    """
    if isinstance(payload, tuple):
        nonce, ct = payload
        combined = nonce + ct
    else:
        # assume concatenated IV||ciphertext||tag
        if len(payload) < 12 + 16:
            raise ValueError("Payload too short")
        nonce = payload[:12]
        ct_tag = payload[12:-16]          # last 16 bytes are auth tag
        combined = nonce + ct_tag

    aesgcm = AESGCM(key)
    plaintext = aesgcm.decrypt(combined, associated_data=None)

    return plaintext.decode("utf-8")


# --------------------------------------------------------------------------

if __name__ == "__main__":
    key = os.urandom(32)                     # store securely!
    msg  = b"Hello world! This is a secret message."

    nonce, ct_tag = encrypt(msg, key)
    print("nonce (hex):", nonce.hex())
    print("ct+tag (hex):", ct_tag.hex())

    recovered = decrypt((nonce, ct_tag), key)
    print("Recovered:", recovered)

    # Using concatenated blob:
    combined_blob = nonce + ct_tag
    print("Decrypted from blob:", decrypt(combined_blob, key))
```

**Key points**

* `cryptography`’s `AESGCM` automatically pads and authenticates.
* The library returns **nonce + ciphertext + tag**, which we expose as a tuple or concatenated bytes depending on the caller’s convenience.

