}

func decrypt(ciphertext []byte, key []byte) ([]byte, error) {
	if len(key) != 32 {
		return nil, fmt.Errorf("AES‑256 requires 32‑byte key")
	}
	block, err := aes.NewCipher(key)
	if err != nil { return nil, err }

	stream, ok := cipher.NewGCM(block)
	if !ok {
		return nil, fmt.Errorf("invalid AES key")
	}

nonceSize := block.BlockSize()
if len(ciphertext) < nonceSize {
	return nil, fmt.Errorf("ciphertext too short for IV")
}
nonce, ciphertextTag := ciphertext[:nonceSize], ciphertext[nonceSize:]

plainBytes, err := stream.Open(nil, nonce, ciphertextTag, nil)
if err != nil { return nil, err }
return plainBytes, nil
}

// --------------------------------------------------------------------------

func main() {
	key := make([]byte, 32)
	if _, err := hex.DecodeString("YOUR_256_BIT_KEY_IN_HEX", key); err != nil {
		panic(err)
	}
	msg := []byte("Hello world! This is a secret message.")

	ciphertext, err := encrypt(msg, key)
	if err != nil { panic(err) }
	fmt.Printf("ciphertext (hex): %s\n", hex.EncodeToString(ciphertext))

	recovered, err := decrypt(ciphertext, key)
	if err != nil { panic(err) }
	fmt.Println("Recovered:", string(recovered))
}
