// webhook.ts --------------------------------------------------------------
import crypto from 'crypto';

/**
 * Verify the signature of a POST body using HMAC‑SHA256.
 *
 * @param payload   The raw request body (string or Buffer)
 * @param secret    Shared secret used for signing
 * @param headerKey Optional name of the header that holds the signature;
 *                  defaults to "x-signature"
 */
export function verifyHmacSha256(
  payload: string | Buffer,
  secret: string,
  headerKey = 'x-signature'
): boolean {
  const expectedSig = crypto.createHmac('sha256', secret)
    .update(payload, 'utf8')
    .digest('hex');

  // The signature sent by the provider (e.g. Stripe) is base64‑encoded.
  const actualSig = Buffer.from(
    crypto
      .createHmac('sha256', secret)
      .update(Buffer.from(expectedSig, 'hex'), 'hex')
      .digest('base64'),
    'utf8'
  );

  // Normalise whitespace – most providers send a single value without spaces.
  return actualSig.trim() === expectedSig;
}

// ---------------------------------------------------------------------
// Example usage (e.g. Express route)
import express from 'express';
const app = express();

app.post('/webhook', async (req, res) => {
  const payload = req.rawBody || ''; // capture raw body first
  try {
    if (!verifyHmacSha256(payload, process.env.WEBHOOK_SECRET)) {
      return res.status(401).send('Invalid signature');
    }

    // 👉 Your business logic here …
    res.json({ received: true });
  } catch (err) {
    console.error(err);
    res.status(500).send('Internal error');
  }
});

app.listen(3000, () => console.log('Server listening on :3000'));
```

**Key points**

* `payload` must be the **raw request body**, not parsed JSON.  
* The signature header (`X‑Signature`, `x-signature`, etc.) is compared after normalising whitespace.

