// apiKeyGenerator.ts ---------------------------------------------------------
/**
 * Generates a new API‑key.
 *
 * • `prefix` – optional static string that will be prepended.
 * • Returns: { key, checksum }
 *   - `key` = prefix + secretPart + checksumSegment
 *   - `checksum` = simple CRC‑8 over the secret part (hex encoded)
 */
export function generateApiKey(prefix?: string): {
  key: string;
  checksum: string; // hex representation of the CRC‑8 value
} {
  const charset =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  const charsetLength = charset.length;

  /** Generate a random alphanumeric secret part (32 chars) */
  function randomSecret(): string {
    let result = "";
    for (let i = 0; i < 32; ++i) {
      result += charset[Math.floor(Math.random() * charsetLength)];
    }
    return result;
  }

  // ---- checksum generation ------------------------------------------------
  /** Simple CRC‑8 using the polynomial x⁸+x²+x+1 (non‑reflected). */
  function crc8(data: Uint8Array): number {
    const poly = 0x07; // x^8 + x^2 + x + 1
    let crc = 0;
    for (const b of data) {
      crc ^= b << 5;          // shift in byte, drop high bit later
      crc <<= 3;              // CRC left‑shift by 3 bits
      crc ^= poly * ((crc >> 7) & 1); // XOR with polynomial if MSB set
    }
    return crc;
  }

  const secret = randomSecret();
  const data = new TextEncoder().encode(secret);
  const checksumValue = crc8(data);

  /** Convert number to a two‑character hex string (lowercase). */
  function numToHex(n: number): string {
    return n.toString(16).padStart(2, "0");
  }

  // Build the final key.
  let keyParts: string[] = [];
  if (prefix) {
    keyParts.push(prefix);
  }
  keyParts.push(secret);               // secret part
  const hexChecksum = numToHex(checksumValue);
  // Append checksum as a two‑character hex segment – you can change length/encoding.
  keyParts.push(hexChecksum);

  const apiKey = keyParts.join("");
  return { key: apiKey, checksum: hexChecksum };
}

// --------------------------------------------------------------------------

/**
 * Validates an API‑key that follows the format:
 *   [prefix]secretchecksum
 *
 * Returns true if both prefix (if supplied) and checksum match.
 */
export function validateApiKey(apiKey: string, expectedPrefix?: string): boolean {
  // Split by assuming checksum is always two hex characters at the end.
  const lastTwo = apiKey.slice(-2);
  const rest = apiKey.slice(0, -2);

  if (!/^[A-Za-z0-9]+$/.test(lastTwo)) {
    return false; // checksum must be hex
