    const sepIdx = rest.indexOf(expectedPrefix);
    if (sepIdx === -1 || sepIdx + expectedPrefix.length !== lastTwo.length) {
      return false; // mismatched or missing prefix
    }
    secretPart = rest.slice(expectedPrefix.length, -2); // everything before checksum
    expectedChecksum = lastTwo;
