#!/usr/bin/env python3
"""
apiKeyGenerator.py – Generates a random API key with optional prefix and simple CRC‑8 checksum.
"""

import os
import binascii
from typing import Tuple, Optional


# ---------------------------------------------------------------------------


def generate_api_key(prefix: Optional[str] = None) -> Tuple[str, str]:
    """
    Returns:
        (key, checksum)
        - `key`  = prefix + secretPart + checksumSegment   (checksum is hex(2 chars))
        - `checksum` = hex representation of CRC‑8 over secretPart
    """

    charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
    CHARSET_LEN = len(charset)

    def random_secret() -> str:
        """Generate a 32‑character alphanumeric secret."""
        return "".join(os.urandom(1).hex()[2:3] for _ in range(32))  # simpler alternative

    # Simpler pure‑Python version (no os.urandom):
    import string, random
    secret = ''.join(random.choice(charset) for _ in range(32))

    data = secret.encode('utf-8')
    crc_val = crc8(data)

    def num_to_hex(n: int) -> str:
        return f"{n:02x}"

    checksum_hex = num_to_hex(crc_val)
    key_parts = []
    if prefix:
        key_parts.append(prefix)
    # Append secret + checksum (checksum is two hex chars)
    key_parts.extend([secret, checksum_hex])
    api_key = "".join(key_parts)

    return api_key, checksum_hex


def crc8(data: bytes) -> int:
    """
    CRC‑8 with polynomial 0x07 (non‑reflected). Returns an integer.
    """
    poly = 0x07
    crc = 0
    for b in data:
        crc ^= b << 5          # shift byte into place, drop high bit later
        crc <<= 3              # CRC left‑shift by 3 bits
        if (crc >> 7) & 1:     # MSB set?
            crc ^= poly       # XOR with polynomial
    return crc


def validate_api_key(api_key: str, expected_prefix: Optional[str] = None) -> bool:
    """
    Checks both format and checksum.
    Expected format: [prefix]secretchecksum   (checksum always 2 hex chars)
    Returns True if valid; False otherwise.
    """

    # Separate out the final two‑character hex checksum
    last_two = api_key[-2:]
    rest = api_key[:-2]

    if not all(c in "0123456789abcdefABCDEF" for c in last_two):
        return False  # checksum must be hex

    secret_part = ""
    expected_checksum = ""

    if expected_prefix:
        sep_idx = rest.find(expected_prefix)
        if sep_idx == -1 or len(expected_prefix) + sep_idx != len(rest[:sep_idx]):
            return False
        secret_part = rest[sep_idx : len(rest) - 2]
        expected_checksum = last_two
    else:
        secret_part = rest[:-2]   # everything except the final two chars
        expected_checksum = last_two

    # Re‑compute CRC on secret part and compare
    data = secret_part.encode('utf-8')
    computed_crc = crc8(data)
    if int(expected_checksum, 16) != computed_crc:
        return False

    return True


# ---------------------------------------------------------------------------


if __name__ == "__main__":
    # Demo: generate a key with an optional prefix and validate it.
    prefix = "myPrefix"
    key, chksum = generate_api_key(prefix)
    print("Generated API‑key :", key)
    print("Checksum        :", chksum)

