// arithmeticEvaluator.ts ----------------------------------------------------
/**
 * Evaluates an arithmetic expression containing +, -, *, /.
 *
 * @param expr – The string to evaluate (e.g. "3+5*2-4/2").
 * @returns An object with `result` and optional `error`.
 */
export function evaluateArithmetic(expr: string): { result?: number; error?: string } {
  // ---------- Tokeniser ----------
  const tokens = tokenize(expr);
  if (!tokens) return { error: "Invalid expression" };

  // ---------- Parser ----------
  const parser = new ExpressionParser(tokens);
  const root = parser.parseExpression();
  if (parser.errors.length > 0) return { error: parser.errors.join("\n") };
  if (parser.currentToken !== null && !parser.isAtEnd()) {
    return { error: "Unexpected token after complete parse" };
  }

  // ---------- Evaluate ----------
  const result = evaluateTree(root);
  if (isNaN(result)) return { error: "Division by zero or invalid operation" };

  return { result };
}

// ---------- Tokeniser ----------
function tokenize(expr: string): Array<string> | null {
  const tokens: Array<string> = [];
  let i = 0;
  while (i < expr.length) {
    if (expr[i].match(/\s/)) {
      ++i; // skip whitespace
      continue;
    }
    if (expr[i] === '+' || expr[i] === '-' || expr[i] === '*' || expr[i] === '/') {
      tokens.push(expr[i]);
      ++i;
      continue;
    }
    if (!expr[i].match(/\d/)) return null; // unexpected character
    let num = "";
    while (i < expr.length && expr[i].match(/\d/)) {
      num += expr[i];
      ++i;
    }
    tokens.push(num);
  }
  return tokens;
}

// ---------- Parser ----------
class ExpressionParser {
  private pos: number = 0;
  private currentToken: string | null = null;

  constructor(private readonly tokens: Array<string>) {
    this.currentToken = tokens[0] ?? null;
  }

  get errors(): string[] { return this._errors; }
  set errors(val: string[]) { this._errors = val; }

  private _errors: string[] = [];

  parseExpression(): ASTNode | null {
    let node = this.parseTerm();
    if (node === null) return null;

    while (this.currentToken !== null && ["+", "-"].includes(this.currentToken)) {
      const op = this.currentToken!;
      this.advance(); // consume '+'
      const right = this.parseTerm();
      if (right === null) { this.errors.push(`Expected term after ${op}`); return null; }
      node = new BinaryOp(op, node, right);
    }

    return node;
  }

  private parseTerm(): ASTNode | null {
    let node = this.parseFactor();
    if (node === null) return null;

    while (this.currentToken !== null && ["*", "/"].includes(this.currentToken)) {
      const op = this.currentToken!;
      this.advance(); // consume '*'
      const right = this.parseFactor();
      if (right === null) { this.errors.push(`Expected factor after ${op}`); return null; }
      node = new BinaryOp(op, node, right);
    }

    return node;
  }

  private parseFactor(): ASTNode | null {
    const tok = this.currentToken!;
    if (!isNaN(Number(tok))) {
      // consume number
      this.advance();
      return new NumberLiteral(parseFloat(tok));
    }
    this.errors.push(`Expected number or '(' but found '${tok}'`);
    return null;
  }

  private advance() {
    if (this.pos < this.tokens.length) {
      this.currentToken = this.tokens[this.pos++];
    } else {
      this.currentToken = null;
    }
  }

  private isAtEnd(): boolean { return this.currentToken === null; }
}

// ---------- AST ----------
abstract class ASTNode {}
class NumberLiteral extends ASTNode {
  constructor(private readonly value: number) { super(); }
}
class BinaryOp extends ASTNode {
  constructor(
    public operator: string,
    public left: ASTNode,
    public right: ASTNode
  ) {
    super();
  }
}

