# arithmetic_evaluator.py ----------------------------------------------------
import re
from typing import Tuple, Optional


class AST:
    """Abstract base for all AST nodes."""
    pass


class Number(AST):
    def __init__(self, value: float) -> None:
        self.value = value

    def evaluate(self) -> float:
        return self.value


class BinaryOp(AST):
    def __init__(self, op: str, left: AST, right: AST) -> None:
        self.op = op          # one of '+', '-', '*', '/'
        self.left = left
        self.right = right

    def evaluate(self) -> float:
        lval = self.left.evaluate()
        rval = self.right.evaluate()

        if self.op == '+':
            return lval + rval
        elif self.op == '-':
            return lval - rval
        elif self.op == '*':
            return lval * rval
        elif self.op == '/':
            if rval == 0:
                raise ZeroDivisionError("division by zero")
            return lval / rval


def tokenize(expr: str) -> Tuple[list, Optional[str]]:
    """
    Returns a list of tokens (numbers and operators) or an error string.
    Whitespace is ignored; any non‑numeric/non-operator character yields an error.
    """
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue

        if expr[i] in "+-*/":
            tokens.append(expr[i])
            i += 1
            continue

        if not expr[i].isdigit():
            return [], f"Invalid character '{expr[i]}' at position {i}"

        # consume a full number (may have multiple digits)
        num = ""
        while i < len(expr) and expr[i].isdigit():
            num += expr[i]
            i += 1
        tokens.append(num)

    return tokens, None


def evaluate_arithmetic(expr: str):
    """
    Evaluates an arithmetic expression containing +, -, *, /.
    Returns a tuple (result, error_message). If no error, result is a float;
    otherwise error_message holds the diagnostic string.
    """
    tokens, err = tokenize(expr)
    if err:
        return None, err

    parser = Parser(tokens)
    try:
        root = parser.parse_expression()
        # Ensure we consumed all tokens
        if not parser.is_at_end():
            raise ValueError("Unexpected token after complete parse")
        result_node = root.evaluate()   # raises ZeroDivisionError on failure
        return float(result_node), None
    except Exception as e:
        return None, str(e)


class Parser:
    def __init__(self, tokens: list) -> None:
        self.tokens = tokens
        self.pos = 0

    @property
    def current(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        self.pos += 1

    def is_at_end(self) -> bool:
        return self.current() == ""

    # ---------- Grammar ----------
    # expression ::= term {( "+" | "-" ) term}*
    def parse_expression(self) -> AST:
        node = self.parse_term()
        if not node: 
            raise ValueError("Expected term")
        while True:
            tok = self.current()
            if tok in ("+", "-"):
                self.advance()  # consume operator
                right = self.parse_term()
                if not right:
                    raise ValueError(f"Expected expression after {tok}")
                node = BinaryOp(tok, node, right)
            else:
                break
        return node

    # ---------- term ::= factor {( "*" | "/" ) factor}*
    def parse_term(self) -> AST:
        node = self.parse_factor()
        if not node: 
            raise ValueError("Expected factor")
        while True:
            tok = self.current()
            if tok in ("*", "/"):
                self.advance()  # consume operator
                right = self.parse_factor()
                if not right:
                    raise ValueError(f"Expected expression after {tok}")
                node = BinaryOp(tok, node, right)
            else:
                break
        return node

    # ---------- factor ::= number | '(' expression ')'
    def parse_factor(self) -> AST:
        tok = self.current()
        if tok is None or not (tok.isdigit() or (tok.startswith('-') and len(tok)==1)):
            raise ValueError(f"Expected number or '(' but found '{tok}'")
        if tok == "(":
            self.advance()  # consume '('
            node = self.parse_expression()
            if not node: 
                raise ValueError("Empty expression inside parentheses")
            if self.current() != ")":
                raise ValueError("Missing closing ')'")
            self.advance()   # consume ')'
            return node
        else:
            try:
                value = float(tok)
            except ValueError:
                raise ValueError(f"Invalid number '{tok}'")
            self.advance()
            return Number(value)


