	lval, err := b.Left.eval()
	if err != nil { return 0, err }
	rval, err := b.Right.eval()
	if err != nil { return 0, err }

	switch b.Operator {
	case "+":
		return lval + rval, nil
	case "-":
		return lval - rval, nil
	case "*":
		return lval * rval, nil
	case "/":
		if rval == 0 {
			return 0, errors.New("division by zero")
		}
		return lval / rval, nil
	default:
		panic(fmt.Sprintf("unknown operator %q", b.Operator))
	}
}

