// RenderTemplate returns a string with all {{key}} placeholders replaced by their values.
func RenderTemplate(source string, values map[string]string) string {
	// Build regex pattern: {{key1|key2|...}}
	var keys []string
	for k := range values {
		keys = append(keys, k)
	}
	reStr := "(" + regexp.QuoteMeta("|") + "|"+regexp.JoinString(keys)+")"
	r := regexp.MustCompile(`{{` + reStr + `}}`)
	return r.ReplaceAllLiteralString(source, func(match []byte) []byte {
