use std::collections::HashMap;

fn render_template(source: &str, values: &HashMap<String, String>) -> String {
    // Build a regex that matches {{key}} where key is one of the map keys
    let keys: Vec<_> = values.keys().cloned().collect();
    let pattern = keys.join("|");
    let re = regex::RegexBuilder::new(&format!("{{({})}}", pattern))
        .build()
        .expect("invalid regex");

    // Replacement closure that looks up the key
    fn replacer(cap: &regex::Captures) -> String {
        let key = cap[1].to_string(); // captures {{key}}
        values.get(&key).cloned().unwrap_or("")
    }

    re.replace_all(source, |cap| replacer(cap)).into_owned()
}

