/**
 * Convert a non‑negative integer to its English words.
 *
 * Supports numbers up to 999,999,999 (billions).
 *
 * @param n The number to convert. Must be >=0 and <1_000_000_000.
 * @returns A string containing the English representation of `n`.
 */
function numToEnglish(n: number): string {
    if (!Number.isInteger(n) || n < 0 || n >= 1_000_000_000) {
        throw new Error('Input must be an integer between 0 and 999,999,999');
    }

    // Helper arrays
    const units = ['', 'one', 'two', 'three', 'four', 'five',
                   'six', 'seven', 'eight', 'nine'];
    const teens   = ['ten','eleven','twelve','thirteen','fourteen',
                     'fifteen','sixteen','seventeen','eighteen','nineteen'];
    const tens    = ['', '', 'twenty', 'thirty', 'forty',
                     'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];

    // Helper to convert numbers <1000
    function threeDigitToWords(num: number): string {
        if (num === 0) return '';
        let words = '';

        const hundreds = Math.floor(num / 100);
        if (hundreds > 0) {
            words += units[hundreds] + ' hundred';
            num %= 100;
            if (num !== 0) words += ' ';
        }

        // Handle teens and normal tens+units
        if (num < 20) {
            if (num >= 10 && num <= 19) {
                words += teens[num - 10];
            } else {
                const tenIdx = Math.floor(num / 10);
                const oneIdx = num % 10;
                words += (tenIdx > 0 ? tens[tenIdx] : '') + (oneIdx > 0 ? units[num % 10] : '');
            }
        } else {
            const tenIdx = Math.floor(num / 10);
            const oneIdx = num % 10;
            if (tenIdx > 0) words += tens[tenIdx];
            if (oneIdx > 0) words += ' ' + units[oneIdx];
        }

        return words.trim();
    }

    // Break the number into billions, millions, thousands and remainder
    const billion = Math.floor(n / 1_000_000_000);
    n %= 1_000_000_000;
    let result = '';
    if (billion > 0) {
        result += threeDigitToWords(billion) + ' billion';
        if (n !== 0) result += ' ';
    }

    const million = Math.floor(n / 1_000_000);
    n %= 1_000_000;
    if (million > 0) {
        result += threeDigitToWords(million) + ' million';
        if (n !== 0) result += ' ';
    }

    const thousand = Math.floor(n / 1_000);
    n %= 1_000;
    if (thousand > 0) {
        result += threeDigitToWords(thousand) + ' thousand';
        if (n !== 0) result += ' ';
    }

    // Remaining hundreds‑tens‑units
    if (n > 0) {
        result += threeDigitToWords(n);
    }

    return result;
}

// Example usage:
console.log(numToEnglish(123456789));   // → "one hundred twenty three million four hundred fifty six thousand seven hundred eighty nine"
