def num_to_english(n: int) -> str:
    """
    Convert a non-negative integer (0 ≤ n < 1,000,000,000)
    into its English word representation.
    
    Raises ValueError if `n` is out of range or not an integer.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0 or n >= 1_000_000_000:
        raise ValueError("Number out of supported range (0‑999,999,999)")

    # Helper arrays
    units = ['', 'one', 'two', 'three', 'four', 'five',
             'six', 'seven', 'eight', 'nine']
    teens  = ['ten','eleven','twelve','thirteen','fourteen',
              'fifteen','sixteen','seventeen','eighteen','nineteen']
    tens   = ['', '', 'twenty', 'thirty', 'forty',
              'fifty', 'sixty', 'seventy', 'eighty', 'ninety']

    def three_digit(num: int) -> str:
        """Convert a number <1000 to English words."""
        if num == 0:
            return ''
        parts = []
        # Hundreds
        h = num // 100
        if h > 0:
            parts.append(units[h])
            parts.append('hundred')
            num %= 100

        # Teens / normal tens+units
        if num < 20:
            if 10 <= num <= 19:
                parts.append(teens[num - 10])
            else:
                parts.append(units[num])
        else:
            t = num // 10          # tens digit (0‑9)
            u = num % 10           # ones digit
            if t > 0:
                parts.append(tens[t])
            if u > 0:
                parts.append(units[u])
        return ' '.join(parts)

    # Split into billions, millions, thousands and remainder
    billion = n // 1_000_000_000
    n %= 1_000_000_000

    result = ''
    if billion:
        result += three_digit(billion) + ' billion'
        if n: result += ' '

    million = n // 1_000_000
    n %= 1_000_000
    if million:
        result += three_digit(million) + ' million'
        if n: result += ' '

    thousand = n // 1_000
    n %= 1_000
    if thousand:
        result += three_digit(thousand) + ' thousand'
        if n: result += ' '

    # Remaining units
    if n:
        result += three_digit(n)

    return result


