/**
 * Returns a fuzzy similarity score between 0 and 1.
 *
 * @param a First string
 * @param b Second string
 * @returns Similarity (higher = more similar)
 */
export function fuzzySimilarity(a: string, b: string): number {
  // Levenshtein distance implementation -------------------------------------------------
  const levenshtein = (s: string, t: string): number => {
    if (s === t) return 0;               // identical strings
    const m = s.length;
    const n = t.length;

    // Create a matrix of size (m+1) × (n+1)
    const d: number[][] = Array.from({ length: m + 1 }, () =>
      Array(n + 1).fill(0)
    );

    for (let i = 0; i <= m; i++) d[i][0] = i;
    for (let j = 0; j <= n; j++) d[0][j] = j;

    for (let i = 1; i <= m; i++) {
      const si = s.charAt(i - 1);
      for (let j = 1; j <= n; j++) {
        const cost = si === t.charAt(j - 1) ? 0 : 1;
        d[i][j] =
          Math.min(
            // deletion
            d[i - 1][j] + 1,
            // insertion
            d[i][j - 1] + 1,
            // substitution
            d[i - 1][j - 1] + cost
          );
      }
    }

    return d[m][n];
  };

  const distance = levenshtein(a, b);
  const maxLen = Math.max(a.length, b.length);

  if (maxLen === 0) {
    // both strings empty → perfect match
    return 1;
  }

  // Normalized similarity: higher score when edit distance is small.
  return 1 - (distance / maxLen);
}

