		}

		for i := 1; i <= m; i++ {
			si := s[i-1]
			for j := 1; j <= n; j++ {
				cost := 0
				if si != t[j-1] {
					cost = 1
				}
				d[i][j] = min(
					d[i-1][j]+1,   // deletion
					d[i][j-1]+1,   // insertion
					d[i-1][j-1]+cost, // substitution
				)
			}
		}

		return d[m][n]
	}

	distance := lev(a, b)
	maxLen := max(len(a), len(b))

	if maxLen == 0 {
