# ---------------------------------------------------
# 1️⃣ Enum class for states
from enum import Enum

class State(Enum):
    IDLE   = "Idle"
    RUNNING= "Running"
    ERROR  = "Error"

# ---------------------------------------------------
# 2️⃣ Transition validator – raises an exception on error
def transition(from_state: State, to_state: State) -> State:
    """
    Returns the next state if legal; otherwise raises InvalidTransition.
    """
    # Legal transitions only:
    #   IDLE   → RUNNING
    #   RUNNING→ ERROR (failure)
    if from_state == State.IDLE and to_state == State.RUNNING:
        return State.RUNNING
    elif from_state == State.RUNNING and to_state == State.ERROR:
        return State.ERROR
    else:
        raise InvalidTransition(
            f"Invalid transition {from_state.name} → {to_state.name}"
        )

# ---------------------------------------------------
# 3️⃣ Simple exception class for illegal moves
class InvalidTransition(Exception):
    pass

# ---------------------------------------------------
# 4️⃣ Demo / usage
def run_demo(initial: State) -> None:
    state = initial
    print(f"Starting in {state.name}")

    # Example command sequence (feel free to add more)
    cmds = [
        {"from": "Idle",   "to": "Running"},
        {"from": "Running","to": "Error"},  # <-- legal
        # Uncomment the next line to see an error:
        # {"from": "Running","to": "Running"},  # <-- illegal!
    ]

    for c in cmds:
        try:
            new_state = transition(c["from"], c["to"])
            state = new_state
            print(f"→ {state.name}")
        except InvalidTransition as e:
            print(f"❌ Transition error: {e}")

# Run the demo (uncomment to test)
if __name__ == "__main__":
    run_demo(State.IDLE)
```

