package main

import (
	"fmt"
)

// ---------------------------------------------------
// 1️⃣ Type alias for states – compile‑time enforced set.
type State string

const (
	IDLE   State = "Idle"
	RUNNING State = "Running"
	ERROR  State = "Error"
)

// ---------------------------------------------------
// 2️⃣ Transition validator – returns error on illegal move
func transition(from, to State) (State, error) {
	// Legal transitions only:
	//   IDLE   → RUNNING
	//   RUNNING→ ERROR (failure)
	switch [][2]State{
	case {IDLE, RUNNING},
	     {RUNNING, ERROR}:
	default:
		return "", fmt.Errorf("invalid transition %s → %s", from, to)
	}
	return to, nil
}

// ---------------------------------------------------
// 3️⃣ Demo / usage
func runDemo(initial State) {
	fmt.Printf("Starting in %s\n", initial)

	cmds := []struct{ From, To State }{
		{"Idle",   "Running"},
		{"Running","Error"}, // <-- legal
		// Uncomment the next line to trigger an error:
		// {"Running","Running"},  // <-- illegal!
	}

	for _, c := range cmds {
		next, err := transition(c.From, c.To)
		if err != nil {
			fmt.Printf("❌ Transition error: %s\n", err)
			continue
		}
		println("→", next)
	}
}

// ---------------------------------------------------
func main() {
	runDemo(IDLE)
}
```

**Key points**

* `State` is a **string alias**, guaranteeing that only the three defined constants can be used.  
* The function returns an explicit `error`; callers must handle it (`if err != nil { … }`). This mirrors typical Go error‑first APIs and makes illegal transitions impossible to ignore at compile time.

