## 3️⃣ Go  

```go
// ---------------------------------------------------
// observer.go – simple Pub/Sub using map[string][]func(payload interface{})
// ---------------------------------------------------
package main

import (
	"fmt"
)

type Observer struct {
	handlers map[string][]func(interface{}) // event name → slice of callbacks
}

// NewObserver returns a new, empty PubSub system.
func NewObserver() *Observer {
	return &Observer{
		handlers: make(map[string][]func(interface{})),
	}
}

// On subscribes a callback for the given event name.
func (o *Observer) On(event string, cb func(interface{})) {
	o.handlers[event] = append(o.handlers[event], cb)
}

// Off unsubscribes – if `cb` is omitted all callbacks are removed.
func (o *Observer) Off(event string, cb func(interface{})) {
	if o.handlers == nil || len(o.handlers) == 0 {
		return
	}
	if _, ok := o.handlers[event]; !ok {
		return // event does not exist
	}
	if cb == nil {
		delete(o.handlers, event)
	} else {
		var newSlice []func(interface{})
		for _, f := range o.handlers[event] {
			if f != cb {
				newSlice = append(newSlice, f)
			}
		}
		o.handlers[event] = newSlice
	}
}

// Emit notifies every subscriber for the given event.
func (o *Observer) Emit(event string, payload interface{}) {
	for _, cb := range o.handlers[event] {
		cb(payload)
	}
}

