  ```ts
  // ---------------------------------------------------
  // observer.ts – simple EventEmitter implementation
  // ---------------------------------------------------
  export interface EventListener<T> {
      (payload?: T): void;
  }
  
  /**
   * A minimal Pub/Sub system.
   *
   * - `on(name, listener)`   → subscribe a callback for an event name.
   * - `off(name, listener?)`→ unsubscribe.  If no listener is given,
   *                           all listeners for that name are removed.
   * - `emit(name, payload?)`→ notify every subscriber of the named event.
   */
  export class EventEmitter {
      private handlers: Record<string, EventListener<any>[]> = {};
  
      /** Subscribe a callback to an event name (may be called multiple times). */
      on(name: string, listener: EventListener<any>): void {
          if (!this.handlers[name]) this.handlers[name] = [];
          this.handlers[name].push(listener);
      }
  
      /** Unsubscribe – removes only the supplied listener for that name. */
      off(name: string, listener?: EventListener<any>): void {
          const list = this.handlers[name];
          if (!list) return;
          if (listener === undefined) {
              // remove all listeners
              delete this.handlers[name];
          } else {
              this.handlers[name] = list.filter(l => l !== listener);
          }
      }
  
      /** Notify all subscribers of a given event name. */
      emit(name: string, payload?: any): void {
          const handlers = this.handlers[name]?.slice() ?? []; // make a copy
          for (const cb of handlers) {
              cb(payload);
          }
      }
  }
  ```
  
