  ## 2️⃣ Python  
  
  ```python
  # ---------------------------------------------------
  # observer.py – simple Pub/Sub using a dict of lists
  # ---------------------------------------------------
  from typing import Callable, Any
  
  class Observer:
      """
      A minimal publish/subscribe system.
      
      - `on(event_name: str, callback: Callable)` → subscribe.
      - `off(event_name: str, callback=None)` → unsubscribe. If no callback is given,
        all callbacks for that event are removed.
      - `emit(event_name: str, payload:Any)` → notify every subscriber.
      """
      
      def __init__(self):
          self._handlers = {}   # dict[str, list[Callable]]
  
      def on(self, event_name: str, callback: Callable[..., Any]) -> None:
          """Subscribe a callable to an event."""
          if event_name not in self._handlers:
              self._handlers[event_name] = []
          self._handlers[event_name].append(callback)
  
      def off(self, event_name: str, callback: Callable | None = None) -> None:
          """
          Unsubscribe. If `callback` is omitted, all callbacks for that event are removed.
          """
          if event_name not in self._handlers:
              return
          if callback is None:
              del self._handlers[event_name]
          else:
              # filter out only the supplied callback
              self._handlers[event_name] = [
                  c for c in self._handlers[event_name] if c != callback
              ]
  
      def emit(self, event_name: str, payload:Any) -> None:
          """Notify all subscribers of an event."""
          callbacks = self._handlers.get(event_name, [])
          # make a shallow copy so we can safely modify the dict while iterating
          for cb in list(callbacks):
              cb(payload)
  ```
  
