## 1️⃣ TypeScript Implementation

```ts
// ------------------------------------------------------------
// Simple DI Container for TypeScript
// ------------------------------------------------------------

type Provider<T> = () => T | Promise<T>;

/**
 * A very basic Dependency Injection container.
 *
 * - `register(name, provider)`: stores a factory function that returns an instance.
 * - `get<T>(name): T` : resolves the dependency (calling its factory if needed)
 *   and caches the result for subsequent calls.
 */
export class DIContainer {
  /** Internal storage: name → {provider, singleton} */
  private registry = new Map<string, { provider: Provider<any>; singleton?: boolean }>();

  /**
   * Register a new dependency.
   *
   * @param name      Unique identifier (string)
   * @param provider  A function that returns the instance or a Promise for it.
   *                  If `singleton === true`, only one instance is created and cached.
   */
  register<T>(name: string, provider: Provider<T>, singleton = false): void {
    if (!name || typeof name !== 'string') {
      throw new Error('Name must be a non‑empty string');
    }
    this.registry.set(name, { provider, singleton });
  }

  /**
   * Resolve the dependency.
   *
   * @param name The identifier registered with `register`.
   * @returns The resolved instance (or Promise for it).
   */
  async get<T>(name: string): Promise<T> {
    const entry = this.registry.get(name);
    if (!entry) {
      throw new Error(`No provider registered for "${name}"`);
    }

    // If we already have an instance, return it directly.
    if (entry.singleton && !this._instances.has(name)) {
      try {
        const value = await entry.provider();
        this._instances.set(name, value);
        return value;
      } catch (err) {
        throw new Error(`Failed to create "${name}": ${(err as Error).message}`);
      }
    }

    // No cached instance – call the factory.
    try {
      const value = await entry.provider();
      if (entry.singleton) this._instances.set(name, value);
      return value;
    } catch (err) {
      throw new Error(`Error resolving "${name}": ${(err as Error).message}`);
    }
  }

  /** Optional: clear all cached instances (useful for testing) */
  reset(): void {
    this._instances.clear();
  }

  private _instances = new Map<string, any>(); // cache of resolved singletons
}

// ------------------------------------------------------------
// Example usage in TypeScript
// ------------------------------------------------------------

/**
 * A simple logger that writes to console.
 */
function createLogger(): { log(msg: string): void } {
  return {
    log(msg) {
      console.log(`[LOG] ${msg}`);
    },
  };
}

/**
 * Database client – we'll pretend it needs a config object.
 */
async function createDatabaseClient(config: { url: string }): Promise<{ query(sql: string): any }> {
  // Simulate async connection
  await new Promise((r) => setTimeout(r, 100));
  return {
    query(sql) {
      console.log(`[DB] Executing ${sql}`);
      // Dummy result for demo
      return { rows: [{ id: 1, name: 'Alice' }] };
    },
  };
}

/**
 * A service that depends on both Logger and DatabaseClient.
 */
function createUserService(logger: ReturnType<typeof createLogger>, db: ReturnType<typeof createDatabaseClient>): {
  greetUser(name: string): void;
} {
  return {
    greetUser(name) {
      logger.log(`Hello, ${name}!`);
      // Example DB call
      const user = db.query('SELECT * FROM users WHERE name=?')[0];
      console.log(`${user?.name || 'unknown'} greeted.`);
    },
