## 2️⃣ Python Implementation

```python
# ------------------------------------------------------------
# Simple DI Container for Python (≈30 lines)
# ------------------------------------------------------------

from typing import Callable, Any, Dict, TypeVar, Generic
import asyncio

T = TypeVar('T')

class DIContainer:
    """
    Very basic Dependency Injection container.
    * `register(name: str, provider: Callable[[], T | Awaitable[T]], singleton=True)`
      registers a factory function that returns an instance (or awaitable).
    * `get(name: str) -> T` resolves the dependency; singletons are cached.
    """
    def __init__(self):
        self._registry = {}          # name → {"provider": Callable, "singleton": bool}
        self._instances: Dict[str, Any] = {}

    def register(self,
                 name: str,
                 provider: Callable[[], T | asyncio.Future[T]],
                 singleton: bool = True) -> None:
        if not isinstance(name, str) or not name:
            raise ValueError('Name must be a non‑empty string')
        self._registry[name] = {"provider": provider, "singleton": singleton}

    async def get(self, name: str) -> T:
        entry = self._registry.get(name)
        if entry is None:
            raise KeyError(f'No provider registered for "{name}"')

        # Return cached singleton immediately
        if entry["singleton"] and name in self._instances:
            return self._instances[name]

        # Otherwise call the factory (async or sync) and cache result
        try:
            value = await entry["provider"]()
            if entry["singleton"]:
                self._instances[name] = value
            return value
        except Exception as exc:
            raise RuntimeError(f'Error resolving "{name}": {exc}') from exc

    def reset(self) -> None:          # handy for tests
        self._registry.clear()
        self._instances.clear()


# ------------------------------------------------------------
# Example usage in Python (mirroring the TypeScript demo)
# ------------------------------------------------------------

def create_logger() -> Callable[[str], None]:
    """A simple logger that writes to stdout."""
    return lambda msg: print(f"[LOG] {msg}")

async def create_database_client(config: dict) -> Callable[['DBQuery'], Any]:
    """
    Async DB client – pretends to connect after a short sleep.
    Returns an object with a `query` method.
    """
    await asyncio.sleep(0.1)
    return lambda sql: {
        "rows": [{"id": 1, "name": "Alice"}],
        # Dummy implementation
    }

def create_user_service(logger: Callable[[str], None],
                        db_client: Callable[['DBQuery'], Any]) -> Callable[[], None]:
    """
    Service that uses logger and DB client.
    For demo purposes we only expose a greetUser method.
    """
    return lambda name: (
        logger(f"Hello, {name}!"),
        # Example DB call (the actual db_client is not used here)
        print("Executing dummy query...")
    )

# ---- Wiring -------------------------------------------------
di = DIContainer()

# Register factories with identifiers
di.register('logger', create_logger)
di.register('dbConfig', lambda: {"url": "postgres://localhost/mydb"})

# The DB client depends on the config; we register it as a callable that returns an async factory.
async def db_factory() -> Callable[['DBQuery'], Any]:
    return await create_database_client(await di.get('dbConfig'))

di.register('database', db_factory)

# UserService needs both logger and database client. We build it after they are ready:
def user_service_factory(ctx: DIContainer) -> Callable[[], None]:
    async def service(name: str):
        log = await ctx.get('logger')
