// logger.ts --------------------------------------------------------------
import { v4 as uuidv4 } from 'uuid';
import fs from 'fs';

/**
 * Simple JSON‑structured logger.
 *
 * Usage:
 *   const log = new Logger('myApp');
 *   log.debug({ userId: 123 }, "User logged in");
 */
export class Logger {
  private readonly name: string;
  private static readonly LEVELS = ['debug', 'info', 'warn', 'error'] as const;

  constructor(name: string) {
    this.name = name;
  }

  /** Helper to create a JSON line with required fields. */
  private _write(level: typeof Logger.LEVELS[number], context?: Record<string, unknown>): void {
    const entry: Record<string, unknown> = {
      timestamp: new Date().toISOString(),
      level,
      message: '',
      ...context
    };
    // Append to a file (or replace with your own logger)
    const path = './logs/app.log';
    const existing = fs.existsSync(path) ? JSON.parse(fs.readFileSync(path, 'utf8')) : [];
    existing.push(entry);
    fs.writeFileSync(path, JSON.stringify(existing, null, 2));
  }

  debug(context: Record<string, unknown> = {}, message: string): void {
    this._write('debug', { ...context, message });
  }
  info(context: Record<string, unknown> = {}, message: string): void {
    this._write('info', { ...context, message });
  }
  warn(context: Record<string, unknown> = {}, message: string): void {
    this._write('warn', { ...context, message });
  }
  error(context: Record<string, unknown> = {}, message: string): void {
    this._write('error', { ...context, message });
  }

  // Optional convenience shortcuts
  get debug()   { return (ctx: any, msg: string) => this.debug(ctx, msg); }
  get info()    { return (ctx: any, msg: string) => this.info(ctx, msg); }
  get warn()    { return (ctx: any, msg: string) => this.warn(ctx, msg); }
  get error()   { return (ctx: any, msg: string) => this.error(ctx, msg); }

} // Logger

// ----------------------------------------------------------------------
// Example usage ---------------------------------------------------------
import { Logger } from './logger';

const logger = new Logger('myApp');

logger.info({ requestId: uuidv4(), component: 'auth' }, "User authenticated");
logger.debug({ userId: 42 }, "Login attempt succeeded");
logger.warn({ requestId: uuidv4() }, "Cache miss, falling back to DB");
logger.error(
  { requestId: uuidv4(), errorCode: 'NOT_FOUND', details: new Error("Resource not found") },
  "Failed to retrieve user profile"
);
