import json
from datetime import datetime, timezone
import uuid

class Logger:
    LEVELS = ["debug", "info", "warn", "error"]

    def __init__(self, name: str):
        self.name = name

    def _write(self, level: str, context: dict | None = None, message: str) -> None:
        entry = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "level": level,
            "message": message,
        }
        if context:
            entry.update(context)
        # Append to a file (replace with your own logger backend as needed)
        try:
            with open("logs/app.log", "r+", encoding="utf-8") as f:
                lines = json.load(f) or []
                lines.append(entry)
                f.seek(0)
                f.truncate()
                json.dump(lines, f, indent=2)
        except FileNotFoundError:
            # First run – create empty list
            with open("logs/app.log", "w+", encoding="utf-8") as f:
                json.dump([], f)

    def debug(self, context: dict | None = None, message: str) -> None:
        self._write("debug", context or {}, message)

    def info(self, context: dict | None = None, message: str) -> None:
        self._write("info", context or {}, message)

    def warn(self, context: dict | None = None, message: str) -> None:
        self._write("warn", context or {}, message)

    def error(self, context: dict | None = None, message: str) -> None:
        self._write("error", context or {}, message)


