  // logger.go ------------------------------------------------------------
  package main
  
  import (
  	"encoding/json"
  	"fmt"
  	"io/ioutil"
  	"log"
  	"os"
  	"path/filepath"
  	"strings"
  	"time"
  
  	uuid "github.com/google/uuid"
  )
  
  type Logger struct {
  	name string
  }
  
  const logDir = "./logs"
  
  func init() {
  	os.MkdirAll(logDir, 0o755)
  }
  
  // Helper to write a JSON line into the file.
  func (l *Logger) _write(level, message string, ctx map[string]interface{}) error {
  	entry := map[string]interface{}{
  		"timestamp": time.Now().UTC().Format(time.RFC3339),
  		"level":     level,
  		"message":   message,
  	}
  	if len(ctx) > 0 {
  		for k, v := range ctx {
  			entry[k] = v
  		}
  	}
  
  	data, err := ioutil.ReadFile(filepath.Join(logDir, "app.log"))
  	var lines []interface{}
  	if err == nil && string(data) != "" {
  		err = json.Unmarshal(data, &lines)
  		if err != nil {
  			return fmt.Errorf("parsing existing log: %w", err)
  		}
  	}
  	lines = append(lines, entry)
  
  	out, err := json.MarshalIndent(lines, "", "  ")
  	if err != nil {
  		log.Printf("marshaling error: %v", err)
  	} else {
  		err = ioutil.WriteFile(filepath.Join(logDir, "app.log"), out, 0o644)
  		if err != nil {
  			return fmt.Errorf("writing log file: %w", err)
  		}
  	}
  
  	return nil
  }
  
  func (l *Logger) Debug(ctx map[string]interface{}, msg string) {
  	l._write("debug", msg, ctx)
  }
  func (l *Logger) Info(ctx map[string]interface{}, msg string) {
  	l._write("info", msg, ctx)
  }
  func (l *Logger) Warn(ctx map[string]interface{}, msg string) {
  	l._write("warn", msg, ctx)
  }
  func (l *Logger) Error(ctx map[string]interface{}, msg string) {
  	l._write("error", msg, ctx)
  }
  
