// main.go
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/mux" // optional, but can use std mux too
)

type HealthPayload struct {
	Timestamp string    `json:"timestamp"`
	Service   string    `json:"service"`
	Status    string    `json:"status"`
	Details   map[string]bool `json:"details,omitempty"`
}

func dbCheck() (bool, error) {
	// Replace with real DB logic.
	return true, nil
}
func cacheCheck() (bool, error) {
	return true, nil // example: Redis/Memcached …
}
func queueCheck() (bool, error) {
	return true, nil // e.g., RabbitMQ/Kafka/SQS…
}

var (
	mu      sync.Mutex
	status  string   = "UP"
	checks  []string = []string{"db", "cache", "queue"}
)

// Helper to update shared status atomically.
func setStatus(st string) {
	mu.Lock()
	defer mu.Unlock()
	if st == "UP" && status != "UP" {
		fmt.Println("Service transitioned from DOWN → UP")
	}
	status = st
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()

	vars := make([](func() (bool, error)), len(checks))
	for i, name := range checks {
		switch name {
		case "db":
			vars[i] = dbCheck
		case "cache":
			vars[i] = cacheCheck
		case "queue":
			vars[i] = queueCheck
		default:
			vars[i] = func() (bool, error) { return false, fmt.Errorf("unknown dependency %q", name)}
		}
	}

	details := make(map[string]bool)
	for i, fn := range vars {
		ok, err := fn()
		if err != nil {
			log.Printf("%s check failed: %v", checks[i], err)
			details[checks[i]] = false
		} else {
			details[checks[i]] = true
		}
	}

	payload := HealthPayload{
		Timestamp: time.Now().UTC().Format(time.RFC3339),
		Service:   "Aura‑Benchmark",
		Status:    strings.ToUpper(status),
		Details:   details,
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(payload)

	if status == "UP" {
		log.Println("Service is UP – health check succeeded")
	} else {
		log.Printf("Health check failed, service now DOWN (%s)", status)
	}
}

func main() {
	http.HandleFunc("/healthz", healthHandler)

	port := os.Getenv("PORT", "8080")
	fmt.Printf("🚀 Service listening on http://0.0.0.0:%v/healthz\n", port)
	err := http.ListenAndServe(fmt.Sprintf("0.0.0.0:%v", port), nil)
	if err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}
