## 1️⃣ TypeScript implementation  

```ts
/**
 * SlidingWindowMetrics – keeps count, sum, min, max and average for a sliding window.
 *
 * @param windowMs   Size of the moving time‑window (milliseconds).
 */
class SlidingWindowMetrics {
    private readonly windowMs: number;
    /** current timestamp in ms (used to compute “now”) */
    private now = Date.now();
    /** circular buffer – stores {value, ts} pairs */
    private buffer: Array<{ value: number; ts: number }> = [];
    /** running aggregates */
    count = 0;
    sum   = 0;
    min   = Number.POSITIVE_INFINITY;
    max   = Number.NEGATIVE_INFINITY;

    constructor(windowMs: number) {
        this.windowMs = windowMs;
    }

    /**
     * Add a new numeric sample.
     *
     * @param value The metric value (must be comparable with <, >).
     */
    add(value: number): void {
        // keep only the newest samples that still belong to the window
        const now = Date.now();
        while (
            this.buffer.length > 0 &&
            now - this.buffer[0].ts >= this.windowMs
        ) {
            const oldest = this.buffer.shift()!;
            this.count--;
            this.sum -= oldest.value;
            if (oldest.value < this.min)   this.min = oldest.value;
            if (oldest.value > this.max)   this.max = oldest.value;
        }

        // insert the new sample at the end
        const entry: { value: number; ts: number } = {
            value,
            ts: now,
        };
        this.buffer.push(entry);

        // update aggregates
        this.count++;
        this.sum += entry.value;
        if (entry.value < this.min)   this.min = entry.value;
        if (entry.value > this.max)   this.max = entry.value;

        // keep the running timestamps in sync with now – optional but handy for debugging
        this.now = Date.now();
    }

    /**
     * Returns a snapshot of all aggregates.
     */
    getSnapshot(): {
        count: number;
        sum: number;
        min: number | null;
        max: number | null;
        avg?: number; // undefined when count === 0
    } {
        const hasData = this.count > 0;
        return {
            count,
            sum,
            min: hasData ? this.min : null,
            max: hasData ? this.max : null,
            avg: hasData ? (this.sum / this.count) : undefined,
        };
    }
}
