import time

class SlidingWindowMetrics:
    """
    Keeps count, sum, min, max and average for a sliding window.
    
    Parameters:
        window_ms: Size of the moving time‑window in milliseconds.
    """

    def __init__(self, window_ms: int):
        self.window_ms = window_ms
        self.buffer = []          # list of (value, timestamp)
        self.count = 0
        self.sum   = 0.0
        self.min_val = None      # will be set on first valid entry
        self.max_val = None

    def add(self, value: float) -> None:
        """Add a new numeric sample."""
        now = time.time() * 1000          # current timestamp in ms

        # purge old entries that fall outside the window
        while self.buffer and (now - self.buffer[0][1] >= self.window_ms):
            _, ts = self.buffer.pop(0)
            self.count -= 1
            self.sum   -= float(ts)       # not needed; just keep consistent with TS version
            if self.min_val is None or float(ts) < self.min_val:
                self.min_val = float(ts)
            if self.max_val is None or float(ts) > self.max_val:
                self.max_val = float(ts)

        # insert new sample at the end (order preserved by time)
        entry = (value, now)
        self.buffer.append(entry)

        # update aggregates
        self.count += 1
        self.sum   += value
        if self.min_val is None or value < self.min_val:
            self.min_val = value
        if self.max_val is None or value > self.max_val:
            self.max_val = value

    def get_snapshot(self) -> dict:
        """
        Returns a dictionary with the current aggregates.
        
        {
            "count": int,
            "sum": float,
            "min": float | None,
            "max": float | None,
            "avg": float | None   # undefined when count == 0
        }
        """
        if self.count == 0:
            return {"count": 0, "sum": 0.0, "min": None, "max": None, "avg": None}
        avg = self.sum / self.count
        return {
            "count": self.count,
            "sum": self.sum,
            "min": self.min_val,
            "max": self.max_val,
            "avg": avg,
        }
