class SnowflakeId {
  private static readonly BITS = {
    TIMESTAMP_BITS: 42,   // ~69 years
    MACHINE_ID_BITS: 5,   // up to 32 machines
    RANDOM_BYTES_BITS: 80,
  };

  /** Number of milliseconds since epoch (UTC). */
  private timestampMs!: number;

  constructor(
    /**
     * Optional – if omitted the current time is used.
     * Useful for deterministic testing or seeding.
     */
    initialTimestampMs?: number
  ) {
    this.timestampMs = initialTimestampMs ?? Date.now();
  }

  /** Generate a new ID. */
  generate(): string {
    const now = Math.floor(this.timestampMs / 1000); // seconds → fits in timestamp_bits

    // ---- build the bits -------------------------------------------------
    const tsMask   = ((1 << SnowflakeId.BITS.TIMESTAMP_BITS) - 1);
    const machineMask = ((1 << SnowflakeId.BITS.MACHINE_ID_BITS) - 1);

    const randomBytesHex =
      Math.floor(Math.random() * (1 << SnowflakeId.BITS.RANDOM_BYTES_BITS))
        .toString(16)
        .padStart(SnowflakeId.BITS.RANDOM_BYTES_BITS / 4, '0');

