package snowflakeid

import (
	"crypto/rand"
	"encoding/binary"
	"math/big"
	"time"
)

// SnowflakeId generator – 64‑bit layout:
//   • timestamp (42 bits) – seconds since Unix epoch (UTC)
//   • machine_id    (5 bits) – up to 32 machines
//   • random_bytes  (80 bits) – cryptographically secure randomness

type Generator struct {
	timestampSeconds int64 // current time in seconds
	machineID       uint8  // set later via SetMachineID()
}

const (
	// Bits per field as defined in the other languages.
	bitsTimestamp = 42
	bitsMachine   = 5
	bitsRandom    = 80
)

func New() *Generator {
	return &Generator{
		timestampSeconds: time.Now().Unix(),
		machineID:        uint8(0), // will be overwritten by SetMachineID()
	}
}

// Generate returns a hex string (fixed length) representing the ID.
func (g *Generator) Generate() string {
	nowSec := g.timestampSeconds
	tsMask   := big.NewInt(int64((1 << bitsTimestamp) - 1))
	machineMask := big.NewInt(int64((1 << bitsMachine) - 1))

	// ---- pack random bytes -------------------------------------------------
	randomBytes, _ := rand.Int(rand.Reader, big.NewInt(1<<bitsRandom))
	randomBigInt := new(big.Int).Set(randomBytes)

	// ---- compute final integer ---------------------------------------------
	idBigInt := new(big.Int)
	idBigInt.Lsh(idBigInt, uint(bitsMachine+bitsRandom)) // shift for machine + random
	idBigInt.Or(idBigInt, big.NewInt(int64(g.machineID)<<bitsRandom))
	idBigInt.Or(idBigInt, randomBigInt)

	// Convert to hex with leading zeros so length is always fixed.
	hexLen := (bitsTimestamp + bitsMachine + bitsRandom) / 4
	return idBigInt.Text(16).PadRight(hexLen, '0')
}

// SetMachineID validates and stores the machine identifier (< 32).
func (g *Generator) SetMachineID(machineID uint8) {
	if int64(machineID) < 0 || int64(machineID) >= (1<<bitsMachine) {
		panic("machine_id must be in range [0,31]")
	}
	g.machineID = machineID
}

// GetTimestamp returns the timestamp part as seconds since epoch.
func (g *Generator) GetTimestamp() int64 { return g.timestampSeconds }

