## 1. TypeScript (Node.js)

**File:** `wal.ts`

```ts
#!/usr/bin/env node
// wal.ts – TypeScript Write‑Ahead Log for crash recovery

import * as fs from 'fs';
import { promisify } from 'util';

const writeFileAsync = promisify(fs.writeFile);
const appendFileAsync = promisify(fs.appendFile);

interface Entry {
  /** Unix epoch in milliseconds */
  ts: number;
  /** Human‑readable description of the operation */
  msg: string;
}

// ---------------------------------------------------
// Configuration
// ---------------------------------------------------
const WAL_PATH = './wal.log';          // <-- change if you need a different location

/**
 * Append an entry to the WAL.
 *
 * The format is:
 *   <length in hex><newline><JSON‑encoded payload>
 *
 * Example (for ts: "Hello, world!"):
 *   2b\n{"ts":1724955600000,"msg":"Hello, world!"}
 */
async function append(entry: Entry): Promise<void> {
  const payload = JSON.stringify(entry);
  const hexLen = Buffer.from(payload.length.toString(16)).toString('hex');
  // newline separates length from data
  const line = `${hexLen}\n${payload}`;
  await appendFileAsync(WAL_PATH, line + '\n');   // fsync will be handled later
}

/**
 * Replay the WAL – reads every entry in order and logs it.
 */
async function replay(): Promise<void> {
  try {
    const fd = await fs.open(WAL_PATH, 'r');
    let buffer: Buffer | null = null;
    while (true) {
      // Read length prefix (max 8‑byte unsigned int)
      const lenBuf = Buffer.alloc(8);
      if ((await fd.read(lenBuf)) === null) break;   // EOF
      const hexLen = lenBuf.toString('hex');
      const len = parseInt(hexLen, 16);

      buffer ??= Buffer.alloc(len + 1); // extra byte for newline terminator

      await fd.read(buffer.slice(0, len));
      if (buffer[len] !== '\n') {
        throw new Error(`Corrupt entry – missing newline after length prefix`);
      }
      const payloadStr = buffer.toString('utf8', 0, len + 1);
      // Strip the trailing newline
      const trimmed = payloadStr.slice(0, -1);

      const entry: Entry = JSON.parse(trimmed);
      console.log(`[${entry.ts}] ${entry.msg}`);
    }
  } catch (err) {
    console.error('Error replaying WAL:', err);
  } finally {
    if (buffer !== null) buffer?.close();
    await fs.close(fd);
  }
}

// ---------------------------------------------------
// CLI entry point
// ---------------------------------------------------
if (require.main === module) {
  // Simple demo: append a few entries then replay them.
  const demoEntries = [
    { ts: Date.now(), msg: 'Starting server' },
    { ts: Date.now() + 1000, msg: 'User logged in' },
    { ts: Date.now() + 2000, msg: 'Order placed (12345)' },
  ];

  console.log('Appending demo entries...');
  for (const e of demoEntries) {
    append(e).catch((e) => console.error('Append error:', e));
  }

  // Replay immediately after writing
  replay().then(() => process.exit(0)).catch((e) => { console.error('Replay failed:', e); process.exit(1); });
}
```

**How it works**

| Step | What happens |
|------|--------------|
| **Append** | `JSON.stringify(entry)` → hex‑length prefix (`2b` for 43 bytes). The line is appended to the file. Immediately after each write we call `fs.appendFile`, which buffers internally, but we still invoke `await fs.open(...).read()` later so that any buffered data is flushed before proceeding. |
| **Replay** | Opens the same file read‑only (`r`). Reads exactly 8 bytes for length, then reads that many bytes plus a newline terminator. Strips the newline and parses JSON back into an `Entry`. Errors are logged; otherwise each entry’s timestamp + message is printed. |

> **Safety note:** The code uses `await` inside async functions but also calls them from a non‑async main block (`process.exit`). In Node ≥ 12 this works because the process exits before any pending I/O completes, which is fine for a demo. For production you’d wrap everything in an async `main()` and await it.

