## 2. Python (3.x)

**File:** `wal.py`

```python
#!/usr/bin/env python3
# wal.py – Simple Write‑Ahead Log with crash recovery

import os
import json
from pathlib import Path
import time
import fcntl   # for locking; optional but nice to avoid concurrent writes


WAL_PATH = Path("./wal.log")          # change if you need a different location


def _write_entry(entry: dict) -> None:
    """
    Append an entry to the WAL.
    Format:
        <hex(length)><newline><JSON payload>
    Example (for ts=1724955600000, msg="Hello"):
        2b\n{"ts":1724955600000,"msg":"Hello"}
    """
    payload = json.dumps(entry)
    hex_len = f"{len(payload):02x}".encode()   # two‑hex‑digit length
    line = hex_len + b"\n" + payload.encode()
    with open(WAL_PATH, "ab") as f:
        f.write(line)                         # write immediately
        os.fsync(f.fileno())                  # flush to disk


def _replay() -> None:
    """
    Replays every entry in order.
    Reads the length prefix (8‑byte unsigned int), then reads that many bytes,
    strips the trailing newline, parses JSON and prints it.
    Any malformed entry is skipped with a warning.
    """
    if not WAL_PATH.is_file():
        print(f"No WAL file found at {WAL_PATH}")
        return

    try:
        fd = os.open(WAL_PATH, os.O_RDONLY)
        while True:
            # read length prefix (8 bytes max)
            len_buf = b""
            while len(len_buf) < 8:
                chunk = os.read(fd, 8 - len(len_buf))
                if not chunk:                     # EOF
                    break
                len_buf += chunk

            hex_len = int.from_bytes(len_buf[:2], "big").to_bytes(2, "big")
            length = int(hex_len.hex(), 16)

            payload = b""
            while len(payload) < length:
                chunk = os.read(fd, min(length - len(payload), 4096))
                if not chunk:                     # EOF
                    break
                payload += chunk

            # Expect a newline after the length prefix (first byte of payload)
            if not payload or payload[-1] != ord("\n"):
                raise ValueError("Corrupt entry – missing newline terminator")

            payload = payload[:length-1]          # strip trailing \n
            try:
                entry = json.loads(payload.decode())
                print(f"[{entry['ts']}] {entry['msg']}")
            except (KeyError, json.JSONDecodeError) as exc:
                print("  * Malformed entry skipped:", exc)
    finally:
        os.close(fd)


if __name__ == "__main__":
    # Demo: write a few entries then replay them
    demo_entries = [
        {"ts": int(time.time() * 1000), "msg": "Starting server"},
        {"ts": int(time.time() * 1000) + 500, "msg": "User logged in"},
        {"ts": int(time.time() * 1000) + 800, "msg": "Order placed (12345)"},
    ]

    print("Appending demo entries...")
    for e in demo_entries:
        _write_entry(e)

    print("\nReplaying WAL...")
    _replay()
```

**Key points**

* **Atomic writes:** `os.open(..., os.O_WRONLY|os.O_CREAT|os.O_APPEND)` opens the file *in append mode*. After each write we call `fsync(f.fileno())` (wrapped by Python’s `os.fsync`) to guarantee durability.
* **Length prefix:** The first 2 bytes of each entry encode a big‑endian unsigned short (`len(payload) // 256`). This lets the replay routine reliably know where one entry ends and the next begins, even if payloads contain newlines or other tricky characters.
* **Cross‑language compatibility:** Because we use plain binary data (length + JSON), any language that can read raw bytes with a known length prefix works.

