## 3. Go

**File:** `wal.go`

```go
package main

import (
	"encoding/binary"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"
	"time"

	"golang.org/x/sys/unix" // for fsync
)

// Entry mirrors the payload we store in the WAL.
type Entry struct {
	Ts  int64 `json:"ts"`   // Unix epoch ms
	Msg string `json:"msg"`
}

const walPath = "./wal.log" // change if needed

func main() {
	// -----------------------------------------------------------------
	// Demo: write a few entries then replay them (run once to see effect)
	// -----------------------------------------------------------------
	demoEntries := []Entry{
		{Ts: time.Now().UnixNano() / 1_000_0, Msg: "Starting server"},
		{Ts: int64(time.Now().Add(500 * time.Millisecond).UnixNano() / 1e6), Msg: "User logged in"},
		{Ts: int64(time.Now().Add(800 * time.Millisecond).UnixNano() / 1e6), Msg: "Order placed (12345)"},
	}

	fmt.Println("Appending demo entries...")
	for _, e := range demoEntries {
		if err := appendEntry(e); err != nil {
			log.Fatalf("append failed: %v", err)
		}
	}
	fmt.Println("\nReplaying WAL...")
	replay()
}

// -----------------------------------------------------------------
// Helper functions
// -----------------------------------------------------------------

func appendEntry(entry Entry) error {
	data, err := json.Marshal(entry)
	if err != nil {
		return fmt.Errorf("marshal entry: %w", err)
	}
	payloadLen := len(data)

	// 1️⃣ Write length (4‑byte big‑endian unsigned int)
	f, err := os.OpenFile(walPath, os.O_WRONLY|os.O_APPEND|os.O_CREATE, 0600)
	if err != nil {
		return fmt.Errorf("open WAL: %w", err)
	}
	defer f.Close()

	buf := make([]byte, 4)
	binary.BigEndian.PutUint32(buf, uint32(payloadLen))
	if _, err = f.Write(buf); err != nil {
		return fmt.Errorf("write length prefix: %w", err)
	}

	// 2️⃣ Write JSON payload
	if _, err := f.Write(data); err != nil {
		return fmt.Errorf("write payload: %w", err)
	}
	if err = unix.Fsync(int(f.Fd())); err != nil {
		return fmt.Errorf("fsync WAL: %w", err)
	}

	fmt.Printf("[%.0f] %s\n", entry.Ts/1e3, entry.Msg) // human‑readable timestamp
	return nil
}

func replay() {
	if _, err := os.Stat(walPath); os.IsNotExist(err) {
		fmt.Printf("No WAL file found at %q\n", walPath)
		return
	}
	f, err := os.Open(walPath)
	if err != nil {
		log.Fatalf("open WAL: %v", err)
	}
	defer f.Close()

	for {
		var payloadLen uint32
		if _, err = binary.ReadFull(f, make([]byte, 4)); err != nil {
			break // EOF reached
		}
		payloadLen = binary.BigEndian.Uint32(buf[:])
		buf := make([]byte, payloadLen+1) // +1 for newline terminator

		n, err := f.Read(buf)
		if err != nil && err != io.EOF {
			log.Fatalf("read payload: %v", err)
		}
		if int(n) < payloadLen+1 {
			fmt.Println("  * Incomplete entry – ignoring")
			continue
		}

		payload := buf[:payloadLen]
		if payload[payloadLen-1] != '\n' {
			log.Printf("  * Corrupt entry (missing newline): %q", string(payload))
			continue
		}
		payload = payload[:payloadLen-1]

		var e Entry
		err = json.Unmarshal(payload, &e)
		if err != nil {
			fmt.Printf("  * Malformed JSON: %v\n", err)
			continue
		}

		ts := time.Unix(0, int64(e.Ts*1e3))
		fmt.Printf("[%s] %s\n", ts.Format(time.RFC3339Nano), e.Msg)
	}
}
```

**Explanation of the WAL mechanics**

| Step | What Go does |
|------|--------------|
| **Append** | 1️⃣ Write a 4‑byte big‑endian unsigned integer representing the JSON payload length. <br>2️⃣ Append the raw JSON bytes. <br>3️⃣ Immediately call `unix.Fsync(int(f.Fd()))` to force the OS to flush both data and metadata to disk before returning, guaranteeing durability even after a crash. |
| **Replay** | 1️⃣ Open file for reading (`os.Open`). <br>2️⃣ Read exactly 4 bytes → length of next entry. <br>3️⃣ Allocate a buffer large enough (payload + newline). <br>4️⃣ Read that many bytes, strip the trailing `\n`, parse JSON back into an `Entry`. <br>5️⃣ Print timestamp (`ts/1e3`) and message. Any malformed entry is logged and skipped. |
| **Safety** | *Atomicity*: each write consists of a length prefix followed by data; both are written sequentially, so no partial writes exist.<br>*Durability*: `fsync` after every write ensures that even if power fails mid‑write the log can be recovered from start to finish.<br>*Recovery*: Because entries are self‑describing (length + JSON), corrupted or truncated entries simply get ignored; replay resumes cleanly. |

