// vector_clock_demo.ts
/**
 * Simple Vector Clock implementation.
 *
 * A vector clock is an array of integers, one per node.  
 * When a node performs an event it increments its own entry;
 * when sending a message it also propagates the current values
 * from the other nodes (merge step).
 */

type NodeId = string;

/**
 * The VectorClock class.
 */
class VectorClock {
  /** Map: nodeId → counter value */
  private counters: Record<NodeId, number>;

  constructor(nodes: NodeId[]) {
    this.counters = {};
    for (const nid of nodes) {
      this.counters[nid] = 0;
    }
  }

  /**
   * Increment the counter for **myNode** and return a copy.
   */
  public increment(myNode: NodeId): VectorClock {
    const newCopy = new VectorClock(Object.keys(this.counters));
    newCopy.counters[myNode]++;
    // merge with existing counters (no need to mutate self)
    for (const nid in this.counters) {
      if (!newCopy.counters[nid] || newCopy.counters[nid] < this.counters[nid]) {
        newCopy.counters[nid] = this.counters[nid];
      }
    }
    return newCopy;
  }

  /**
   * Compare two vector clocks.
   *
   * Returns:
   *   - true  if `this` <= other (all counters ≤)
   *   - false otherwise
   */
  public isLessOrEqual(other: VectorClock): boolean {
    for (const nid in this.counters) {
      if (!other.counters[nid] || this.counters[nid] > other.counters[nid]) {
        return false;
      }
    }
    return true; // all counters ≤
  }

  /**
   * Merge two vector clocks – used when receiving a message.
   */
  public merge(other: VectorClock): VectorClock {
    const result = new VectorClock(Object.keys(this.counters));
    for (const nid in this.counters) {
      if (!other.counters[nid] || this.counters[nid] < other.counters[nid]) {
        result.counters[nid] = other.counters[nid];
      }
    }
    return result;
  }

  /** Human‑readable string representation */
  public toString(): string {
    const entries: string[] = [];
    for (const nid in this.counters) {
      entries.push(`${nid}=${this.counters[nid]}`);
    }
    return `{${entries.join(", ")}}`;
  }
}

/**
 * -----------------------------------------------------------------
 *   DEMO – how to use the VectorClock class
 */
function demo() {
  const nodes = ["nodeA", "nodeB", "nodeC"];

  // Create clocks for each node (they start at zero)
  const vcA = new VectorClock(nodes);
  const vcB = new VectorClock(nodes);
  const vcC = new VectorClock(nodes);

  console.log("Initial clocks:");
  console.log(vcA.toString());
  console.log(vcB.toString());
  console.log(vcC.toString());

  // Simulate events:
  //   Node A performs event → increment its own counter
  vcA.increment("nodeA");
  console.log("\nAfter nodeA increments (event #1):", vcA);

  // Node B receives a message from A and merges clocks
  const msgFromA = { source: "nodeA", vector: vcA };
  vcB.merge(msgFromA.vector);
  console.log("Node B after receiving A's clock:", vcB);

  // Node C performs its own event
  vcC.increment("nodeC");
  console.log("\nAfter nodeC increments (event #2):", vcC);

  // Compare clocks to decide causality:
  const compareAB = vcA.isLessOrEqual(vcB);
  const compareAC = vcA.isLessOrEqual(vcC);
  const compareBC = vcB.isLessOrEqual(vcC);

  console.log("\nComparisons:");
  console.log(`vcA ≤ vcB? → ${compareAB}`);
  console.log(`vcA ≤ vcC? → ${compareAC}`);
  console.log(`vcB ≤ vcC? → ${compareBC}`);

