// ---------------------------------------------------
//  Two‑Phase Commit Protocol (TypeScript)
// ---------------------------------------------------
type Vote = 'prepare' | 'commit' | 'abort';

interface Participant {
    id: string;                     // unique identifier, e.g. "A" or "B"
    prepare(): Promise<Vote>;
    commit(txId: string): Promise<void>;
    abort(txId: string): Promise<void>;
}

/**
 * Simple in‑memory coordinator that orchestrates the 2PC flow.
 */
class Coordinator<T extends Participant> {
    private participants: T[];

    constructor(...participants: T[]) {
        this.participants = participants;
    }

    /** Starts a new transaction identified by txId. Returns true if all votes were "commit". */
    async run(txId: string): Promise<boolean> {
        // 1️⃣ Prepare phase
        const prepareVotes: Vote[] = await Promise.all(
            this.participants.map(p => p.prepare())
        );

        // All participants must have voted "prepare"
        if (prepareVotes.some(v => v !== 'prepare')) return false;

        // 2️⃣ Commit phase – each participant does its local work
        const commitPromises: Promise<void>[] = prepareVotes.map((_, i) =>
            this.participants[i].commit(txId)
        );

        await Promise.all(commitPromises);

        // Coordinator confirms success to everyone
        for (const p of this.participants) {
            await p.commit(txId);   // redundant but makes the ACK explicit
        }

        return true;               // all succeeded → coordinator reports OK
    }

    /** Aborts a transaction if any participant voted otherwise. */
    async abort(txId: string): Promise<void> {
        for (const p of this.participants) {
            await p.abort(txId);
        }
    }
}

// ---------------------------------------------------
//  Example participants that simulate work and voting.
// ---------------------------------------------------
class ParticipantImpl implements Participant {
    private id: string;
    private txId?: string;

    constructor(public readonly name: string, private readonly timeoutMs = 2000) {
        this.id = name;
    }

    async prepare(): Promise<Vote> {
        console.log(`[${this.name}] → Prepare`);
        // Simulate local work (could be DB write, file I/O, etc.)
        await new Promise(r => setTimeout(r, Math.random() * 1500));
        return 'prepare';
    }

    async commit(txId: string): Promise<void> {
        this.txId = txId;
        console.log(`[${this.name}] → Commit (tx=${txId})`);
        // Real work would be here
        await new Promise(r => setTimeout(r, Math.random() * 1500));
    }

    async abort(txId: string): Promise<void> {
        if (!this.txId || this.txId !== txId) return;
        console.log(`[${this.name}] → Abort (tx=${txId})`);
        // Simulate cleanup
        await new Promise(r => setTimeout(r, Math.random() * 1500));
    }
}

// ---------------------------------------------------
//  Demo usage – run a transaction across two participants.
// ---------------------------------------------------
async function demoTwoPhaseCommit() {
    const participantA = new ParticipantImpl('Participant A');
    const participantB = new ParticipantImpl('Participant B');

    const coordinator = new Coordinator(participantA, participantB);

    // Run the same logical transaction ID on both sides
    const allSucceeded = await coordinator.run('tx-001');

    if (allSucceeded) {
        console.log('✅ All participants committed successfully.');
    } else {
        console.log('❌ One or more participants aborted – rolling back.');
    }
}

// Run demo when executed as a script.
if (require.main === module) {
    demoTwoPhaseCommit().catch(console.error);
}
```

### What the code does

| Step | Code fragment | Explanation |
|------|---------------|-------------|
| **1️⃣ Prepare** | `await Promise.all(participants.map(p => p.prepare()))` | All participants are asked “are you ready?”; each returns `'prepare'`. If any return a different value, the coordinator aborts. |
| **2️⃣ Commit work** | `await participant.commit(txId)` inside an array comprehension | Each participant does its local transaction (e.g., DB insert). The order of calls is not important because they all run concurrently; we later wait for them all to finish before telling everyone “commit”. |
| **3️⃣ Confirm** | Loop that calls `p.commit(txId)` again and then returns `true` only when every participant voted `'commit'`. | This step acts as the *acknowledgement* phase: after local work, each participant informs the coordinator it may finish. |
| **4️⃣ Abort (fallback)** | Separate `abort()` method called by coordinator if any vote ≠ `'prepare'`. | Participants roll back whatever they started and reply ACK/FAIL to the coordinator. |

The protocol is fully synchronous – every call blocks until a response arrives, guaranteeing that either *all* participants have committed or none have.

