# ---------------------------------------------------
# Two‑Phase Commit Protocol (Python)
# ---------------------------------------------------
from typing import List, Tuple, Callable

class Participant:
    """
    Minimal interface for a participant in the 2PC protocol.
    Each method returns a string vote: 'prepare', 'commit' or 'abort'.
    """
    def __init__(self, name: str):
        self.name = name
        # Optional timeout to simulate work duration
        self._timeout_ms = 2000

    async def prepare(self) -> str:
        raise NotImplementedError

    async def commit(self, tx_id: str) -> None:
        raise NotImplementedError

    async def abort(self, tx_id: str) -> None:
        raise NotImplementedError


class Coordinator:
    """
    Simple two‑phase coordinator.
    All participants must vote 'prepare' before any participant may call `commit`.
    If a single participant votes otherwise the whole transaction is aborted.
    """
    def __init__(self, *participants: Participant):
        self.participants = list(participants)

    async def run(self, tx_id: str) -> bool:
        # ---- Prepare phase -------------------------------------------------
        prepare_votes = await asyncio.gather(*(p.prepare() for p in self.participants))
        if 'abort' in prepare_votes or 'commit' not in prepare_votes:
            return False   # any non‑prepare vote aborts

        # ---- Commit work (local transaction) -------------------------------
        commit_tasks = [
            participant.commit(tx_id)
            for participant in self.participants
        ]
        await asyncio.gather(*commit_tasks)

        # ---- Confirmation -------------------------------------------------
        # Each participant explicitly tells the coordinator it may finish.
        confirm_futures = [participant.commit(tx_id) for participant in self.participants]
        await asyncio.gather(*confirm_futures)

        return True   # all succeeded → coordinator reports OK


