import asyncio, random

class ParticipantImpl(Participant):
    def __init__(self, name: str, timeout_ms: int = 2000):
        super().__init__(name)
        self._timeout_ms = timeout_ms

    async def prepare(self) -> str:
        print(f"[{self.name}] → Prepare")
        # Simulate work (could be DB write, file I/O, etc.)
        await asyncio.sleep(random.uniform(1.2, 3.0))
        return 'prepare'

    async def commit(self, tx_id: str) -> None:
        self._tx_id = tx_id
        print(f"[{self.name}] → Commit (tx={tx_id})")
        await asyncio.sleep(random.uniform(1.2, 3.0))

    async def abort(self, tx_id: str) -> None:
        if self._tx_id != tx_id:
