Event = dict[str, Any]

def counter_reducer(state: int, event: Event) -> int:
    """Pure reducer – deterministic and idempotent."""
    typ = event['type']
    if typ == 'INCREMENT':
        return state + event['payload']
    # Unknown events are ignored → no change
    return state


class EventQueue:
    def __init__(self):
        self._queue: list[Event] = []

    def enqueue(self, event: Event) -> None:
        self._queue.append(event)

    def dequeue_all(self) -> list[Event]:
        """Consume all events; returns a copy so the caller can't modify."""
        return list(self._queue)
    # (optional clear method)


class Replica:
    def __init__(self):
        self._state: int = 0

    def apply(self, event: Event) -> None:
        self._state = counter_reducer(self._state, event)

    @property
    def state(self) -> int:
        return self._state


# ---------------------------------------------------
# Example usage – interleaved processing yields the same result
# ---------------------------------------------------
queue1 = EventQueue()
queue2 = EventQueue()

# Queue events in any order; they will be processed later.
queue1.enqueue({'type': 'INCREMENT', 'payload': 5})
queue1.enqueue({'type': 'INCREMENT', 'payload': 3})

queue2.enqueue({'type': 'INCREMENT', 'payload': 3})
queue2.enqueue({'type': 'INCREMENT', 'payload': 5})

# Apply events on replica A
replica_a = Replica()
for ev in queue1.dequeue_all():
    replica_a.apply(ev)

print('Replica A final state:', replica_a.state)   # → 8

# Apply the same set of events on replica B (order may differ)
replica_b = Replica()
for ev in queue2.dequeue_all():
    replica_b.apply(ev)

print('Replica B final state:', replica_b.state)   # → 8
