   * In a real system each replica would have its own DB / cache,
   * but here we keep everything in‑memory for clarity.
   */
  class Replica {
    private _state: number = 0;
  
    // Expose only via pure functions so the logic stays deterministic
    apply(event: Event): void {
      this._state = counterReducer(this._state, event);
    }
  
    get state(): number {
      return this._state;
    }
  }
  
  // ---------------------------------------------------
  // Example usage – different orders of events still converge
  // ---------------------------------------------------
  const queue = new EventQueue();
  
  queue.enqueue({ type: 'INCREMENT', payload: 5 });
  queue.enqueue({ type: 'INCREMENT', payload: 3 });
  
  const replicaA = new Replica();
  replicaA.apply(queue.dequeueAll()[0]); // {type:'INCREMENT',payload:5}
  replicaA.apply(queue.dequeueAll()[1]); // {type:'INCREMENT',payload:3}
  
  console.log('Replica A final state:', replicaA.state); // → 8
  
  // ---------------------------------------------------
  // Mirror the same sequence on a second replica (order may differ)
  // ---------------------------------------------------
  const queue2 = new EventQueue();
  queue2.enqueue({ type: 'INCREMENT', payload: 3 });
  queue2.enqueue({ type: 'INCREMENT', payload: 5 });
  
  const replicaB = new Replica();
  replicaB.apply(queue2.dequeueAll()[0]);
  replicaB.apply(queue2.dequeueAll()[1]);
  
  console.log('Replica B final state:', replicaB.state); // → 8
  
  // Both replicas are now consistent despite the interleaved processing.
  ```
  
  ### Why it works
  * **Deterministic reducer** – `counterReducer` always produces the same new value for a given old state + event, regardless of when that event was processed.
  * **Idempotent** – Re‑applying an already‑processed event does not change the result (`state + 5` twice still yields `state + 10`).
  * **Order‑agnostic** – The queue can be shuffled arbitrarily; after all events are drained, every replica ends up at the same final state.
  
