// Helper: element‑wise scalar activation applied to each entry of an array
function applyActivation(arr: number[], actFn: (z:number)=>number): number[] {
  return arr.map(actFn);
}

// Forward pass – pure math primitives only
/**
 * @param x          Input vector, length `inFeatures`
 * @param W1         Weight matrix from input → hidden, shape `[inFeatures][hiddenSize]`
 * @param b1         Bias vector for hidden layer, length `hiddenSize`
 * @param W2         Weight matrix from hidden → output, shape `[hiddenSize][outFeatures]`
 * @param b2         Output bias vector, length `outFeatures`
 * @param activation Optional scalar activation function (default: identity)
 */
function forwardPass(
  x: number[],
  W1: number[][],          // list of rows
  b1: number[],
  W2: number[][],
  b2: number[],
  activation?: (z:number)=>number   // e.g., Math.sqrt, Math.tanh, etc.
): number[] {
  const hiddenSize = W1[0].length;
  const outFeat    = b2.length;

  // ----- matrix‑vector multiplication -----
  function matVecMul(A: number[][], v: number[]): number[] {
    return A.map(row => row.reduce((sum, a, i) => sum + a * v[i], 0));
  }

  // ----- forward step -----
  const z_h = matVecMul(W1, x).map((s,i)=> s + b1[i]);   // hidden pre‑activation
  let h: number[];
  if (activation) {
    h = applyActivation(z_h, activation);
  } else {
    h = z_h;                     // identity activation → no change
  }

  const y = matVecMul(W2, h).map((s,i)=> s + b2[i]);   // output prediction

  return y;
}

