    max_tokens: opts?.max_tokens ?? undefined,
    temperature: opts?.temperature ?? undefined,
    n?: never; // intentionally omitted – we only ask for one completion
    stream: true,               // <-- enables streaming
    ...opts,
  };

  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const err = await response.text();
    throw new Error(`OpenAI request failed (${response.status}): ${err}`);
  }

  // The API returns a special "stream" header and then streams the `choices[0].delta` stream.
  const reader = response.body?.getReader ? response.body : undefined;
  if (!reader) {
    throw new Error("Unexpected OpenAI response format – no readable body.");
  }

  const decoder = new TextDecoder();
  let lastSeq: string | null = "";

  // The first delta contains the prompt + system messages (if any)
  const initDelta = await readOneChunk(reader);
  if (!initDelta) throw new Error("No initial chunk received");
  console.log(initDelta);

  async function readOneChunk(stream: ReadableStream<Uint8Array>) {
    const { done, value } = await stream.read();
    return !done ? value : null;
  }

  // Helper to concatenate chunks and emit the delta
  let buffer = "";
  while (true) {
    const chunk = await readOneChunk(reader);
    if (!chunk) break; // EOF

    buffer += decoder.decode(chunk, { stream: true });
    const parts = buffer.split("\n");
    for (let i = 0; i < parts.length - 1; ++i) {
      const deltaStr = parts[i];
      lastSeq += "\n" + deltaStr;
      console.log(deltaStr);
    }
    // keep the final partial line for the next iteration
    buffer = parts[parts.length - 1];
  }

  // If there is a trailing incomplete chunk, flush it now.
  if (buffer.trim() !== "") {
    const lastDelta = decoder.decode(buffer, { stream: true });
    console.log(lastDelta);
  }
}

/**
 * Tiny wrapper that reads the first non‑empty chunk from a readable stream.
 */
async function readOneChunk(stream: ReadableStream<Uint8Array>): Promise<Uint8Array | null> {
  const reader = new TransformStream<Uint8Array, Uint8Array>();
  let pending: Uint8Array[] = [];
  // We need to pipe the original stream into our own transform that buffers.
  await new Promise<void>((resolve) => {
    stream.pipeTo(reader.writable).catch(resolve);
    resolve();
  });

  return readOneChunk(stream); // delegate
}
