import os, json, requests

OPENAI_API_KEY = os.getenv("OPENAI_API_KEY")
if not OPENAI_API_KEY:
    raise RuntimeError("Set the environment variable OPENAI_API_KEY")

HEADERS = {
    "Content-Type": "application/json",
    "Authorization": f"Bearer {OPENAI_API_KEY}",
}

def stream_completion(
    model: str,
    prompt: str | dict,
    *,
    max_tokens: int | None = None,
    temperature: float | None = None,
) -> None:
    """
    Streams a completion request to an OpenAI‑compatible LLM.
    The function prints each token (newline‑separated delta) as soon as it arrives.
    """
    payload = {
        "model": model,
        "messages": [ {"role": "user", "content": prompt} ] if not isinstance(prompt, dict)
                     else prompt,
        "max_tokens": max_tokens,
        "temperature": temperature,
        "stream": True,               # <-- enables streaming
        **({k: v for k, v in locals() if k not in ("self", "__annotations__")})
    }

    url = "https://api.openai.com/v1/chat/completions"   # works also with /completions

    resp = requests.post(url, headers=HEADERS, json=payload)
    resp.raise_for_status()

    # The body is a readable stream of newline‑separated JSON deltas.
    reader = iter(resp.iter_lines(decode_unicode=True))

    buffer: str = ""
    for line in reader:
        buffer += "\n" + line
        lines = buffer.split("\n")
        # everything except the last partial line can be emitted immediately
        for delta_str in lines[:-1]:
            print(delta_str)
            buffer = lines[-1]  # keep trailing incomplete chunk

    if buffer.strip():
        print(buffer)   # flush any leftover text


if __name__ == "__main__":
    stream_completion(
        model="gpt-3.5-turbo",
        prompt='Write a short Python function that reads two integers from stdin and prints their sum.',
        max_tokens=30,
        temperature=0.2
    )
