```go
// file: openai_stream.go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
)

const openAIURL = "https://api.openai.com/v1/chat/completions"

type Message struct {
	Role string `json:"role"`
    Content string `json:"content"`
}

func streamCompletion(model, prompt string,
	maxTokens int64, temperature *float64) error {

	payload := map[string]any{
		"model": model,
		"messages": []Message{ { Role: "user", Content: prompt} },
	}
	if maxTokens > 0 {
		payload["max_tokens"] = maxTokens
	}
	if temperature != nil {
		payload["temperature"] = *temperature
	}

	body, err := json.Marshal(payload)
	if err != nil {
		return fmt.Errorf("marshal payload: %w", err)
	}

	req, err := http.NewRequest(http.MethodPost, openAIURL, bytes.NewBuffer(body))
	if err != nil {
		return fmt.Errorf("create request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set(
		"Authorization",
		fmt.Sprintf("Bearer %s", os.Getenv("OPENAI_API_KEY")),
	)

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return fmt.Errorf("openai request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode/100 != 2 {
		b, _ := ioutil.ReadAll(resp.Body)
		return fmt.Errorf("non‑200 response (%d): %s",
			resp.StatusCode, string(b))
	}

	// The API streams newline‑separated JSON deltas.
	var buffer bytes.Buffer
	scanner := bufio.NewScanner(resp.Body)

	for scanner.Scan() {
		line := scanner.Text()
		buffer.WriteString("\n" + line)
		lines := buffer.Split('\n')
		for _, l := range lines[:len(lines)-1] { // everything except last partial chunk
			fmt.Print(l)
		}
		buffer.Reset(lines[len(lines)-1]) // keep trailing incomplete part for next iteration
	}

	if err := scanner.Err(); err != nil {
		return fmt.Errorf("reading response body: %w", err)
	}

	if buffer.Len() > 0 {
		fmt.Print(buffer.String())
	}

	return nil
}

func main() {
	streamCompletion(
		"gpt-3.5-turbo",
		"Write a short Python function that reads two integers from stdin and prints their sum.",
		30,
		nil, // temperature omitted → default 0.0
	)
}
```

### How it works

| Step | What happens |
|------|--------------|
| **POST** | Sends the same JSON payload with `stream:true`. The response body is a newline‑separated stream of JSON objects (`delta`). |
| **bufio.Scanner** | Reads each line as soon as it arrives. We keep a small buffer; whenever we see a full line (ends with `\n`) we print it immediately and discard the rest for the next iteration. This yields token‑by‑token output while still waiting on later tokens. |
| **Environment variable** | The OpenAI key is read from `OPENAI_API_KEY` – same as in the other examples. |

> **Tip:** In Go you could also use `io.TeeReader` with a custom reader that buffers and prints, but the simple scanner pattern shown above keeps it concise.

