/**
 * Cosine similarity between two vectors.
 *
 * @param v1 First vector (array of numbers)
 * @param v2 Second vector (array of numbers)
 * @returns cosine similarity in [-1, 1]
 */
function cosineSimilarity(v1: number[], v2: number[]): number {
    if (v1.length !== v2.length) {
        throw new Error('Vectors must be the same length');
    }

    // dot product
    const dot = v1.reduce((sum, x, i) => sum + x * v2[i], 0);

    // magnitudes
    const magV1 = Math.sqrt(v1.map(x => x ** 2).reduce((a, b) => a + b, 0));
    const magV2 = Math.sqrt(v2.map(x => x ** 2).reduce((a, b) => a + b, 0));

    // guard against zero‑magnitude vectors
    if (magV1 === 0 || magV2 === 0) {
        return NaN; // or throw / handle as appropriate
    }

    return dot / (magV1 * magV2);
}

// Example usage:
