// ---------------------------------------------------
// 1️⃣ Types for request / response (JSON‑compatible)
type Request = {
  tool: string;
  args: any;               // JSON‑serialisable value
};

type Response<T> = {
  success: boolean;
  result?: T;              // optional – can be undefined if error present
  error?: { code: string; message: string };
};

// ---------------------------------------------------
// 2️⃣ Registry definition (map<string, ToolFn>)
type ToolFn = (args: any) => Promise<Response<any>>;

const registry: Record<string, ToolFn> = {
  // Example tools – replace with your real functions
  "greet": async (args: { name?: string }) => ({
    success: true,
    result: args.name ? `Hello, ${args.name}!` : "Hello, world!"
  }),
  "reverseString": async (args: { text: string }) => ({
    success: true,
    result: args.text.split('').reverse().join('')
  }),
};

// ---------------------------------------------------
// 3️⃣ Helper to invoke a tool
async function callTool(req: Request): Promise<Response<any>> {
  const fn = registry[req.tool];
  if (!fn) throw new Error(`No such tool "${req.tool}"`);

  return await fn(req.args);
}

