// 4️⃣ Simple HTTP‑style wrapper (Node.js example)
import express from "express";
const app = express();
app.use(express.json());

app.post("/invoke", async (req, res) => {
  try {
    const result = await callTool(req.body as Request);
    res.status(200).json(result);
  } catch (err: any) {
    console.error(err);
    res
      .status(err?.error?.code ? err.error.code : 500)
      .json({ success: false, error: err });
  }
});

app.listen(3000, () => console.log("Tool registry listening on http://localhost:3000"));
