## 4️⃣ Go implementation  

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"

	"github.com/gorilla/mux" // optional router; can use std net/http directly
)

// ---------------------------------------------------
// Types that mirror JSON request/response (any JSON value)
type Request struct {
	Tool   string          `json:"tool"`
	Args   json.RawMessage `json:"args"` // raw bytes – unmarshalled later
}

type Response struct {
	Success bool         `json:"success"`
	Result  interface{}  `json:"result,omitempty"`
	Error   *ErrorResponse `json:"error,omitempty"`
}

// Helper error wrapper (JSON‑serialisable)
type ErrorResponse struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

var registry = map[string]func(context.Context, json.RawMessage) (*Response, error){
	"greet": func(ctx context.Context, args json.RawMessage) (*Response, error) {
		var a struct{ Name *string `json:"name"` }
		if err := json.Unmarshal(args, &a); err != nil {
			return nil, fmt.Errorf("invalid args: %w", err)
		}
		result := "Hello, world!"
		if a.Name != nil {
			result = fmt.Sprintf("Hello, %s!", *a.Name)
		}
		return &Response{Success: true, Result: result}, nil
	},
	"reverse_string": func(ctx context.Context, args json.RawMessage) (*Response, error) {
		var a struct{ Text string `json:"text"` }
		if err := json.Unmarshal(args, &a); err != nil {
			return nil, fmt.Errorf("invalid args: %w", err)
		}
		result := reverse(a.Text)
		return &Response{Success: true, Result: result}, nil
	},
}

func reverse(s string) string { return string([]rune(s)[::-1]) }

// ---------------------------------------------------
// HTTP handler (mirrors previous examples)
func invoke(w http.ResponseWriter, r *http.Request) {
	var req Request
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid JSON", http.StatusBadRequest)
		return
	}
	resp, ok := registry[req.Tool]
	if !ok {
		w.WriteHeader(http.StatusNotFound)
		json.NewEncoder(w).Encode(Response{Success: false, Error: &ErrorResponse{
			Code:    "NOT_FOUND",
			Message: fmt.Sprintf("tool %q not found", req.Tool),
		}})
		return
	}
	rsp, err := resp(nil, req.Args) // context.Context ignored for simplicity
	if err != nil {
		w.WriteHeader(http.StatusInternalServerError)
		json.NewEncoder(w).Encode(Response{Success: false, Error: &ErrorResponse{
			Code:    "INTERNAL",
			Message: err.Error(),
		}})
		return
	}
	json.NewEncoder(w).Encode(rsp)
}

func main() {
	r := mux.NewRouter()
	r.HandleFunc("/invoke", invoke).Methods("POST")
	http.ListenAndServe(":3000", r) // http://localhost:3000/invoke
}
```

