// conversationHistoryManager.ts -------------------------------------------------
/**
 * A simple in‑memory conversation history manager.
 *
 * • Keeps an ordered list of messages (user ↔ assistant).
 * • Evicts the oldest entry when `maxTokens` is exceeded.
 * • Exposes a single public method: `add(message)` that returns the updated array
 *   and also logs it for convenience.
 *
 * The token budgeting uses OpenAI’s approximate tokenizer (`openai.tokenizer.encode`)
 * so you can plug this directly into an LLM client (ChatGPT, GPT‑4o, etc.).
 */

import { v4 as uuidv4 } from "uuid";
// If you run this inside a Node project that already has `@types/node`, the imports
// below work out‑of‑the‑box.
import * as openai from "openai";

/** Maximum number of tokens allowed in the whole conversation. */
const MAX_TOKENS = 8_000; // <-- adjust to your budget

/**
 * Tokenizer helper – returns an array of token IDs for a given string.
 * (OpenAI’s default tokenizer is used here.)
 */
function tokenize(str: string): number[] {
  return openai.tokenizer.encode(str);
}

/** ConversationHistoryManager class -------------------------------------------------*/
export class ConversationHistoryManager {
  /** Ordered list of messages. Each entry contains an id, role and content. */
  private history: Array<{ id: string; role: "user" | "assistant"; content: string }>;

  constructor() {
    this.history = [];
  }

  /**
   * Add a new turn to the conversation.
   *
   * @param role – either `"user"` (the user) or `"assistant"` (the model).
   * @param text – raw message text.
   */
  public add(role: "user" | "assistant", text: string): Array<{ id: string; role: "user" | "assistant"; content: string }> {
    // Create a unique ID for the turn
    const entryId = uuidv4();

    // Push new turn onto the end of the list (preserving order)
    this.history.push({ id: entryId, role, content: text });

    // Compute total token count *after* adding the new turn
    let totalTokens = 0;
    for (const m of this.history) {
      totalTokens += tokenize(m.content).length;
    }

    // Evict oldest entries until we are under budget
    while (totalTokens > MAX_TOKENS && this.history.length > 1) {
      const removed = this.history.shift(); // remove the first element
      if (!removed) break; // safety check

      totalTokens -= tokenize(removed.content).length;
    }

    // Return the *current* state for convenience / logging
    return [...this.history];
  }

  /** Helper – pretty‑print the whole conversation */
  public toString(): string {
    return this.history.map(m => `${m.role}: ${m.content}`).join("\n");
  }
}

// -----------------------------------------------------------------------------


// Example usage ---------------------------------------------------------------
if (require.main === module) {
  const manager = new ConversationHistoryManager();

  // Simulate a few turns
  for (let i = 0; i < 20000; i++) { // generate many messages to trigger eviction
    manager.add("user", `User ${i}: How are you today?`);
    manager.add("assistant", `Assistant: I'm doing well, thanks! Here's what we discussed so far:\n${manager.toString()}`);
  }

  console.log("\n--- Final conversation (first few lines) ---");
  console.log(manager.toString().split("\n").slice(0, 10).join("\n"));
}
```

### How it works

| Step | What happens |
|------|--------------|
| **Add** | A new turn is appended. The total token count (`openai.tokenizer.encode`) is recomputed. |
| **Evict** | While `totalTokens > MAX_TOKENS` and there’s more than one entry, the oldest message (`shift()`) is removed and its token cost subtracted. This guarantees we never exceed the budget while preserving as much context as possible. |
| **Return** | The manager returns the *current* list so callers can log or feed it to an LLM client (ChatGPT, GPT‑4o, etc.). |

> **Why this works:**  
> - `MAX_TOKENS` is set by you – e.g., 8 000 tokens ≈ a few thousand words. Adjust upward/downward depending on your budget constraints.  
> - Because we use the same tokenizer that OpenAI’s API uses (`openai.tokenizer.encode`), the eviction logic mirrors exactly what would happen if the conversation were sent to an LLM.

