import openai


class ConversationHistoryManager:
    """
    In‑memory conversation history manager.
    
    • Keeps an ordered list of (id, role, content) tuples.
    • Evicts the oldest entry when total token count exceeds `max_tokens`.
    • Uses OpenAI’s tokenizer to compute token usage.
    
    Parameters
    ----------
    max_tokens : int
        Maximum allowed tokens in the whole conversation.
    """

    def __init__(self, max_tokens: int = 8000):
        self.max_tokens = max_tokens
        self.history: List[Dict[str, str]] = []   # each dict: {"id": str, "role": "user"|"assistant", "content": str}

    @staticmethod
    def _tokenize(text: str) -> int:
        """Return approximate token count for a string using OpenAI's tokenizer."""
        return openai.tokenizer.encode(text).__len__()

    def add(self, role: str, text: str) -> List[Dict[str, str]]:
        """
        Append a new turn and evict oldest entries if needed.

        Parameters
        ----------
        role : "user" | "assistant"
            Who is speaking.
        text : str
            The raw message (either user or assistant).

        Returns
        -------
        List[Dict[str,str]]
            Current conversation state after the addition.
        """
        entry_id = uuid.uuid4().hex  # short UUID for uniqueness
        new_entry: Dict[str, str] = {
            "id": entry_id,
            "role": role,
            "content": text,
        }

        self.history.append(new_entry)

        total_tokens = sum(self._tokenize(e["content"]) for e in self.history)
        # Evict oldest entries until we are under budget
        while total_tokens > self.max_tokens and len(self.history) > 1:
            removed = self.history.pop(0)          # remove first element (oldest)
            total_tokens -= self._tokenize(removed["content"])

        return [...self.history]   # immutable copy for callers


