const TOOL_CALL_SCHEMA = new z.Schema<{
  /** The name of the tool to invoke – must be one of the allowed keys */
  tool: "validateToolCall" | "runBenchmark";
  /** Arguments required by each specific tool */
  args: {
    validateToolCall?: { payload: Record<string, unknown> };
