---------------------------------------------------------- */
function safeInvoke(toolsData: any): void {
  // Validate against the schema – throws if invalid
  TOOL_CALL_SCHEMA.parse(toolsData);

  const { tool, args } = toolsData;
  switch (tool) {
    case "validateToolCall":
      validateToolCall(args.payload);
      break;

    case "runBenchmark":
      runBenchmark(args.tier, args.outputFile ?? undefined);
      break;

    default:
      throw new Error(`Unknown tool "${tool}"`);
  }
}

