// simple-repl.ts -------------------------------------------------------------
import * as readline from 'readline';

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
});

let history: string[] = [];
let currentHistoryIndex = -1; // points to the currently‑selected line in `history`

function addHistory(line: string) {
    // keep only the last N lines (here 20)
    if (history.length >= 20) history.shift();
    history.push(line);
}

// Simple REPL loop
rl.on('line', async (input: string) => {
    // store current line in history before evaluating it
    addHistory(input);

    try {
        const result = await evalLine(input);   // <-- replace with your own evaluator if you need AST/compile‑time checks
        console.log(`=> ${result}`);
    } catch (err) {
        console.error('❌ Error:', err);
    }
});

// Optional: bind up / down arrow keys to navigate history
rl.on('SIGINT', () => { // Ctrl+C → exit cleanly
    rl.close();
    process.exit(0);
});
process.stdin.setRawMode(true); // needed for .on('keypress')
rl.on('keypress', (str, key) => {
    if (key?.name === 'up' && history.length > 0) {
        currentHistoryIndex = Math.min(currentHistoryIndex + 1, history.length - 1);
        console.log(history[currentHistoryIndex]);
    } else if (key?.name === 'down') {
        // nothing to do – cursor stays on last line until a new input is entered
    }
});

