/**
 * Very simple evaluator that just runs the JavaScript code.
 *
 * In a real REPL you would probably use Babel/ESBuild or a compiler API,
 * but for demonstration `eval` suffices (be careful with untrusted input!).
 */
async function evalLine(code: string): Promise<string> {
    // strip comments so they don't break things
    const clean = code.replace(/\/\*[\s\S]*?\*\//g, '').trim();
    if (!clean) return '';

    try {
        // Using `new Function` is the simplest way to evaluate a single line.
        // In production you’d want a sandboxed environment (vm2, esprima‑eval,
        // or even just running inside an isolated VM).
        const fn = new Function('return ' + clean);
        const result = await Promise.resolve(fn());
        return String(result);
    } catch (e) {
        throw e;
    }
}
