#!/usr/bin/env python3
"""
Simple REPL (Read-Eval-Print Loop) with command history.
"""

import readline
import sys

# ---------------------------------------------------------------------
# History management -------------------------------------------------
history: list[str] = []
current_index: int = -1          # points to the line we are editing


def add_history(line: str):
    """Keep at most 20 recent lines."""
    if len(history) >= 20:
        history.pop(0)
    history.append(line)


# ---------------------------------------------------------------------
# REPL loop -----------------------------------------------------------
while True:
    try:
        readline.set_startup_hook(lambda: sys.stdout.write(f'{"> "} '))
        readline.parse_and_bind("tab: complete")
        line = input()
    except EOFError:
        break

    # Store the command before evaluating
    add_history(line)

    try:
        result = eval_line(line)          # <-- replace with your own evaluator
        print('=>', result)
    except Exception as exc:
        print('❌ Error:', exc)


# ---------------------------------------------------------------------
def eval_line(code: str):
    """
    Very naive evaluator – just runs the Python statement.
    In production you would use `ast`/`exec` in a restricted namespace,
