// sse-client.ts
import { createEventSource } from 'sse-source';

/**
 * Fetches server‑sent events from the given URL and prints them.
 *
 * @param url – The SSE endpoint (e.g. "http://example.com/events")
 */
async function streamSSE(url: string): Promise<void> {
  // `createEventSource` returns a ReadableStream that emits an event for each line
  const source = createEventSource(url);

  source.addEventListener('open', () => console.log('🔗 Opened connection'));
  source.addEventListener('message', (e) => {
    if (e.data) {
      // `data` is the raw text after the newline separator.
      console.log(`✅ Message: ${e.data}`);
    } else if (e.type === 'error') {
      console.error('❌ SSE error:', e);
    }
  });

  source.addEventListener('close', () => console.log('🔗 Connection closed'));
}

// Example usage
if (require.main === module) {
  // Replace with your own endpoint.
  const endpoint = process.argv[2] || 'http://localhost:3000/sse';
  streamSSE(endpoint);
}
```

