Go’s standard `http` package can read SSE via a simple loop:

```go
// sse_client.go
package main

import (
	"bufio"
	"fmt"
	"io"
	"net/http"
	"os"
)

func streamSSE(url string) error {
	resp, err := http.Get(url)
	if err != nil {
		return fmt.Errorf("failed to GET %s: %w", url, err)
	}
	defer resp.Body.Close()

	if resp.StatusCode/100 != 2 {
		return fmt.Errorf("%s returned non‑200 status: %d", url, resp.StatusCode)
	}

	reader := bufio.NewReader(resp.Body)

	fmt.Println("🔗 Connected to SSE endpoint")
	for {
		line, err := reader.ReadString('\n')
		switch {
		case err == io.EOF:
			fmt.Println("✅ Connection closed by server")
			return nil
		case err != nil:
			return fmt.Errorf("read error: %w", err)
		default:
			msg := line[:len(line)-1] // drop trailing newline
			if msg != "" {
				fmt.Printf("✅ Message: %s\n", string(msg))
			}
		}
	}
}

func main() {
	if len(os.Args) < 2 {
		fmt.Println("Usage: go run sse_client.go <sse-endpoint>")
		os.Exit(1)
	}
	url := os.Args[1]
	if err := streamSSE(url); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(2)
	}
}
```

**Explanation**

* `http.Get` returns an `io.Reader`.  
* SSE lines are newline‑terminated; we discard the final `\n`.  
* The loop runs forever until the server closes the connection (`EOF`) or an error occurs.

> **Run**:  

```bash
go run sse_client.go http://example.com/sse   # replace with your endpoint
```

