// multipart.ts --------------------------------------------------------------
import { IncomingMessage } from 'http';
import * as fs   from 'fs';

/**
 * Parse a raw HTTP request body that contains `multipart/form-data`.
 *
 * @param req – an `IncomingMessage` (e.g. the object returned by Node’s http/https server)
 * @returns  {fields: Record<string,string>, files: Array<{name:string; filename:string; data:Buffer}>}
 */
export function parseMultipart(req: IncomingMessage): {
    fields: Record<string, string>;
    files: Array<{
        name: string;
        filename?: string;   // optional – present when Content-Disposition has a filename
        data: Buffer;
    }>;
} {
  const boundary = req.headers['content-type']?.match(/boundary=(.*)/)?.[1] ?? '';
  if (!boundary) throw new Error('No multipart boundary found');

  let currentField: string | null = null;   // name of the field we are reading
  let currentFile?: {name: string, filename?: string, buffer: Buffer}; // building a file

  const fields: Record<string, string> = {};
  const files: Array<{
    name: string;
    filename?: string;
    data: Buffer;
  }> = [];

  req.on('data', (chunk) => {
    if (currentFile) {
      currentFile.buffer = Buffer.concat([currentFile.buffer, chunk]);
      // When we see the boundary line that ends with "--", finish this file.
      if (Buffer.isBuffer(chunk) && chunk.toString() === '\r\n--') {
        files.push(currentFile);
        currentFile = undefined;
      }
    } else {
      const line = chunk.toString();
      if (line.trim().startsWith('--')) {
        // End of a part – check whether it is the final boundary
        if (line.trim() === '--' + boundary) return; // ignore trailing --
        // Otherwise we have a new field name before the colon
        currentField = line.split(/\s*:\s*/)?.[0];
      } else if (currentField !== null && line.trim().startsWith('Content-Disposition')) {
        const dispMatch = /form-data; ?name="([^"]+)";? ?filename="?([^"]*)"?/.exec(line);
        if (dispMatch) {
          currentFile = { name: currentField!, filename: dispMatch[2] };
          fields[currentField!] = ''; // placeholder – will be overwritten later
        }
      } else if (currentField !== null && line.trim().length > 0) {
        // Simple text field value
        const val = line.trim();
        fields[currentField!] += `\r\n${val}`;
      }
    }
  });

  req.on('end', () => {
    // Final file finish marker
    if (currentFile) files.push(currentFile);
    // Trim trailing newlines from multi‑line field values
    for (const k in fields) fields[k] = fields[k].trim();
  });
  return { fields, files };
}

