import * as http from 'http';

function serve(req: http.IncomingMessage, res: http.ServerResponse) {
  if (req.url === '/upload' && req.method?.toLowerCase() === 'post') {
    const parsed = parseMultipart(req);
    // For demo purposes we just echo back the fields & files
    console.log('Fields:', JSON.stringify(parsed.fields, null, 2));
    console.log('Files:', JSON.stringify(parsed.files.map(f => ({
      name: f.name,
      filename: f.filename ?? '(no filename)',
      size: f.data.length,
    })), null, 2));

    // Respond with a simple acknowledgement
    res.writeHead(200, { 'Content-Type': 'text/plain' });
    res.end('Upload complete');
  } else {
    res.writeHead(405);
    res.end();
  }
}

