## 2️⃣ Python 3.x

```python
# multipart_parser.py -------------------------------------------------------
import io
from typing import Dict, List, Tuple

def parse_multipart(body: bytes) -> Tuple[Dict[str, str], List[Dict]]:
    """
    Parse `multipart/form-data` from raw request body.

    Returns:
        fields (dict): {field_name: value}
        files  (list): [{name: filename, filename: optional_filename, data: bytearray}]
    """
    boundary = None
    for line in body.splitlines():
        if not line.strip():          # empty line separates parts
            continue
        if '--' in line:
            # Last part ends with "--"
            if line.rstrip() == '--':
                break  # consume the final boundary marker later
            else:
                boundary = line.lstrip('--').split('=', 1)[1].strip()
    else:
        raise ValueError("No multipart boundary found")

    fields: Dict[str, str] = {}
    files: List[Dict] = []

    current_name: str | None = None
    current_file_buffer: io.BytesIO | bytearray | bytes = b''

    for line in body.splitlines():
        if not line.strip():          # empty line → part separator
            continue

        if '--' in line:
            # End of a part; check whether it is the final boundary.
            if line.rstrip() == '--' + boundary:
                break  # ignore trailing --
            else:
                current_name = None
                current_file_buffer = b''
        elif line.startswith('Content-Disposition'):
            disp_match = line.split(None, 1)[1].strip()
            # Example: form-data; name="profile"; filename="resume.pdf"
            parts = disp_match.split(';')
            for p in parts:
                if '=' not in p:
                    continue
                k, v = p.split('=', 1)
                k = k.strip().lower()
                v = v.strip('"').strip("'")
                if k == 'name':
                    current_name = v
        else:
            # Simple field value or file data line (e.g. "profile=example.txt")
            if current_name is not None:
                # If we see a plain string after the name, treat it as an assignment.
                fields[current_name] = line.strip()
            elif 'filename' in locals():
                # Append to file buffer
                current_file_buffer += bytes(line, 'utf-8')
    else:
        # After loop ends (when boundary reached) we still may have a pending file.
        if current_name and 'filename' in locals():
            files.append({
                "name": current_name,
                "filename": None if not current_file_buffer else None,
                "data": bytearray(current_file_buffer)
            })

    return fields, files


