@app.post("/upload")
async def upload(req: Request):
    # req.body() returns bytes; we assume the request already has Content-Type set.
    body = await req.body()
    fields, files = parse_multipart(body)

    # For demo purposes just echo back what was received
    print("Fields:", dict(fields))
    print("Files:", [
