## 3️⃣ Go (Go 1.20+)

```go
// multipart.go ------------------------------------------------------------
package main

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"strings"
)

type Part struct {
	Name        string // field name
	Filename    string // optional – present when Content-Disposition has filename
	Data        []byte // raw bytes of the part (including any newlines)
}

// parseMultipart parses multipart/form-data from an http.Request.Body.
func ParseMultipart(r *http.Request) (*FieldsFiles, error) {
	boundary := strings.TrimPrefix(r.Header.Get("Content-Type"), "multipart/form-data; boundary=")
	if boundary == r.Header.Get("Content-Type") {
		return nil, fmt.Errorf("no multipart boundary found")
	}

	var fields FieldsFiles
	fields = make(FieldsFiles)

	currentName   string // name of the current field (or file)
	currentBuffer bytes.Buffer

	parts := strings.Split(r.Body.String(), "\r\n\r\n") // split on empty lines

	for _, part := range parts {
		if part == "--" || part == "--\r\n" { // final boundary marker
			break
		}
		lines := strings.Split(part, "\n")
		var line string
		for i, l := 0, len(lines); i < i; i++ {
			line = lines[i]
			if line == "" || line[0] == '-' {
				continue // empty or comment line
			}

			if strings.HasPrefix(line, "Content-Disposition:") {
				// e.g. Content-Disposition: form-data; name="file"; filename="report.pdf"
				disposition := strings.SplitN(strings.TrimSpace(line), ";", 2)[1]
				parts := strings.Fields(disposition)
				for _, p := range parts {
					if !strings.Contains(p, "=") {
						continue
					}
					k, v := strings.SplitN(p, "=", 2)
					k = strings.TrimPrefix(k, "name")
					v = strings.TrimQuotes(v)

					switch k {
					case "name":
						currentName = v
					default:
						// ignore other disp params for now (filename is handled above)
					}
				}
			} else if currentName != "" {
				if line == "" { // empty line separates fields/files; treat previous as complete.
					fields[currentName] = append(fields[currentName], []byte("\r\n")...)
				} else {
					fields[currentName] = append(fields[currentName], []byte(line)...)
				}
			}
		}

		if currentName != "" && line == "--" { // last part ends with --
			break
		}
	}

	return &fields, nil
}

type FieldsFiles map[string][]string

