// Simple HTTP server demo (mirrors the Node example)

import (
	"fmt"
	"net/http"
)

func uploadHandler(w http.ResponseWriter, req *http.Request) {
	if req.Method != "POST" || req.Header.Get("Content-Type") == "" {
		http.Error(w, "Only POST with multipart/form-data accepted", 405)
		return
	}

	req.ParseMultipartForm(10 << 20) // limit payload size (10 MiB)

	fields, _ := ParseMultipart(req.Body) // already set by ParseMultipartForm internally

	fmt.Fprintf(w, "Fields: %v\n", fields)
	fmt.Fprint(w, "\nFiles:\n")
	for name, parts := range fields {
		for _, v := range parts {
			fmt.Fprintf(w, "- %s (%d bytes)\n", v, len([]byte(v)))
		}
	}

	req.Body.Close() // consume body after reading
}

func main() {
	http.HandleFunc("/upload", uploadHandler)
	fmt.Println("Listening on :8000")
	if err := http.ListenAndServe(":8000", nil); err != nil {
		panic(err)
	}
}
```

**Explanation**

* `ParseMultipartForm` (standard library) already splits the request into parts and stores them in memory. We wrap that with a custom parser (`ParseMultipart`) to illustrate line‑by‑line logic.
* The function returns a map where each key is a field name; values are slices of strings for text fields, or you could store `[]byte` if you need binary data (as shown).
* Files can be streamed directly from the request body using `req.MultipartForm.File["<fieldname>"]` – but here we demonstrate parsing manually.

