	cfg.defaults()

	if cfg.HealthCheck != "" && len(cfg.HealthCmd) > 0 {
		return "", fmt.Errorf("deploy: HealthCheck and HealthCmd are mutually exclusive")
	}

	cli, err := client.NewClientWithOpts(client.FromEnv, client.WithAPIVersionNegotiation())
	if err != nil {
		return "", fmt.Errorf("deploy: create docker client: %w", err)
	}
	defer cli.Close()

	// --- Pull ---
	reader, err := cli.ImagePull(ctx, cfg.Image, image.PullOptions{})
	if err != nil {
		return "", fmt.Errorf("deploy: pull image %s: %w", cfg.Image, err)
	}
	_, _ = io.Copy(io.Discard, reader)
	reader.Close()

	// --- Create ---
	portSet, portBindings, err := nat.ParsePortSpecs(toPortSpecs(cfg.Ports))
	if err != nil {
		return "", fmt.Errorf("deploy: parse port specs: %w", err)
	}
	resp, err := cli.ContainerCreate(ctx, &container.Config{
		Image: cfg.Image, Cmd: cfg.Cmd, Env: cfg.Env, ExposedPorts: portSet,
	}, &container.HostConfig{PortBindings: portBindings}, nil, nil, cfg.Name)
	if err != nil {
		return "", fmt.Errorf("deploy: create container: %w", err)
	}
	cid := resp.ID[:12]

	// --- Start ---
	if err := cli.ContainerStart(ctx, resp.ID, container.StartOptions{}); err != nil {
		return "", fmt.Errorf("deploy: start container %s: %w", cid, err)
	}

	// --- Wait for health ---
	if err := waitForHealth(ctx, cli, resp.ID, cfg); err != nil {
		if cfg.RemoveOnFailure {
			_ = cli.ContainerRemove(ctx, resp.ID, container.RemoveOptions{Force: true})
		}
		return "", err
	}
	return cid, nil
}
