  export interface DeployContainerOptions {
    image: string;
    name?: string;
    ports?: Record<string, number>;          // { "80/tcp": 8080 }
    env?: string[];                          // ["FOO=bar"]
    cmd?: string[];
    healthCheck?: string;                    // HTTP URL to poll for 200
    healthCmd?: string[];                    // exec-based health check
    pollIntervalMs?: number;                 // default 1000
    timeoutMs?: number;                      // default 60_000
    removeOnFailure?: boolean;               // default true
    dockerHost?: string;                     // default unix:///var/run/docker.sock
  }
  
  export async function deployContainer(opts: DeployContainerOptions): Promise<string> {
    const dockerHost = opts.dockerHost ?? "unix:///var/run/docker.sock";
    const pollIntervalMs = opts.pollIntervalMs ?? 1000;
    const timeoutMs = opts.timeoutMs ?? 60_000;
  
    // --- Pull ---
    await dockerRequest(dockerHost, "POST", "/images/create?fromImage=" + encodeURIComponent(opts.image));
  
    // --- Create ---
    const exposedPorts: Record<string, unknown> = {};
    const portBindings: Record<string, unknown> = {};
    for (const [containerPort, hostPort] of Object.entries(opts.ports ?? {})) {
      exposedPorts[containerPort] = {};
      portBindings[containerPort] = [{ HostPort: String(hostPort) }];
    }
    const create = await dockerRequest(dockerHost, "POST",
      "/containers/create" + (opts.name ? `?name=${encodeURIComponent(opts.name)}` : ""),
      JSON.stringify({
        Image: opts.image, Cmd: opts.cmd, Env: opts.env,
        ExposedPorts: exposedPorts,
        HostConfig: { PortBindings: portBindings },
      }));
    if (create.status < 200 || create.status >= 300) throw new DockerDeployError(create.status, create.body);
    const containerID = JSON.parse(create.body).Id;
    const cid = containerID.slice(0, 12);
  
    // --- Start ---
    const start = await dockerRequest(dockerHost, "POST", `/containers/${containerID}/start`);
    if (start.status < 200 || start.status >= 300) throw new DockerDeployError(start.status, start.body);
  
    // --- Wait for health ---
    await waitForHealth(dockerHost, containerID, { pollIntervalMs, timeoutMs, healthCheck: opts.healthCheck, healthCmd: opts.healthCmd });
    return cid;
  }
