// clone‑commit‑push.ts
import { Repository, Reference } from 'nodegit';

async function cloneAndPush(
  remoteUrl: string,
  localPath: string,
  commitMessage = 'Add initial commit',
): Promise<void> {
  // -------------------------------------------------
  // 1️⃣ Clone the repository (shallow optional)
  // -------------------------------------------------
  const repo = await Repository.clone(remoteUrl, localPath);
  console.log(`✅ Cloned into ${localPath}`);

  // -------------------------------------------------
  // 2️⃣ Open / create a branch & commit
  // -------------------------------------------------
  const headRef = await repo.getHead();
  let currentBranch: Reference | null = null;

  if (headRef?.name() === 'HEAD') {
    // HEAD points directly to master – we’ll work on it.
    currentBranch = headRef;
  } else {
    // Otherwise create a new branch called `initial-commit`.
    const branchName = 'initial-commit';
    await repo.createBranch(branchName, headRef!.target(), null);
    currentBranch = repo.getReference(`refs/heads/${branchName}`);
  }

  // -------------------------------------------------
  // 3️⃣ Create the commit
  // -------------------------------------------------
  const author = new Commit.Author('Your Name', 'you@example.com');
  await repo.createCommit(
    currentBranch!.name(),
    author,
    null,               // committer – same as author for demo
    commitMessage,
    null,               // tree (empty tree → just the commit)
    [],
  );

  console.log(`✅ Commit created (${commitMessage})`);

  // -------------------------------------------------
  // 4️⃣ Push to the remote (fast‑forward if possible)
  // -------------------------------------------------
  const remote = await repo.getRemote('origin');
  const pushOpts = new Repository.PushOptions();
  pushOpts.setVerify(false);   // don’t require GC on server side
  pushOpts.setForce(true);    // force‑push – only for demo

  try {
    const result = await remote.push([currentBranch!.name()], pushOpts);
    console.log(`✅ Pushed ${result.count} ref(s)`);
  } catch (err: any) {
    if (err instanceof Error && err.message?.includes('non-fast‑forward')) {
      console.warn(
        '⚠️ Non‑fast‑forward – you may need to pull/push manually.',
      );
    }
    throw err;
  }

  // -------------------------------------------------
  // Clean up
  // -------------------------------------------------
  await repo.close();
}

// -------------------------------------------------------------------
if (require.main === module) {
  // Usage: node clone-commit-push.ts https://github.com/user/repo.git ./repo
  const [,, remoteUrl, localPath] = process.argv;
  if (!remoteUrl || !localPath) {
    console.error('Usage: node clone-commit-push.ts <remote-url> <local-path>');
    process.exit(1);
  }
  cloneAndPush(remoteUrl, localPath).catch(console.error);
}
```

### How it works
| Step | What happens |
|------|--------------|
| **Clone** | `Repository.clone()` creates a fresh repo at the given path. |
| **Branch / Commit** | We either reuse `HEAD` (master) or create a new branch (`initial-commit`). A single commit is created with an empty tree – you can replace it with real staged files if desired. |
| **Push** | The new commit is pushed back to the same remote via `push()`. If the push would cause a non‑fast‑forward, we warn and continue (useful for CI pipelines). |

