    local_path: str = ".",
    commit_msg: str = "Add initial commit",
) -> None:
    """
    Clone a repo, create/modify a single commit and push it back.
    """

    # -------------------------------------------------
    # 1️⃣ Clone (shallow=True by default)
    # -------------------------------------------------
    print(f"🔧 Cloning {remote_url} → {local_path}")
    Repo.clone_from(remote_url, local_path, progress=None)   # no progress bar
    print("✅ Repository cloned")

    repo = Repo(local_path)

    # -------------------------------------------------
    # 2️⃣ Open / create branch & commit
    # -------------------------------------------------
    head_ref = repo.head

    if str(head_ref) == "HEAD":
        current_branch = head_ref
    else:
        new_branch_name = "initial-commit"
        print(f"🆕 Creating new branch {new_branch_name} from {head_ref.name}")
        repo.create_head(new_branch_name, head_ref.target)
        current_branch = repo.head.reference

    # -------------------------------------------------
    # 3️⃣ Create the commit
    # -------------------------------------------------
    author = git.Author("Your Name", "you@example.com")
    new_commit = repo.commit(
        message=commit_msg,
        author=author,
        committer=author,   # same as author for demo
    )
    print(f"✅ Commit created: {new_commit.hexsha}")

    # -------------------------------------------------
    # 4️⃣ Push back to the remote (fast‑forward only)
    # -------------------------------------------------
    origin = repo.remote(name="origin")
    push_opts = git.PushOptions()
    push_opts.force = True   # demo – remove if you need non‑ff handling
    print(f"🚀 Pushing {current_branch.name} …")
    try:
        origin.push([current_branch], opts=push_opts)
        print("✅ Push succeeded")
    except GitCommandError as exc:
        if "non-fast-forward" in str(exc):
            print(
                "⚠️ Non‑fast‑forward detected – you may need to pull/push manually."
            )
        raise

