// clone-commit-push/main.go
package main

import (
	"context"
	"fmt"
	"io/ioutil"
	"log"

	git "github.com/libgit2/git2go/v33"
	"github.com/libgit2/git2go/v33/index"
)

func cloneAndPush(remoteURL, localPath string) error {
	repo, err := git.Clone(context.Background(), nil, remoteURL, localPath)
	if err != nil {
		return fmt.Errorf("clone: %w", err)
	}
	fmt.Printf("✅ Cloned into %s\n", localPath)

	workdir, _ := repo.Workdir()
	idx, err := index.New(workdir)
	if err != nil {
		return fmt.Errorf("create index: %w", err)
	}

	headRef, err := repo.Head()
	if err != nil {
		return fmt.Errorf("get HEAD ref: %w", err)
	}
	currentBranchName := headRef.Name().String()

	var currentBranch *git.Reference
	if strHead := str(headRef); strHead == "HEAD" {
		currentBranch = headRef
	} else {
		newBranch, err := repo.CreateBranch(currentBranchName+"-initial-commit",
			headRef.Target(), nil)
		if err != nil {
			return fmt.Errorf("create branch: %w", err)
		}
		currentBranch = newBranch
		fmt.Printf("🆕 Created branch %s from %s\n", currentBranch.Name().String(), headRef.Name())
	}

	auth := &git.Signature{
		Name:  "Your Name",
	 Email: "you@example.com",
	 When:  git.TimeNow(),
	}
	tree, err := idx.WriteTreeTo(repo)
	if err != nil {
		return fmt.Errorf("write tree: %w", err)
	}
	parents := []*git.Commit{}
	message := "Add initial commit"
	newCommit, err := repo.CreateCommit(
		currentBranch.Name(), auth, auth,
		message, tree, parents,
