      // HEAD points directly to master – we’ll work on it.
      currentBranch = headRef;
    } else {
      // Otherwise create a new branch called `initial-commit`.
      const branchName = 'initial-commit';
      await repo.createBranch(branchName, headRef!.target(), null);
      currentBranch = repo.getReference(`refs/heads/${branchName}`);
    }
  
