## 1️⃣ TypeScript (Express)

```ts
// server.ts
import express, { Request, Response } from 'express';
import * as qs from 'querystring';

const app = express();
app.use(express.json());          // parse JSON request bodies
app.use(express.urlencoded({ extended: true })); // parse URL‑encoded bodies

/**
 * Returns the best matching MIME type based on Accept header.
 *
 * @param acceptHeader – string like "application/json;q=0.9, text/xml;q=0.8"
 * @returns preferred MIME type or undefined if none matches
 */
function pickBestType(acceptHeader?: string): string | undefined {
  // If no Accept header → return the first one (usually JSON)
  if (!acceptHeader) return 'application/json';

  const parts = acceptHeader.split(',');
  let best: {type: string, q: number} | null = null;

  for (const part of parts) {
    const [rawType, rawQ] = part.trim().split(/;\s*q=/);
    const type = rawType;
    // Default quality factor is 1.0 if not specified
    let q = rawQ ? parseFloat(rawQ) : 1.0;

    // If we already have a better match keep it (higher q wins)
    if (!best || q > best.q) {
      best = { type, q };
    }
  }

  return best?.type ?? 'text/plain';
}

/**
 * Simple handler that returns JSON by default.
 */
app.get('/data', (_req: Request, res: Response) => {
  const contentType = pickBestType(res.getHeader('Accept'));
  if (contentType === 'application/json') {
    // You could also read from a DB / compute something here
    res.json({ message: 'Hello – JSON response!' });
  } else {
    // Fallback to plain‑text when no matching type is requested
    res.type(contentType);
    res.send('Fallback to text/plain');
  }
});

/**
 * Optional endpoint that forces XML (demo only)
 */
app.get('/data/xml', (_req: Request, res: Response) => {
  const contentType = 'application/xml';
  // Force the Accept header for demo purposes
  res.setHeader('Accept', 'text/xml;q=1.0');
  res.type(contentType);
  res.send('<?xml version="1.0"?><root>Hello – XML!</root>');
});

const PORT = process.env.PORT ?? 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});
```

**How it works**

* `pickBestType` parses the header (`q=` values are used as quality scores).  
* The `/data` endpoint first checks the client’s Accept header; if none matches, it falls back to plain‑text.  
* You can add more routes (e.g., XML) and force a specific `Accept` header for testing.

