## 2️⃣ Python (Flask)

```python
# server.py
from flask import Flask, request, Response

app = Flask(__name__)

def pick_best_type(accept_header: str | None) -> str:
    """
    Returns the best MIME type based on Accept header.
    If no match is found, returns 'text/plain'.
    """
    if not accept_header:
        return 'text/plain'

    # Split by comma and then split each part into type & optional q= factor
    parts = [part.strip() for part in accept_header.split(',')]
    best: dict[str, float] | None = None

    for part in parts:
        # Example: "application/json;q=0.9"
        if ';' not in part:
            continue  # ignore malformed entries
        type_, q_part = part.split(';', 1)
        typ = type_.strip()
        try:
            q = float(q_part.split('q=', 1)[1])
        except (IndexError, ValueError):
            q = 1.0   # no explicit quality → treat as highest priority

        if best is None or q > best['q']:
            best = {'type': typ, 'q': q}

    return best['type'] if best else 'text/plain'

@app.route('/data')
def data():
    accept = request.headers.get('Accept')
    preferred_type = pick_best_type(accept)

    # Force the response header to match chosen type
    resp = Response(content=preferred_type)
    resp.content_type = preferred_type

    if preferred_type == 'application/json':
        resp.json = {'message': 'Hello – JSON response!'}
    elif preferred_type == 'text/xml':
        resp.data = '<?xml version="1.0"?><root>Hello – XML!</root>'
    else:
        # Fallback to plain text
        resp.data = 'Fallback to text/plain'

    return resp

if __name__ == '__main__':
    app.run(port=5000, debug=True)
```

**Explanation**

* `pick_best_type` mirrors the same logic as in TypeScript.  
* The `/data` endpoint reads `Accept`, picks a type, sets the appropriate `Content-Type` header and body, then returns it.

