// ------------------------------------------------------------
// config.ts – single helper that merges env vars, JSON config,
// and command‑line flags.
// ------------------------------------------------------------

import * as fs from "fs";
import * as path from "path";

/**
 * Simple interface for the configuration we expect.
 */
export type Config = {
  /** API key used by service A */
  apiKey?: string;
  /** Port number to listen on (default: 3000) */
  port?: number;
  /** Timeout in seconds (optional) */
  timeout?: number;
};

/**
 * Load a JSON config file. Throws if the file is missing or invalid.
 */
function loadJsonConfig(filePath: string): Config {
  try {
    const raw = fs.readFileSync(filePath, "utf8");
    return JSON.parse(raw);
  } catch (err) {
    throw new Error(`Failed to parse ${filePath}: ${(err as any).message}`);
  }
}

/**
 * Helper that reads an environment variable or returns a default.
 */
function envOrDefault(key: string, defaultValue?: unknown): unknown {
  const value = process.env[key];
  return value !== undefined ? value : defaultValue;
}

/**
 * CLI flag parser – expects flags in the form --key=value.
 *
 * The function builds a Config object from all recognized flags,
 * preferring values that are already present (so later calls win).
 */
function parseCliFlags(): Config {
  const cfg: Config = {};

  // Example: process.argv looks like ["node", "app.js","--apiKey","myKey"]
  for (let i = 2; i < process.argv.length; i += 2) {
    const key = process.argv[i];
    let value = process.argv[i + 1];

    // Simple conversion – you can extend this to support booleans, ints, etc.
    switch (key.toLowerCase()) {
      case "--api-key":
        cfg.apiKey = value;
        break;
      case "--port":
        if (!isNaN(Number(value))) cfg.port = Number(value);
        break;
      case "--timeout":
        if (!isNaN(Number(value))) cfg.timeout = Number(value);
        break;
      // Add more cases as needed
    }
  }

  return cfg;
}

/**
 * Main helper – merges env vars → config file → CLI flags.
 *
 * @param configFile Path to the JSON/YAML/INI config file (relative or absolute)
 */
export function getMergedConfig(configFile: string): Config {
  // Start with defaults that we will later override
  let cfg = parseCliFlags();

  // ---- Environment variables -------------------------------------------------
  // Example env vars names – adjust to your naming convention.
  cfg.apiKey ??= envOrDefault("API_KEY");
  cfg.port ??= Number(envOrDefault("PORT", "3000"));
  cfg.timeout ??= Number(envOrDefault("TIMEOUT"));

  // ---- Config file (JSON) ----------------------------------------------------
  try {
    const raw = fs.readFileSync(configFile, "utf8");
    const jsonCfg: Config = JSON.parse(raw);
    // Precedence: CLI > Env > File → merge shallowly
    Object.assign(cfg, jsonCfg);
  } catch (e) {
    console.warn(`[WARN] Could not load config file ${configFile}: ${(e as Error).message}`);
  }

  return cfg;
}

