#!/usr/bin/env python3
"""
config.py – single helper that merges environment variables,
a JSON/YAML config file, and command‑line flags (argparse).
"""

import os
import json
from pathlib import Path
import argparse

def env_or_default(key: str, default=None):
    """Return value from os.environ or a supplied default."""
    return os.getenv(key, default)

def parse_cli_flags():
    parser = argparse.ArgumentParser()
    # Add flags here – the names map directly to config keys.
    parser.add_argument("--api-key", type=str)
    parser.add_argument("--port", type=int, default=3000)
    parser.add_argument("--timeout", type=float)
    args = parser.parse_args()
    cfg: dict = {}
    for k, v in vars(args).items():
        if v is not None:
            cfg[k] = v
    return cfg

def load_json_config(file_path: Path):
    """Load a JSON file; raise on error."""
    try:
        raw = file_path.read_text(encoding="utf-8")
        return json.loads(raw)
    except Exception as exc:
        raise RuntimeError(f"Failed to parse {file_path}: {exc}") from exc

def merge_configs(cli_cfg: dict, config_file: Path):
    """
    Merge three sources with clear precedence:
      CLI flags → env vars (fallback) → JSON/YAML file.
    Returns a single dictionary containing all values.
    """
    cfg = cli_cfg.copy()                     # start with CLI
    # 1️⃣ Environment variables – higher than file but lower than flags
    for key, default in [("API_KEY", None), ("PORT", 3000), ("TIMEOUT", None)]:
        if key not in cfg:                   # only add missing keys from env
            cfg[key] = env_or_default(key, default)

    # 2️⃣ Config file – lowest priority among the three sources we control here
    try:
        json_cfg = load_json_config(config_file)
        # shallow merge; CLI/Env already override if present.
        cfg.update(json_cfg)
    except Exception as exc:
        print(f"[WARN] Could not load config file {config_file}: {exc}", file=sys.stderr)

    return cfg

# ----------------------------------------------------------------------
if __name__ == "__main__":
    cli = parse_cli_flags()
    # Example: merge with a JSON config located next to the script.
    import sys
    merged = merge_configs(cli, Path(__file__).with_suffix(".json"))
    print("Merged configuration:", json.dumps(merged, indent=2))
