func envOrDefault(key, fallback string) string {
	if val := os.Getenv(key); val != "" {
		return val
	}
	return fallback
}

// -------------------------------------------------------------------
// Parse command‑line flags (CLI).
// -------------------------------------------------------------------
var cliCfg Config

func parseFlags() {
	flag.StringVar(&cliCfg.APIKey, "api-key", "", "API key")
	flag.IntVar(&cliCfg.Port, "port", 3000, "Listening port")
	flag.Float64Var(&cliCfg.Timeout, "timeout", 30.0, "Timeout in seconds")

	// No default for --port and --timeout; they are required.
	if err := flag.Parse(); err != nil {
		panic(err)
	}
}

// -------------------------------------------------------------------
// Load JSON config file (supports both .json or .yaml via extension).
// -------------------------------------------------------------------
func loadJSONConfig(path string) (*Config, error) {
	data, err := ioutil.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", path, err)
	}
	var cfg Config
	if err := mapTo(&cfg, data); err != nil {
		return nil, fmt.Errorf("parse JSON: %w", err)
	}
	return &cfg, nil
}

// -------------------------------------------------------------------
// Simple map unmarshal helper (reflect‑free for this tiny example).
