// lru-cache-redis.ts ---------------------------------------------------------
import { Redis } from "ioredis";

export interface LRUCacheOptions {
  /** Maximum number of entries before eviction */
  capacity: number;
}

/**
 * Simple LRU cache backed by Redis.
 *
 * - `set(key, value)` stores the pair and updates recency order.
 * - `get(key)` returns the stored value or undefined if miss.
 * - Eviction follows an LRU policy; when a new entry is inserted
 *   while capacity is exceeded, the least‑recently used key/value
 *   is removed from Redis (and internally).
 *
 * All operations are async and use Redis `SETEX`/`MGET/MSET`
 * to keep latency low.
 */
export class LRUCacheRedis<V> {
  private readonly client: Redis;
  private readonly capacity: number;

  // internal map that mirrors the order of keys from most‑recent → least‑recent
  private readonly orderedKeys: string[];

  constructor(opts: LRUCacheOptions) {
    this.client = new Redis();
    this.capacity = opts.capacity!;
    this.orderedKeys = []; // empty initially

    // fire a “ready” event only once (optional)
    this.client.on("connect", () => console.log("[LRU‑Redis] connected"));
  }

  /** Public API – get value for key */
  async get(key: string): Promise<V | undefined> {
    const raw = await this.client.get(key);
    if (!raw) return undefined;
    // Redis returns a Buffer; convert to V (or leave as Buffer)
    return typeof raw === "string" ? JSON.parse(raw) : raw;
  }

  /** Public API – set key/value */
  async set(key: string, value: V): Promise<void> {
    const serialized = typeof value === "object"
      ? JSON.stringify(value)
      : (value as unknown as string);

    // Push the new key to the front of orderedKeys
    this.orderedKeys.unshift(key);
    await this.client.set(key, serialized);   // store in Redis

    // Evict oldest entries if we exceed capacity
    while (this.orderedKeys.length > this.capacity) {
      const evictedKey = this.orderedKeys.pop()!;
      await this.client.del(evictedKey);
    }
  }

  /** Close the connection when done */
  async close(): Promise<void> {
    await this.client.quit();
  }
}
```

