```python
# lru_cache_redis.py ---------------------------------------------------------
import json
from typing import Any, Optional, Dict

import aioredis   # pip install aioredis

class LRUCacheRedis:
    """
    Simple LRU cache backed by Redis.
    Capacity is enforced via an internal ordered list that mirrors the MRU/LRU order.
    All public methods are async.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.redis = None
        self._ordered_keys: Optional[Dict[str, Any]] = {}  # placeholder for ordering logic

    async def _connect(self) -> None:
        self.redis = await aioredis.from_url(
            "redis://localhost", decode_responses=True
        )

    async def close(self) -> None:
        if self.redis:
            await self.redis.close()

    async def get(self, key: str):
        val = await self.redis.get(key)
        return json.loads(val) if val is not None else None

    async def set(self, key: str, value: Any) -> None:
        serialized = json.dumps(value)

        # Update internal ordering (MRU first)
        if hasattr(self, "_ordered_keys"):
            self._ordered_keys.move_to_end(key, last=True)
        else:
            self._ordered_keys = {key: True}
            await self.redis.set(key, serialized)  # initial insert

        # Evict oldest entries
        while len(self._ordered_keys) > self.capacity:
            evicted_key = next(iter(self._ordered_keys))
            await self.redis.delete(evicted_key)
            del self._ordered_keys[evicted_key]

    async def __aenter__(self):
        await self._connect()
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        await self.close()

# Example usage ---------------------------------------------------------------
if __name__ == "__main__":
    import asyncio
    cache = LRUCacheRedis(capacity=3)

    # Run a few operations concurrently (optional)
    loop = asyncio.get_running_loop()
    tasks = [
        loop.create_task(cache.set(f"k{i}", i * 10)),
        loop.create_task(cache.get(f"k0")),
        loop.create_task(cache.set(f"k4", 40)),   # should evict k1
        loop.create_task(cache.get(f"k2"))
    ]
    await asyncio.gather(*tasks)

    print(await cache.get("k0"))   # still present
    print(await cache.get("k1"))   # gone (evicted)
    await cache.close()
```

*Key points*

- `aioredis.from_url` creates a pooled connection.
- The ordering is kept in a plain Python dict (`_ordered_keys`) that mimics an LRU list; you could replace it with `collections.OrderedDict` if you prefer not to keep state inside the class.
