## 3️⃣ Go

```go
// lru_cache_redis.go ---------------------------------------------------------
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/go-redis/redis/v8" // v8 is the current stable version
)

type LRUCacheRedis struct {
	capacity int
	client   *redis.Client
	order    map[string]bool // simple bool map used as FIFO queue (capacity‑based)
}

// NewLRUCacheRedis creates a new LRU cache backed by Redis.
func NewLRUCacheRedis(capacity int, addr string) *LRUCacheRedis {
	return &LRUCacheRedis{
		capacity: capacity,
		client:   redis.NewClient(&redis.Options{Addr: addr}),
		order:    make(map[string]bool),
	}
}

// Close cleanly shuts down the Redis connection.
func (c *LRUCacheRedis) Close(ctx context.Context) error {
	return c.client.Close()
}

// Get returns a value for key or nil if miss; JSON‑encoded values are decoded.
func (c *LRUCacheRedis) Get(key string) (*string, error) {
	valStr, err := c.client.Get(context.Background(), key).Result()
	if err == redis.Nil {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("redis get: %w", err)
	}
	var v interface{}
	if err = json.Unmarshal([]byte(valStr), &v); err != nil {
		return nil, fmt.Errorf("unmarshal value: %w", err)
	}
	return &valStr, nil
}

// Set stores a key/value pair; if capacity is exceeded the least‑recently used entry is evicted.
func (c *LRUCacheRedis) Set(key string, value interface{}) error {
	serialized, err := json.Marshal(value)
	if err != nil {
		return fmt.Errorf("marshal: %w", err)
	}

	// Update internal LRU order – we treat the map as a set of booleans.
	c.order[key] = true

	// Store in Redis
	if err = c.client.Set(context.Background(), key, serialized, 0).Err(); err != nil {
		return fmt.Errorf("redis set: %w", err)
	}

	// Evict oldest entries if we exceed capacity
	for k := range c.order {
		if len(c.order) > c.capacity {
			delete(c.order, k)
			if _, err = c.client.Del(context.Background(), k).Result(); err != nil {
				return fmt.Errorf("redis del: %w", err)
			}
		} else {
			break
		}
	}

	return nil
}

// Example main (run with `go run`):
/*
func main() {
	ctx := context.Background()
	cache := NewLRUCacheRedis(3, "localhost:6379")
	if err := cache.Set("a", 1); err != nil { log.Fatal(err) }
	if err := cache.Set("b", 2); err != nil { log.Fatal(err) }
	if err := cache.Set("c", 3); err != nil { log.Fatal(err) }

	// Access a few keys to build LRU order
	fmt.Println(cache.Get("a")) // => ("a", nil)
	fmt.Println(cache.Get("b")) // => ("b", nil)

	if err := cache.Set("d", 4); err != nil { log.Fatal(err) } // evicts "b"
