import { createClient, RedisClientType } from "redis";

export class DistributedCounter {
  private readonly client: RedisClientType;
  private readonly key: string;

  constructor(client: RedisClientType, key = "counter:default") {
    this.client = client;
    this.key = key;
  }

  async increment(by = 1): Promise<number> {
    return this.client.incrBy(this.key, by);
  }

  async decrement(by = 1): Promise<number> {
    return this.client.decrBy(this.key, by);
  }

  async get(): Promise<number> {
    const value = await this.client.get(this.key);
    return value === null ? 0 : Number(value);
  }

  async reset(): Promise<void> {
    await this.client.set(this.key, "0");
  }

  async delete(): Promise<void> {
    await this.client.del(this.key);
  }
}
