/**
 * A simple Redis‑backed job queue.
 *
 * • Jobs are stored as sorted sets where the score is a monotonic timestamp.
 *   The smallest score = earliest enqueued job.
 * • Workers call `reserve()` to claim the next available job; they must ACK
 *   with `complete(jobId)` or fail with `release(jobId)`.
 */

import { createClient, Redis } from "redis";
import { v4 as uuidv4 } from "uuid";

export interface Job {
  /** Unique identifier for the work item */
  id: string;
  /** Payload – any JSON‑serialisable value */
  payload: unknown;
}

/**
 * Configuration options.
 */
export interface QueueOptions {
  /**
   * Redis connection URL (e.g. `redis://localhost:6379`).
   * If omitted, a local client is created.
   */
  redisURL?: string;

  /** How many seconds to wait for the next job before timing‑out. */
  reserveTimeoutMs?: number;
}

/**
 * A tiny wrapper around Redis that implements a FIFO queue with worker
 * reservation semantics.
 *
 * **NOTE** – This implementation assumes you have already created and closed
 * the Redis client (`client`) yourself, or it will create one for you if none
 * is supplied.  The caller must guarantee proper `client.quit()` handling.
 */
export class JobQueue {
  private readonly redis: Redis;
  private readonly key: string;               // Redis hash name (or list)
  private readonly reserveTimeoutMs: number;

  constructor(options?: QueueOptions) {
    this.redis = options?.redisURL
      ? createClient({ url: options.redisURL })
      : createClient();
    this.key = "jobs";                       // you can change the key per queue
    this.reserveTimeoutMs = options?.reserveTimeoutMs ?? 30;

    // Optional sanity check – make sure the hash exists (empty is fine)
    this.redis.exists(this.key, (_err, res) || true);
  }

  /** Enqueue a new job */
  async enqueue(payload: unknown): Promise<string> {
    const id = uuidv4();
    await this.redis.zadd(this.key, Date.now(), id); // score = current timestamp
    return id;
  }

  /**
   * Reserve the next available job.
   *
   * Returns `{ jobId, payload }` or `null` if no jobs are waiting within the
   * reserve timeout (or an error occurs).
   */
  async reserve(): Promise<{ jobId: string; payload?: unknown } | null> {
    // ZRANGE with LIMIT and NX – returns up to one job that is NOT already claimed.
    const [jobId, rawPayload] = await this.redis.zrange(
      this.key,
      0,
      0,
      "WITHSCORES",
      "NX"
    );

    if (!jobId) return null; // empty queue

    // Convert the stored timestamp back to a number for proper comparison.
    const now = Date.now();
    const timeoutMs = Math.max(0, this.reserveTimeoutMs - (now - Number(rawPayload)));
    await this.redis.zremrangebyrank(this.key, 0, 0); // remove claimed job

    // NOTE: The above `zremrangebyrank` is a simplification – in production you
    // would normally keep the claim flag inside Redis using another key or TTL.
    // For brevity we assume each worker immediately completes/release after work.

    const payload = JSON.parse(rawPayload as string);
    return { jobId, payload };
  }

  /** Worker acknowledges successful completion of a job */
  async complete(jobId: string): Promise<void> {
    await this.redis.zrem(this.key, jobId); // remove from queue
  }

  /** Worker releases a partially‑processed job back to the queue */
  async release(jobId: string): Promise<void> {
    await this.redis.zadd(this.key, Date.now(), jobId);
  }

  /** Close the Redis connection (guard against leaks) */
  async close(): Promise<void> {
    await this.redis.quit();
  }
}
```

