import { JobQueue } from "./JobQueue";

// Create a queue that will time‑out after 15 seconds if nothing claims a job.
const q = new JobQueue({ reserveTimeoutMs: 15000 });

(async () => {
  // Producer side – push work items (could be called by many processes)
  const jobId1 = await q.enqueue({ type: "process", data: { id: 42 } });
  const jobId2 = await q.enqueue({ type: "report",   data: { period: "last‑week" } });

  // Consumer side – each worker reserves a job, does work, then completes.
  (async () => {
    while (true) {
      const claim = await q.reserve();
      if (!claim) break;               // no more jobs right now
      const { jobId, payload } = claim;

      console.log(`Worker got ${jobId} →`, payload);

      /* ---- Simulate work --------------------------------------------------- */
      await new Promise(r => setTimeout(r, Math.random() * 2000)); // random delay

      await q.complete(jobId);          // ACK success
    }
  })();

})();
