## 2️⃣ Python (asyncio)

```python
# python/job_queue.py
import asyncio
import json
from typing import Any, Dict, Optional, Tuple

try:
    import aioredis   # pip install aioredis[socks]
except ImportError:
    raise RuntimeError("Install aioredis to use the Redis backend.")

class JobQueue:
    """
    Simple FIFO job queue backed by a Redis sorted set.
    
    * `id` is a unique identifier (UUID).
    * The score = current Unix timestamp (seconds since epoch) so that
      ZRANGE returns jobs in insertion order.
    """

    def __init__(
        self,
        redis_url: Optional[str] = None,
        reserve_timeout_ms: int = 15000,   # default timeout like TS version
    ):
        self.redis_url = redis_url or "redis://localhost:6379"
        self.reserve_timeout_ms = reserve_timeout_ms
        self.key = b"jobs"                 # Redis keys are bytes

        self._client: Optional[aioredis.Redis] = None
        self._closed = False

    async def _connect(self):
        if not self._client:
            self._client = await aioredis.from_url(
                self.redis_url, decode_responses=False
            )
        return self._client

    async def close(self) -> None:
        """Gracefully shut down the connection."""
        if self._client and not self._closed:
            await self._client.close()
            self._client = None
            self._closed = True

    async def enqueue(self, payload: Any) -> str:
        """
        Add a new job to the queue.
        
        Returns the generated UUID (as string).
        """
        import uuid

        id_ = str(uuid.uuid4())
        client = await self._connect()
        # Store `id` with current timestamp as score
        ts = int(asyncio.to_thread(lambda: asyncio.get_event_loop().time()))
        await client.zadd(self.key, {id_: ts})
        return id_

    async def reserve(self) -> Optional[Dict[str, Any]]:
        """
        Claim the next job.
        
        Returns a dict like {"jobId": "...", "payload": ...} or None if
        nothing is waiting within `reserve_timeout_ms`.
        """
        client = await self._connect()
        # ZRANGE with NX → returns up to one unclaimed job, otherwise empty list.
        ids = await client.zrange(self.key, 0, 0, "WITHSCORES", NX=True)

        if not ids:
            return None                     # queue empty

        jobId_bytes, raw_ts = ids[0]
        ts = int(raw_ts)                    # score is integer seconds
        now = int(asyncio.to_thread(lambda: asyncio.get_event_loop().time()))

        timeout_ms = self.reserve_timeout_ms - (now - ts)
        if timeout_ms <= 0:
            return None

        # Remove the job from Redis – this atomically marks it as claimed.
        await client.zrem(self.key, jobId_bytes)

        payload = json.loads(await client.get(jobId_bytes))
        return {"jobId": str(jobId_bytes), "payload": payload}

    async def complete(self, jobId: str) -> None:
        """Worker acknowledges successful job completion."""
        client = await self._connect()
        await client.zrem(self.key, jobId.encode())

    async def release(self, jobId: str) -> None:
        """
        Worker releases a partially‑processed job back to the queue.
        
        The job will be re‑available on the next reservation attempt.
        """
        client = await self._connect()
        ts = int(asyncio.to_thread(lambda: asyncio.get_event_loop().time()))
        await client.zadd(self.key, {jobId.encode(): ts})

# --------------------------------------------------------------------
# Example usage (same pattern as TS version)

async def producer(q: JobQueue):
    async with q:
        # In practice you’d loop over many items; here we enqueue a few.
        for i in range(3):
            await q.enqueue({"type": "process", "data": {"id": i}})
            print(f"Enqueued job {i}")

async def worker(q: JobQueue, name: str):
    async with q:
        while True:
            claim = await q.reserve()
            if not claim:
                # No jobs right now – sleep a bit before retrying.
                await asyncio.sleep(0.5)
                continue

            print(f"{name} got {claim['jobId']} → {claim['payload']}")
            # Simulate work
            import time, random
            await asyncio.sleep(random.uniform(0.2, 1))
            await q.complete(claim["jobId"])

if __name__ == "__main__":
    queue = JobQueue()
    async with queue:
        prod_task = asyncio.create_task(producer(queue))
        worker_tasks = [asyncio.create_task(worker(queue, f"W{i}")) for i in range(2)]
        await asyncio.gather(prod_task, *worker_tasks)
```

*Key points*

| Feature | Implementation |
|---------|----------------|
| **FIFO ordering** | Sorted set (`ZADD` → timestamp as score) |
| **Reservation** | `ZRANGE … WITHSCORES NX` (claims one job) |
| **Completion / Release** | `ZREM` to remove, or `ZADD` with same timestamp to re‑insert |
| **Timeout handling** | Compute remaining time after fetching the claim and compare against `reserve_timeout_ms`. |

