// go/jobs.go
package jobs

import (
	"context"
	"encoding/json"
	"fmt"
	"math/rand"
	"time"

	"github.com/go-redis/redis/v8" // v8 is the official Redis client for Go
)

// Job represents a work item stored in Redis.
type Job struct {
	ID      string    `json:"id"`
	Payload interface{} `json:"payload"`
}

// QueueOptions mirrors the config used in the TS version (timeout only).
type QueueOptions struct {
	RedisURL   string // e.g. "redis://localhost:6379"
	TimeoutMs  int64  // seconds timeout for reserve
}

// JobQueue implements a FIFO queue backed by Redis sorted sets.
type JobQueue struct {
	client      *redis.Client
	key         string          // name of the Redis key (sorted set)
	timeoutSecs int64           // derived from options.TimeoutMs
	cancelFunc  context.CancelFunc
	ctx         context.Context
	closed      bool
}

// NewJobQueue creates a new queue.
func NewJobQueue(opts *QueueOptions) (*JobQueue, error) {
	client := redis.NewClient(&redis.Options{
		URL: opts.RedisURL,
	})
	if err := client.Ping(context.Background()).Err(); err != nil {
		return nil, fmt.Errorf("failed to ping Redis: %w", err)
	}
	timeoutSecs := int64(opts.TimeoutMs / 1000) // ms → sec
	return &JobQueue{
		client:      client,
		key:         "jobs",
		timeoutSecs: timeoutSecs,
		ctx:         context.Background(),
	}, nil
}

// Close cleanly shuts down the connection.
func (q *JobQueue) Close() error {
	if q.closed {
		return nil // already closed
	}
	q.closed = true
	return q.client.Close()
}

// enqueue adds a new job to Redis. Returns its UUID string.
func (q *JobQueue) Enqueue(payload interface{}) (string, error) {
	id := fmt.Sprintf("%s-%d", "job-", rand.Int63())
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	_, err := q.client.ZAdd(q.ctx, q.key,
		&redis.Z{Score: float64(time.Now().Unix()), Member: id},
	).Result()
	if err != nil {
		return "", fmt.Errorf("zadd failed: %w", err)
	}
	return id, nil
}

// reserve atomically claims the next unclaimed job.
func (q *JobQueue) Reserve() (*Job, error) {
	ctx := context.Background()
	start := time.Now()

	for !q.closed {
		var jobIdBytes []byte
		err := q.client.Watch(ctx,
			func(tx *redis.Tx) error {
				// ZRANGE with NX → returns up to one unclaimed job.
				members, err := tx.ZRangeByScoreWithScores(
					ctx, q.key, &redis.ZRangeBy{
						Min: "-inf", Max: "+inf",
						Offset: 0,
						Limit: 1,
					},
					&redis.ZOptions{WithScores: true, NX: true},
				).Result()
				if err != nil {
					return fmt.Errorf("zrangebyscore failed: %w", err)
				}
				if len(members) == 0 {
					return nil // empty queue
				}

				jobIdBytes = members[0].Member
				ts := members[0].Score
				now := time.Now().Unix()
				timeoutSecs := int64(q.timeoutSecs - now+now)
				if timeoutSecs <= 0 {
					return fmt.Errorf("reserve timed out")
				}

				// Remove the job atomically.
				tx.ZRemRangeByRank(ctx, q.key, 0, 0)

				// Get payload (stored as JSON string).
				payloadStr := string(members[0].Member)
				var payload interface{}
				if err := json.Unmarshal([]byte(payloadStr), &payload); err != nil {
					return fmt.Errorf("unmarshal payload: %w", err)
				}
				return tx.ZAdd(ctx, q.key,
					&redis.Z{Score: float64(now), Member: jobIdBytes},
				).Err()
			},
			func() error { return nil },
			func() error { return nil },
		)

		if err != nil {
			select {
			case <-ctx.Done():
				return nil, fmt.Errorf("watch cancelled: %w", ctx.Err())
			default:
				continue // retry
			}
		}

		jobId := string(jobIdBytes)
		payloadStr := string(members[0].Member) // same member as above (score is timestamp)
		var payload interface{}
		if err := json.Unmarshal([]byte(payloadStr), &payload); err != nil {
			return nil, fmt.Errorf("unmarshal payload: %w", err)
		}
		job := Job{ID: jobId, Payload: payload}

		tsSecs := int64(members[0].Score - time.Now().Unix())
		if tsSecs < 0 {
			panic("score should be >= current unix")
		}
		now = time.Unix(now, 0).Unix()
		timeoutMs := q.timeoutSecs*1000 - (now - now) // simplified; in real code you'd compare with the original timeout
		return &job, nil
	}

	return nil, fmt.Errorf("queue closed")
}

