## 1️⃣ TypeScript version

```ts
// semantic-search.ts ---------------------------------------------------------
import { Configuration, OpenAIApi } from "openai";

const openai = new OpenAIApi(
    // You can set OPENAI_API_KEY in your env instead of hard‑coding:
    new Configuration({ apiKey: process.env.OPENAI_API_KEY })
);

/**
 * Load documents into memory.
 *
 * In a real system you would read them from files, a DB, or an API.
 */
const DOCUMENTS = [
    { id: "1", title: "Introduction to TypeScript", content: `TypeScript is a superset of JavaScript...` },
    { id: "2", title: "Python Basics",        content: `Python is a high‑level programming language...` },
    { id: "3", title: "Node.js Performance",  content: `Node.js can be fast when you use worker threads...` },
];

/**
 * Compute an embedding for a single text using OpenAI's model.
 */
async function embedText(text: string): Promise<number[]> {
    const resp = await openai.create({
        model: "text-embedding-ada-curie",
        input: text,
    });
    // The response shape is { data: [{ embedding: [number, …] }] }
    return (resp.data?.data[0]?.embedding ?? []) as number[];
}

/**
 * Build the index – one object per document.
 */
const index = DOCUMENTS.map(doc => ({
    id: doc.id,
    title: doc.title,
    content: doc.content,
    embedding: await embedText(doc.content),
}));

/**
 * Simple linear similarity search (k‑nearest neighbours).
 *
 * @param query   The user’s free‑text question.
 * @param k       How many results to return.
 */
export async function semanticSearch(query: string, k = 5): Promise<Record<string, number[]>> {
    const qEmbed = await embedText(query);
    let bestMatches: { id: string; score: number }[] = [];

    // Linear scan – O(N) but works for demo purposes.
    index.forEach(doc => {
        const dotProd = doc.embedding.reduce((s, a, i) => s + a * qEmbed[i], 0);
        // Normalise by vector lengths (optional but improves ranking)
        const normDoc = Math.hypot(...doc.embedding);
        const normQ   = Math.hypot(...qEmbed);
        const score   = dotProd / (normDoc * normQ) ?? 0; // cosine similarity
        bestMatches.push({ id: doc.id, title: doc.title, score });
    });

    // Sort descending and keep top‑k
    bestMatches.sort((a, b) => b.score - a.score);
    const result = {};
    for (let i = 0; i < k && i < bestMatches.length; ++i) {
        result[bestMatches[i].id] = bestMatches[i].score;
    }
    return result;
}

/* -----------------------------------------------------------------------
   Example usage – you could call this from an HTTP handler, CLI script,
   or any other entry point.
----------------------------------------------------------------------- */
if (require.main === module) {
    const query = "What are the main differences between TypeScript and JavaScript?";
    semanticSearch(query).then(scores => {
        console.log("Top matches:");
        for (const [id, score] of Object.entries(scores)) {
            console.log(`  ${score.toFixed(4)} – ${DOCUMENTS.find(d => d.id === id)!.title}`);
        }
    });
}
