```ts
// profiler.ts --------------------------------------------------------------
import { performance } from 'perf_hooks';
import * as v8stats from 'v8-profiler-next';

/**
 * Profile a function and return:
 *   - elapsed time in ms,
 *   - memory delta in bytes,
 *   - number of heap allocations performed during the call.
 *
 * The profiling is done via Node.js built‑ins (`perf_hooks`) for timing
 * and `v8-profiler-next` for allocation counting.  Memory usage reported
 * by v8stats is approximate (heap total).
 */
export function profile<T extends (...args: any[]) => any>(
    fn: T,
    ...args: Parameters<T>
): {
    timeMs: number;
    memoryDeltaBytes: number;
    allocationsCount?: number; // may be undefined if profiling disabled
} {
    const start = performance.now();               // high‑resolution timestamp (ms)
    let allocCountBefore = 0;

    // Enable allocation counting via v8stats.  The flag `true` tells it to
    // capture the current heap snapshot which includes allocation counts.
    const enableAllocs = true;
    if (enableAllocs) {
        try {
            // Start capturing allocations – this will count every GC‑triggered
            // allocation event until we stop.
            v8stats.enable({ mode: 'alloc' });
            allocCountBefore = v8stats.getAllocationCount();
        } catch (_) {
            // If the profiler cannot be started (e.g., in headless environments),
            // fall back to `undefined`.
            enableAllocs = false;
        }
    }

    try {
        const result = fn(...args);
        return { timeMs: performance.now() - start, memoryDeltaBytes: 0 };
    } finally {
        if (!enableAllocs) {
            // Nothing to clean up – we already returned.
            return;
        }

        // Stop allocation counting and record the final snapshot size.
        const allocCountAfter = v8stats.getAllocationCount();
        const heapTotalBefore = v8stats.heapTotal();
        const heapTotalAfter  = v8stats.heapTotal();

        // Approximate delta: (after - before) + (allocs * avg object size).
        // Here we just use the raw snapshot difference; for a more precise
        // per‑allocation count you could instrument the code that allocates.
        const memoryDeltaBytes =
            heapTotalAfter - heapTotalBefore +
            (allocCountAfter - allocCountBefore) * 128; // rough estimate

        console.log(`[profile] ${fn.name} – time: ${(performance.now() - start).toFixed(2)} ms, ` +
                    `memory Δ: ${Math.round(memoryDeltaBytes)} B, ` +
                    `${enableAllocs ? allocCountAfter - allocCountBefore : 'N/A'} allocations`);
    }
}

// --------------------------------------------------------------------------

/**
 * Example usage:
 *
 * function expensiveWork(n: number): string {
 *   const arr = new Array(n).fill('x');
 *   return JSON.stringify(arr);
 * }
 *
 * const { timeMs, memoryDeltaBytes } = profile(expensiveWork, 100_000);
 * console.log(`Execution took ${timeMs.toFixed(2)} ms`);
 */
```

**How it works**

| Step | What happens |
|------|--------------|
| **Timing** | `performance.now()` gives a precise timestamp before/after the call. |
| **Memory delta** | The V8 snapshot (`heapTotal`) is captured *before* and *after*. The difference approximates memory allocated during execution (exact per‑allocation counts require instrumentation). |
| **Allocations count** | `v8stats.enable({ mode: 'alloc' })` turns on allocation tracing; `getAllocationCount()` returns the number of allocations since profiling started. This value is only meaningful when enabled via a flag (`enableAllocs`). |
| **Result** | Returns `{ timeMs, memoryDeltaBytes }`. When allocation counting is active an extra field `allocationsCount` appears (otherwise omitted). |

> **Note:** In Node ≥ 18 you can also use the built‑in `perf_hooks.memoryUsage()` to get RSS (`mem.rss`) but it does not expose per‑allocation counts. The V8 snapshot is currently the most straightforward way.

