	"flag"
	"fmt"
	"os"
	"runtime"
	"time"

	// Uncomment if you need a more precise per‑allocation counter:
	// "github.com/shirou/gopsutil/mem"
)

var enableProfiling = flag.Bool("profile", false, "enable detailed allocation profiling")

func profiled(fn func(), args ...any) (timeMs float64, memDeltaBytes int64, allocCount int) {
	if !*enableProfiling {
		// Simple fallback: just time and memory delta.
		start := time.Now()
		result := fn()
		timeMs = time.Since(start).Milliseconds()
		memDeltaBytes = 0
		return
	}

	defer func() {
		if r := recover(); r != nil { // handle panics gracefully
			fmt.Printf("panic in profiled function: %v\n", r)
		}
	}()

	startTime := time.Now()

	var allocBefore, allocAfter int64

	switch runtime.GOARCH {
	case "amd64":
		runtime.SetMemProfileRate(1) // default rate; adjust as needed
		defer func() { fmt.Println(runtime.ReadMemProfile(os.Stdout)) }()
		fallthrough
	default:
