		if err := runtime.EnableAllocSample(true); err != nil {
			fmt.Fprintln(os.Stderr, "failed to enable allocation sampling:", err)
			return
		}
		defer func() { fmt.Println(runtime.ReadMemProfile(os.Stdout)) }()

		allocBefore = runtime.MemProfile.AllocCount()
	}

	result := fn()

	timeMs = time.Since(startTime).Milliseconds()

