		allocAfter = runtime.MemProfile.AllocCount()
		memDeltaBytes = int64(time.Now().Sub(startTime).Nanoseconds()) / 1_000_000 // ns → µs → B
		fmt.Printf("Allocations before: %d, after: %d\n", allocBefore, allocAfter)
	} else {
		memDeltaBytes = 0
	}

	return timeMs, memDeltaBytes, allocAfter - allocBefore
}

// --------------------------------------------------------------------------

func expensiveWork(n int) []byte {
	buf := make([]byte, n)
	for i := range buf {
		buf[i] = byte(i % 256)
	}
	return buf
}

func main() {
	flag.Parse()

