## 1️⃣ TypeScript (Node.js)

```ts
// benchmark.ts -------------------------------------------------------------
import { performance, PerformanceObserver } from "perf_hooks";

/**
 * Benchmarks `fn` – a function that takes no arguments and returns any value.
 *
 * @param fn          The callable to benchmark. Must be pure (no side‑effects)
 *                    or idempotent; otherwise the result may differ on each run.
 * @param iterations  Number of times to invoke `fn`.
 */
export async function benchmark<T>(
  fn: () => T,
  iterations = 10000
): Promise<{
  p50: number;
  p95: number;
  p99: number;
}> {
  const results: number[] = []; // recorded wall‑clock ms

  // PerfHooks observer collects timestamps before/after each run.
  const obs = new PerformanceObserver((items) => {
    items.getEntries().forEach((entry) => {
      results.push(entry.duration);
    });
  });

  obs.observe({ entryTypes: ["measure"], durationBucketSize: 1, buffered: true });

  // Run the function many times; use a deterministic seed so each run is
  // reproducible (optional but useful for CI).
  const rng = Math.random;
  for (let i = 0; i < iterations; ++i) {
    const start = performance.now();
    fn(); // invoke target
    const end = performance.now();

    // Record the duration in ms.
    results.push(end - start);
  }

  obs.disconnect();

  // Sort and compute percentiles – simple linear interpolation for p50/95/99.
  results.sort((a, b) => a - b);

  function percentile(p: number): number {
    const idx = (p / 100) * (results.length - 1);
    const lower = Math.floor(idx);
    const upper = Math.ceil(idx);
    if (lower === upper) return results[lower];
    // linear interpolation
    const t = idx - lower;
    return results[lower] + t * (results[upper] - results[lower]);
  }

  return {
    p50: percentile(50),
    p95: percentile(95),
    p99: percentile(99)
  };
}

// -----------------------------------------------------------------------
// Example usage ---------------------------------------------------------
if (require.main === module) {
  // A tiny dummy function to illustrate – replace with your own.
  const heavyWork = () => {
    let sum = 0;
    for (let i = 0; i < 1_000_000; ++i) {
      sum += Math.random();
    }
    return sum;
  };

  benchmark(heavyWork, 20000).then((stats) => {
    console.log("=== Benchmark Results ===");
    console.log(`p50 : ${stats.p50.toFixed(3)} ms`);
    console.log(`p95 : ${stats.p95.toFixed(3)} ms`);
    console.log(`p99 : ${stats.p99.toFixed(3)} ms`);
  });
}
```

