from typing import Callable, Any

def benchmark(
    fn: Callable[[], Any],
    iterations: int = 10000,
) -> dict:
    """
    Benchmarks `fn` – a callable that takes no arguments and returns any value.
    Returns a dict with p50, p95, p99 latencies (seconds).
    """
    results = []

    for _ in range(iterations):
        start = time.perf_counter()
        fn()                     # call target
        end = time.perf_counter()
        results.append(end - start)   # duration in seconds

    # Sort and compute percentiles using statistics module.
    sorted_res = sorted(results)
    def percentile(p: float) -> float:
        idx = (p / 100.0) * (len(sorted_res) - 1)
        lo, hi = int(idx), int(idx) + 1
        if lo == hi:
            return sorted_res[lo]
        # linear interpolation between lower and upper bucket
        t = idx - lo
        return sorted_res[lo] + t * (sorted_res[hi] - sorted_res[lo])

    p50 = percentile(50)
    p95 = percentile(95)
    p99 = percentile(99)

    return {"p50": round(p50, 6), "p95": round(p95, 6), "p99": round(p99, 6)}

