```ts
// detect-leak.ts -------------------------------------------------------------
import { connect } from 'chrome-remote-interface';
import fs from 'fs';

/**
 * Takes a heap snapshot (binary) and returns an object where each key is the
 * object's id and its value is the size in bytes.
 */
function parseSnapshot(snapshotBuffer: Buffer): Record<string, number> {
  const json = JSON.parse(snapshotBuffer.toString());
  // Chrome DevTools Protocol uses `snapshot` → `objects` → `[{"id":..., "size":...}]`
  return Object.fromEntries(
    json[0]?.results?.flatMap((obj: any) => [
      [obj.id, obj.size],
    ])
  );
}

/**
 * Runs a small operation that should allocate memory (e.g., create many objects).
 */
async function runOperation(): Promise<void> {
  // Simple allocation loop – adjust `N` to see more impact.
  const N = 10_000; // increase for clearer leak detection
  let i = 0;
  while (i < N) {
    // Allocate a large object just once per iteration and then discard it.
    const obj: any = { value: i };
    // Force GC to make sure the engine really creates new objects.
    await new Promise((r) => setTimeout(r, 1));
    i++;
  }
}

/**
 * Main driver – takes two snapshots (before/after), compares them and prints diff.
 */
async function detectLeak() {
  const BEFORE_ID = 'snapshot-before.json';
  const AFTER_ID   = 'snapshot-after.json';

  // -----------------------------------------------------------------------
  // STEP 1 – Take a baseline snapshot before the operation
  console.log('🔎 Taking baseline heap snapshot (before)');
  await new Promise((resolve) => setTimeout(resolve, 500)); // give some time for V8 to settle

  const client = await connect();
  try {
    const { memory: { takeHeapSnapshot } } = await client;
    const buffer = await takeHeapSnapshot();   // returns a Buffer
    fs.writeFileSync(BEFORE_ID, buffer);
    console.log('✅ Baseline snapshot saved →', BEFORE_ID);
  } finally {
    await client.close();
  }

  // -----------------------------------------------------------------------
  // STEP 2 – Run the code that may leak memory
  console.log('\n🚀 Running operation …');
  await runOperation();

  // -----------------------------------------------------------------------
  // STEP 3 – Take a second snapshot after the operation
  console.log('✅ Taking heap snapshot (after)');
  const clientAfter = await connect();
  try {
    const { memory: { takeHeapSnapshot } } = await clientAfter;
    const bufferAfter = await takeHeapSnapshot();   // returns Buffer
    fs.writeFileSync(AFTER_ID, bufferAfter);
    console.log('✅ After‑snapshot saved →', AFTER_ID);
  } finally {
    await clientAfter.close();
  }

  // -----------------------------------------------------------------------
  // STEP 4 – Compare the two snapshots and report differences
  const before = parseSnapshot(fs.readFileSync(BEFORE_ID));
  const after  = parseSnapshot(fs.readFileSync(AFTER_ID));

  console.log('\n🔎 Heap‑snapshot comparison:');
  let totalDiffBytes = 0;
  for (const [id, size] of Object.entries(after)) {
    // If the same id exists in both snapshots we can compare directly.
    const beforeSize = before[id];
    if (beforeSize !== undefined) {
      const diff = size - beforeSize;
      if (diff > 0) totalDiffBytes += diff;   // new allocation
      console.log(`ID ${id.padEnd(20)}: before=${beforeSize}B, after=${size}B → Δ${diff}B`);
    } else {
      // New object that never appeared in the baseline.
      console.warn(`🚨 NEW ID ${id.padEnd(20)}: size=${size}B (not present before)`);
    }
  }

  if (totalDiffBytes > 0) {
    console.log(
      `\n⚠️ Total new allocation ≈ ${totalDiffBytes.toLocaleString()} bytes – possible memory leak!`
    );
  } else {
    console.log('\n✅ No unexpected allocations detected.');
  }
}

// Run the detection routine
detectLeak().catch((e) => {
  console.error('❌ Error:', e);
});
```

#### How it works

| Step | What happens |
|------|--------------|
| **Baseline snapshot** (`takeHeapSnapshot`) | V8 writes a JSON‑encoded heap profile to disk (binary Buffer). The file contains every live object with its `id` and `size`. |
| **Run operation** | Your code runs – in this example it creates ~10 k objects. In real usage you would replace the loop with whatever workload you suspect may leak. |
| **After snapshot** | Same API call again, giving a second profile. |
| **Diff** | Compare IDs present after vs before; any new ID → new allocation. The size difference tells you how much memory was added per leaked object (or per whole leak). |

> **Tip:** In production you may want to run the operation under `node --expose-gc` and trigger a manual GC (`gc()`) between snapshots so that V8 can’t reuse old allocations.

