### Code (`detect_leak.py`)

```python
#!/usr/bin/env python3
"""
Detect heap leaks by taking two snapshots and comparing the allocation stacks.
Works with Python ≥3.7 (requires `tracemalloc`).
"""

import tracemalloc
import gc
import os
from pathlib import Path

# ----------------------------------------------------------------------
def take_snapshot(name: str) -> None:
    """Take a snapshot, store it as JSON lines in <name>.jsonl."""
    tracemalloc.start()
    # Take a sample (counts allocations)
    snapshots = tracemalloc.take_snapshot()
    # Keep only the top 20 frames for readability
    top_stats = snapshots.statistics('lineno')[:20]
    Path(name).with_suffix('.jsonl').write_text(
        "\n".join(f'{" ".join(str(stat))}' for stat in top_stats)
    )
    tracemalloc.stop()

def load_snapshot(path: str) -> dict:
    """Parse a JSON‑lines snapshot into a dict mapping frame → count."""
    from collections import defaultdict
    counts = defaultdict(int)
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            # Example line: '  File ".../leak.py", line 42, in run_operation'
            parts = line.strip().split()
            if len(parts) >= 3 and parts[0].startswith('  File'):
                counts[parts[1]] += 1
    return dict(counts)

def compare_snapshots(before: Path, after: Path):
    before_counts = load_snapshot(str(before))
    after_counts   = load_snapshot(str(after))

    total_new_bytes = 0
    print("\n🔎 Heap‑snapshot comparison:")
    for frame, cnt_after in after_counts.items():
        if frame in before_counts:
            cnt_before = before_counts[frame]
            diff_cnt = cnt_after - cnt_before
            # Approximate size: average object size (≈64 B) * count difference.
            approx_size = 64 * diff_cnt
            total_new_bytes += approx_size
            print(f'Frame {frame}: before={cnt_before}, after={cnt_after} → Δ{diff_cnt}× (~{approx_size:,}B)')
        else:
            # New frame – never seen before, likely a leak.
            print(f'🚨 NEW FRAME {frame!r}: count={after_counts[frame]} (not present before)')

    if total_new_bytes > 0:
        print(f"\n⚠️ Total new allocation ≈ {total_new_bytes/1024**2:.3f} MiB – possible memory leak!")
    else:
        print("\n✅ No unexpected allocations detected.")

def run_workload():
    """Placeholder workload that we suspect may allocate."""
    # Example: create a large list of objects and then discard.
    N = 50_000
    data = [i for i in range(N)]
    # Force GC to make sure the engine really creates new objects.
    gc.collect()

def main() -> None:
    before_path = Path("before_snapshot.jsonl")
    after_path   = Path("after_snapshot.jsonl")

    print("\n🔧 Starting heap‑leak detection …\n")
    take_snapshot(str(before_path))
    run_workload()
    take_snapshot(str(after_path))

    compare_snapshots(before_path, after_path)

if __name__ == "__main__":
    main()
```

#### How it works

| Step | What happens |
|------|--------------|
| **`take_snapshot(name)`** | Starts `tracemalloc`, runs a short workload (here just creating a big list), then writes the top allocation frames to `<name>.jsonl`. Each line contains *file → line → function* plus the count of allocations. |
| **Run workload** (`run_workload`) | Replace this stub with whatever code you suspect may leak memory. In production you would call your real function or script inside `run_workload()`. |
| **Second snapshot** | Same as before, but after the workload completes. |
| **Comparison** | Reads both JSON‑line files, counts allocations per frame, computes a rough size (average object ≈ 64 B), and prints which frames grew or are new. The total summed size gives you an idea of how much memory was leaked. |

> **Why the approximation?**  
> `tracemalloc` only records *counts*, not exact sizes per frame, so we use a heuristic (average object ≈ 64 B). For more precise numbers you could dump raw allocation objects via `objgraph` or integrate Chrome’s D‑TP API as shown for TypeScript.

